  var AUD = {
    ctx: null, osc: null, gain: null, lfo: null,
    start: function () {
      if (this.ctx) { if (this.ctx.state === 'suspended') this.ctx.resume(); return true; }
      var AC = WIN.AudioContext || WIN.webkitAudioContext;
      if (!AC) return false;
      try {
        var ctx = new AC();
        var osc = ctx.createOscillator();
        var gain = ctx.createGain();
        var lfo = ctx.createOscillator();
        var lfoGain = ctx.createGain();
        osc.type = 'sine';
        osc.frequency.value = 80;
        lfo.type = 'sine';
        lfo.frequency.value = 8;
        lfoGain.gain.value = 14;
        lfo.connect(lfoGain);
        lfoGain.connect(osc.frequency);
        gain.gain.value = 0;
        osc.connect(gain);
        gain.connect(ctx.destination);
        osc.start(); lfo.start();
        this.ctx = ctx; this.osc = osc; this.gain = gain; this.lfo = lfo;
        return true;
      } catch (e) { return false; }
    },
    update: function (env, freq) {
      if (!this.ctx || !S.audio) return;
      var t = this.ctx.currentTime;
      this.osc.frequency.setTargetAtTime(52 + clamp(freq, 0.5, 25) * 6.5, t, 0.08);
      this.lfo.frequency.setTargetAtTime(clamp(freq, 1, 18), t, 0.15);
      this.gain.gain.setTargetAtTime(S.on ? env * 0.11 * S.pow / 100 : 0, t, 0.05);
    },
    stop: function () {
      if (!this.ctx) return;
      try { this.gain.gain.setTargetAtTime(0, this.ctx.currentTime, 0.05); } catch (e) { /* noop */ }
    }
  };

  /* =========================================================
   * 4b. 语音与振动音（VOC）
   *
   * 一条音频总线管三件事：TTS 语音、振动音、上面那个正弦声波模拟（AUD 原样保留）。
   *
   * 三条链路：
   *   ① TTS 语音  —— 心声/台词的实音。走本机转发拿音频（浏览器直连中转会被跨域拦，实测确认）
   *   ② 振动音    —— 纯 Web Audio 实时合成，频率与强度直接由装置参数驱动，零网络零费用
   *
   * 振动音为什么不用 TTS：频率一变声音必须立刻跟着变，TTS 是固定片段，来不及。
   * 手机小扬声器放不出 100Hz 以下的低频，所以基频×3 取谐波、再垫一层真实低频，
   * 靠大脑的音高知觉补出"低沉嗡鸣"。参数依据见 工具-TTS试音台.html。
   * 吸吮式不是震（上游 S.dev='suck'）：那档声音更闷、更贴，所以低通压低、谐波减弱。
   * ======================================================= */
  var VOC = (function () {
    var ctx = null, bus = null, ana = null, anaBuf = null;
    var bzOn = false, bzLast = 0, bzNodes = null;
    var cache = {}, cacheDb = null, dbTried = false;
    var seq = 0, cur = null, curUrl = '', curSrc = null;

    function AC() { return WIN.AudioContext || WIN.webkitAudioContext; }
    function isSuck() { return String(S.dev || '').indexOf('suck') === 0; }

    function ensure() {
      if (ctx) { if (ctx.state === 'suspended') { try { ctx.resume(); } catch (e) { /* noop */ } } return true; }
      var C = AC();
      if (!C) return false;
      try {
        ctx = new C();
        bus = ctx.createGain();
        bus.gain.value = 0.9;
        ana = ctx.createAnalyser();
        ana.fftSize = 1024;
        ana.smoothingTimeConstant = 0.78;
        anaBuf = new Uint8Array(ana.fftSize);
