        return true;
      } catch (e) { ctx = null; return false; }
    }

    /* ---- 振动音 ---- */
    function makeNoise() {
      var len = Math.max(1, Math.floor(ctx.sampleRate * 1.2));
      var buf = ctx.createBuffer(1, len, ctx.sampleRate);
      var d = buf.getChannelData(0);
      for (var i = 0; i < len; i++) d[i] = Math.random() * 2 - 1;
      var s = ctx.createBufferSource();
      s.buffer = buf; s.loop = true;
      return s;
    }
    function bzBuild() {
      if (bzNodes) return;
      var oscA = ctx.createOscillator(), oscB = ctx.createOscillator(), oscS = ctx.createOscillator();
      oscA.type = 'sawtooth'; oscB.type = 'sawtooth'; oscS.type = 'sine';
      var gD = ctx.createGain(), gS = ctx.createGain(), gT = ctx.createGain();
      var lp = ctx.createBiquadFilter(), nz = makeNoise(), bp = ctx.createBiquadFilter(), ng = ctx.createGain();
      oscA.connect(gD); oscB.connect(gD); oscS.connect(gS);
      gD.connect(lp); gS.connect(lp);
      nz.connect(bp); bp.connect(ng); ng.connect(lp);
      lp.connect(gT); gT.connect(bus);
      gT.gain.value = 0.0001;
      oscA.start(); oscB.start(); oscS.start(); nz.start();
      bzNodes = { oscA: oscA, oscB: oscB, oscS: oscS, gD: gD, gS: gS, gT: gT, lp: lp, ng: ng, bp: bp };
    }
    function bzHz() {
      var v = clamp(S.freq, 1, 100) / 100;
      return 30 * Math.pow(220 / 30, v);
    }
    function bzApply() {
      if (!bzNodes || !ctx) return;
      var t = ctx.currentTime, f = bzHz(), u = clamp(S.pow, 0, 100) / 100, suck = isSuck();
      bzNodes.oscA.frequency.setTargetAtTime(f * 3, t, 0.04);
      bzNodes.oscB.frequency.setTargetAtTime(f * 3.02, t, 0.04);   // 2% 失谐，出"活电机"的拍频
      bzNodes.oscS.frequency.setTargetAtTime(f, t, 0.05);
      // 吸吮式：低通压低、噪声更湿，听感从"嗡"变成"含住又松开"
      bzNodes.lp.frequency.setTargetAtTime(suck ? 1500 : 4200, t, 0.08);
      bzNodes.ng.gain.setTargetAtTime(suck ? (0.08 + u * 0.34) : (0.04 + u * 0.26), t, 0.12);
      bzNodes.bp.frequency.setTargetAtTime((suck ? 420 : 1100) + u * (suck ? 900 : 1900), t, 0.12);
      bzNodes.bp.Q.setTargetAtTime(1.0 + u * 1.4, t, 0.12);
      bzNodes.gD.gain.setTargetAtTime(suck ? (0.22 + u * 0.20) : (0.44 + u * 0.30), t, 0.12);
      bzNodes.gS.gain.setTargetAtTime(suck ? (1.0 - u * 0.15) : (0.90 - u * 0.20), t, 0.12);
