    function tick(env) {
      if (!S.voice || S.voice === 'off') { if (bzOn) bzStop(); return; }
      if (!ensure()) return;
      if (bzMode() && S.on) {
        if (!bzOn) bzStart();
        if (Date.now() - bzLast > 120) {     // 参数不必每帧写，AudioParam 本身就是平滑的
          bzLast = Date.now();
