        }
      } else if (bzOn) {
        bzStop();
      }
    }

    function bzMode() { return S.voice === 'buzz' || S.voice === 'both'; }
    function voiceOn() { return S.voice === 'tts' || S.voice === 'both'; }

    /* ---- 音频缓存（同一句不重复花钱） ---- */
    function openDb() {
      if (dbTried) return Promise.resolve(cacheDb);
