      return new Promise(function (resolve) {
        if (typeof indexedDB === 'undefined') return resolve(null);
        var settled = false;
        function done(v) { if (!settled) { settled = true; resolve(v); } }
        var req;
        try { req = indexedDB.open('toylink_voice', 1); } catch (e) { return done(null); }
        req.onupgradeneeded = function () {
          var d = req.result;
          if (!d.objectStoreNames.contains('v')) d.createObjectStore('v', { keyPath: 'id' });
        };
        req.onsuccess = function () { cacheDb = req.result; done(req.result); };
        req.onerror = function () { done(null); };
        req.onblocked = function () { done(null); };
        setTimeout(function () { done(null); }, 3500);
      });
