      setTimeout(function () { paintAudioList(); }, 160);
      return openDb().then(function (d) {
        if (!d) return;
        try { d.transaction('v', 'readwrite').objectStore('v').put(rec); } catch (e) { /* noop */ }
      });
    }

    /* ---- 运行日志 ----
       面板里看不到 console，排错全靠这一栏。记的是"这一句有没有真的发出去、
       打到哪、几毫秒、多大、缓存中没中"，以及失败的分岔在哪一层。 */
    var LOG = [];
    var LOG_MAX = 60;
