      var d = new Date();
      var t = pad2(d.getHours()) + ':' + pad2(d.getMinutes()) + ':' + pad2(d.getSeconds());
      LOG.push({ t: t, m: String(msg), c: cls || '' });
      if (LOG.length > LOG_MAX) LOG.shift();
      if (S.voiceLog) { try { console.log('[TOY·LINK 语音] ' + msg); } catch (e) { /* noop */ } }
      renderLog();
    }
    function renderLog() {
      var box = $('#vs-log');
      var tag = $('#vs-log-tag');
      if (tag) tag.textContent = LOG.length ? (LOG.length + ' 条') : '';
      if (!box) return;
      if (!LOG.length) { box.innerHTML = '<div class="lgdim">（还没有记录）</div>'; return; }
