    function nBytes(s) {
      try { return new TextEncoder().encode(String(s)).length; } catch (e) { return String(s).length * 3; }
    }

    /* ---- 合成：两种传输方式
     *
     * 经作者中转：面板带自己的官方 Key，由中转转发到官方端点（它不持有任何 Key）。
     * direct 直连中转（默认）：URL + 令牌都填在面板里，令牌跟着聊天变量走。
     *   —— 少了本机脚本这一步，但令牌会随变量进聊天文件，也会明文落在页面上。
     *   中转自己开了跨域（Access-Control-Allow-Origin）时，直连才跑得通。
     *
     * 两条路的请求体完全一样，差别只在打到哪、谁来带鉴权头。 ---- */
    function buildHeaders(c) {
      var h = { 'Content-Type': 'application/json' };
      /* 经作者的中转服务器转发的是"一份正常的官方请求"，
         所以走官方的鉴权头与请求体，不带 x-toylink-* 那套旧的本机脚本协议头
         （服务器根本不认那些头，带上等于多送一份没人看的元数据）。 */
      if (c.authstyle === 'x-api-key' && c.key) h['x-api-key'] = c.key;
      else if (c.authstyle === 'raw' && c.key) h['Authorization'] = c.key;
      else if (c.authstyle !== 'none' && c.key) h['Authorization'] = 'Bearer ' + c.key;
      if (c.model && !c.noModelHdr) h[c.modelHdr] = c.model;
