          var ex = JSON.parse(c.extraRaw) || {};
          Object.keys(ex).forEach(function (k) { h[k] = String(ex[k]); });
        } catch (e) { /* 非法 JSON 由界面提示，这里忽略 */ }
      }
      return h;
    }

    function cfgNow() {
      var p = PLATFORMS[S.ttsPlatform] || PLATFORMS.fish;
      var direct = !forwarding();
      /* endpoint 是"这一发到底打到哪个地址"，一次算清楚，后面 buildHeaders、
         日志、报错文案全用它，免得各处各判一次判出不一致。
           浏览器直打 → 用户填的地址（官方或第三方中转）
