        afUrl: af,
        afHealth: afHealth(),
        endpoint: direct ? (S.ttsTarget || '') : af,
        key: S.ttsKey || '',
        authstyle: S.ttsAuth || 'bearer',
        model: S.ttsModel || '',
        modelHdr: S.ttsModelHdr || 'model',
        /* 音色字段名与音色字段是否发 model，都随平台走：
           Fish 用 reference_id + model 头；OpenAI 用 voice 字段、不要 model 头。 */
        voiceField: (S.ttsPlatform === 'custom') ? (S.ttsRefField || 'reference_id') : p.voiceField,
        /* 平台级别"不发 model 头"：OpenAI 协议里模型在 body 里；MiniMax 也是 ——
           官方只要 Authorization + Content-Type，多一个 model 头只会给网关添判断余地。
           作者中转那条路也一样不带（它转发的是同一份官方请求）。 */
        noModelHdr: (S.ttsPlatform === 'openai' || S.ttsPlatform === 'minimax') ? true : !!S.ttsNoModelHdr,
        extraRaw: S.ttsExtraHdrs || '',
        latency: S.ttsLatency || 'low',
        format: S.ttsFormat || 'mp3',
        speed: S.ttsSpeed || 1,
        langBoost: !!S.ttsLangBoost,
        plat: S.ttsPlatform || 'fish'
      };
    }
    function buildReqBody(c, text, vv) {
      var p = PLATFORMS[c.plat] || PLATFORMS.fish;
      return p.req(c, text, vv);
    }

    /* ---------- MiniMax 的 hex 音频解包 ----------
       MiniMax T2A 返回 JSON：{ data: { audio: "<hex>", status: 2 },
                                base_resp: { status_code: 0, status_msg: "success" } }
       音频是十六进制字符串，得转回字节数组才喂得进播放器。
       三个容易踩的点：
         ① base_resp.status_code 才是成败判据 —— HTTP 200 也可能失败；
         ② data 可能是 null（官方文档明说要判空）；
         ③ 音频很长时 hex 串能到几十万字符，必须用 typed array 逐字节填，
            别用 push/concat（那样会慢到卡住界面）。 */
    function hexToBytes(hex) {
      var s = String(hex || '').replace(/[\s\r\n]+/g, '');
      if (s.length < 2) return null;
      if (s.length % 2 !== 0) s = s.slice(0, -1);        // 奇数个字符：丢掉最后一个
      var n = s.length >> 1;
      var out = new Uint8Array(n);
      for (var i = 0; i < n; i++) {
        var b = parseInt(s.substr(i * 2, 2), 16);
        if (isNaN(b)) { vlog('hex 音频里有非十六进制字符（第 ' + (i * 2) + ' 个字符），已中断', 'err'); return null; }
        out[i] = b;
      }
      return out;
    }

    function parseMinimaxJSON(tx, ms) {
      var j;
      try { j = JSON.parse(String(tx || '')); }
      catch (e) {
        vlog('MiniMax 回的 JSON 解析不了：' + esc4(String(tx || '').slice(0, 160)), 'err');
        throw new Error('MiniMax 回的 JSON 解析不了');
      }
      var br = j.base_resp || {};
      if (br.status_code !== 0) {
        var how = br.status_code === 1004 ? ' ← 鉴权失败，检查 API key'
          : br.status_code === 1002 ? ' ← 触发限流（并发/配额）'
            : br.status_code === 1039 ? ' ← TPM 限流：一分钟内字符数超了'
              : br.status_code === 1001 ? ' ← 上游超时'
                : br.status_code === 1042 ? ' ← 无效字符超过 10%，被拒'
                  : br.status_code === 2013 ? ' ← 入参不合法（模型名/音色 ID 对不上？）' : '';
        vlog('MiniMax 返回失败 ' + br.status_code + '：' + esc4(String(br.status_msg || '')) + how, 'err');
        throw new Error('MiniMax ' + br.status_code + '：' + String(br.status_msg || ''));
      }
      var d = j.data;
      if (!d) { vlog('MiniMax 回了 status_code=0 但没有 data（官方文档说这种情况要判空）', 'err'); throw new Error('MiniMax 没有返回音频数据'); }
      var bytes = hexToBytes(d.audio);
      if (!bytes || !bytes.length) { vlog('MiniMax 的 data.audio 是空的或不是合法 hex', 'err'); throw new Error('MiniMax 没有返回可用音频'); }
      var ei = j.extra_info || {};
      vlog('MiniMax 解包完成 ' + Math.round(bytes.length / 1024 * 10) / 10 + ' KB · ' + (ms || '?') + 'ms'
        + (ei.audio_length ? ' · 音频 ' + (Math.round(ei.audio_length / 100) / 10) + ' 秒' : '')
        + (ei.usage_characters ? ' · 计费 ' + ei.usage_characters + ' 字符' : ''), 'ok');
      return bytes.buffer;
    }

    /* ---------- 送去合成前，标记怎么处理 ----------
       多数平台（Fish、OpenAI）不认识方括号标记，念出来会变成噪音 —— 一律删掉。
       MiniMax 是例外：它认「（全角括号）」的插词，而且官方只认固定一张表。
       不在表里的（[whispering]、[颤抖] 这类）如果原样转过去会被当正文念出来，
       所以只转换认识的，其余一律删 —— 宁可少一点语气，也不要念出噪音。
       另外这张表只在 speech-2.8 系列上生效，换别的模型全删。 */
    var MM_FX = {
      '气声': 'breath', '喘息': 'pant', '抽气': 'gasps', '吸气': 'inhale', '呼气': 'exhale',
      '笑': 'laughs', '轻笑': 'chuckle', '咳嗽': 'coughs', '清嗓': 'clear-throat',
      '闷哼': 'groans', '抽鼻子': 'sniffs', '叹气': 'sighs', '鼻音': 'snorts',
      '打嗝': 'burps', '咂嘴': 'lip-smacking', '哼': 'humming', '嘶声': 'hissing',
      '沉吟': 'emm', '喷嚏': 'sneezes'
    };
    /* 官方支持的英文标记原样可用，一并放进白名单 */
    ['laughs', 'chuckle', 'coughs', 'clear-throat', 'groans', 'breath', 'pant',
      'inhale', 'exhale', 'gasps', 'sniffs', 'sighs', 'snorts', 'burps',
      'lip-smacking', 'humming', 'hissing', 'emm', 'sneezes'].forEach(function (k) {
      MM_FX[k] = k;
    });

    function stripMarks(s) { return String(s == null ? '' : s).replace(/\[[^\]]*\]\s*/g, ''); }

    function miniMarks(s) {
      var mdl = String(S.ttsModel || '');
      if (mdl.indexOf('2.8') < 0) return stripMarks(s);   // 老模型不认插词，全删
      var out = String(s == null ? '' : s).replace(/\[([^\]]+)\]/g, function (_, inner) {
        var key = String(inner).trim();
        var hit = MM_FX[key] || MM_FX[key.toLowerCase()];
        return hit ? '（' + hit + '）' : ' ';
      });
      /* 标记原来占着位置，替换掉之后会留下空档 —— 行首最明显。
         还有一处：台词库里标记与正文之间本来有一个空格（"[breath] 不行……"），
         换成全角插词后那个空格吊在「）」后面，念出来是多一次停顿。 */
      return out
        .replace(/）[ \t\u3000]+/g, '）')
        .replace(/^[ \t\u3000]+/, '').replace(/[ \t\u3000]{2,}/g, ' ').trim();
    }

    /* 一份台词送去合成前的清洗：去掉方括号标记（MiniMax 换成括号插词），多行并成一句 */
    function speakText(plat, text) {
      var one = (plat === 'minimax') ? miniMarks : stripMarks;
      var s = String(text || '').split(/[\r\n]+/).map(function (l) { return one(l).trim(); })
        .filter(Boolean).join('，');
      if (!s) s = one(text).trim();
      return s;
    }

    function synth(text, voice) {
      var c = cfgNow();
      if (!c.target) { vlog('没填合成地址', 'err'); return Promise.reject(new Error('没填合成地址')); }
      if (!c.endpoint) { vlog('缺合成地址', 'err'); return Promise.reject(new Error('先填「合成地址」')); }
      /* 经作者中转时，实际地址不是"用户填的"而是从官方地址映射出来的 ——
         映射不出来说明这条路走不通，要说清是地址不认。 */
      if (c.via === 'af' && !c.afUrl) {
        vlog('作者中转不认这个官方地址：' + c.target, 'err');
        return Promise.reject(new Error('作者中转只转发 Fish 与 MiniMax 国际站的官方端点，当前地址不在其中'));
      }
      if (c.authstyle !== 'none' && !c.key) {
        vlog(c.via === 'af' ? '经作者中转需要填官方 API Key' : '这一档要填令牌', 'err');
        return Promise.reject(new Error(c.via === 'af'
          ? '经作者中转要用你自己的官方 API Key，先填「官方 API Key」'
          : '先填令牌（或把鉴权改成「不带」）'));
      }
      var url = c.endpoint;
      var vv = voice || S.ttsVoice;
      /* 多行台词原样送去合成（模型会按行/句切分），但每行的情绪标记要先处理掉。
         具体怎么处理见上面 speakText —— MiniMax 换全角括号插词、其余平台删掉。 */
      var speak = speakText(c.plat, text);
      var k = vkey(text, vv);
      var t0 = Date.now();
      vlog('请求 ' + String(text).slice(0, 34) + ' · ' + nBytes(speak) + ' 字节 · '
        + (c.via === 'af' ? '经作者中转' : '直连')
        + (vv ? ' · 音色 ' + vv : ' · 默认音色'), 'hi');
      return cached(k).then(function (hit) {
        if (hit && hit.blob) {
          vlog('缓存命中 ' + k + '（' + fmtKB(hit.blob.size) + '），未联网', 'ok');
          return { cached: true, id: k, blob: hit.blob };
        }
        vlog('缓存未命中，开始联网合成…', 'step');
        // 请求体按平台生成：Fish 用 reference_id + 一堆调参，OpenAI 用 input + voice，两者字段名都不一样
        var body = buildReqBody(c, speak, vv);

        var ctl = (typeof AbortController !== 'undefined') ? new AbortController() : null;
        var timer = ctl ? setTimeout(function () { ctl.abort(); }, S.ttsTimeout) : null;
        var h = buildHeaders(c);

        /* 把"实际发出去的东西"记进日志。
           排错时缺的往往就是这个：光看"请求失败"没用，得看到打到哪个 URL、
           带了哪些头、有没有带鉴权。令牌只记"有没有带"，不记值。 */
        var authHdr = h['Authorization'] ? 'Authorization（' + (h['Authorization'].indexOf('Bearer ') === 0 ? 'Bearer' : '裸值') + '）'
          : (h['x-api-key'] ? 'x-api-key' : '无');
        var hdrNames = Object.keys(h).filter(function (k) {
          return k !== 'Authorization' && k !== 'x-api-key';
        }).join(', ');
        vlog('  → ' + (c.via === 'af' ? 'AF' : c.transport.toUpperCase()) + ' ' + url, 'step');
        vlog('  → 鉴权头：' + authHdr + ' ｜ 其余头：' + (hdrNames || '无'), 'step');
        vlog('  → 请求体字段：' + Object.keys(body).join(', ') + '（' + nBytes(JSON.stringify(body)) + ' 字节）', 'step');
        var lines = String(text || '').split(/[\r\n]+/).filter(function (x) { return x.trim(); });
        if (lines.length > 1) vlog('  → 多行台词 ' + lines.length + ' 行，合成时并成一句（去掉标记）', 'step');

        return fetch(url, {
          method: 'POST', headers: h, body: JSON.stringify(body),
          signal: ctl ? ctl.signal : undefined,
          /* 不带酒馆的 Cookie，也不带网页地址：中转与官方都不需要这两样，
             送过去只是白送一份身份线索。作者中转那边同样不需要凭据型请求。 */
          credentials: 'omit', referrerPolicy: 'no-referrer'
        }).then(function (r) {
          if (timer) clearTimeout(timer);
          var ms = Date.now() - t0;
          /* 报错时把"这一发是谁回的"说准：直连是官方或第三方中转直接回的，
             经作者中转是中转回的（真正的上游错误它也会透传下来）。 */
          var who = (c.via === 'af') ? '作者中转' : '上游';
          if (!r.ok) {
            return r.text().then(function (tx) {
              var detail = String(tx || '').slice(0, 200);
              /* 402 是"官方那边的 API 余额/额度不够"。
                 Fish 特别注明：API credit 与平台 credit 是分开的两套 ——
                 网页版有额度，不代表 API 端口能用，这一点最容易误解。
                 而 s2.1-pro-free 是官方标称 $0 的同一个模型，所以先劝他换过去试。 */
              var isCredit = (r.status === 402) || /credit|balance|quota|insufficient/i.test(detail);
              var freeNow = String(S.ttsModel || '').indexOf('-free') >= 0;
              var how = (r.status === 401 || r.status === 403) ? ' ← 鉴权失败，检查令牌与鉴权方式'
                : r.status === 404 ? ' ← 路径不对，检查合成地址'
                  : r.status === 413 ? ' ← 请求体太大'
                    : r.status === 429 ? ' ← 触发限流（并发/配额），等几秒再试，不要连着重发'
                      : isCredit ? ' ← 官方说 API credit 不足'
                        : '';
              vlog(who + ' 回 ' + r.status + '（' + ms + 'ms）' + how + (detail ? ' · ' + detail : ''), 'err');
              if (isCredit) {
                vlog('  官方说明：API credit 与平台 credit 是分开的两套，'
                  + '网页版有额度不等于 API 端口能用；充值/查余额：'
                  + 'https://fish.audio/app/developers', 'err');
                if (c.plat === 'fish' && !freeNow) {
                  vlog('  现在用的是付费型号 ' + (S.ttsModel || '(空)') + '，'
                    + '把它改成 s2.1-pro-free 就是同一个模型的免费档，先拿它试通路。', 'hi');
                  toast('Fish 的 API 余额不足。模型先换成 s2.1-pro-free（同一个模型的免费档）再试', 7000);
                } else if (c.plat === 'fish' && freeNow) {
                  toast('官方回了余额不足 —— 免费档也被限了，得去官网看 API credit', 7000);
                }
              }
              throw new Error(who + '返回 ' + r.status + '：' + detail);
            }, function () {
              vlog(who + ' 回 ' + r.status + '（' + ms + 'ms）', 'err');
              throw new Error(who + '返回 ' + r.status);
            });
          }
          var ct = r.headers.get('content-type') || '';
          if (ct.indexOf('json') >= 0) {
            /* 有的平台就是回 JSON —— MiniMax 把音频塞在 data.audio 里、还是 hex 字符串。
               这类走各自的解析函数；其余情况照旧按"不是音频"报错。 */
            if (c.plat === 'minimax' || PLATFORMS[c.plat] && PLATFORMS[c.plat].resp === 'minimax') {
              return r.text().then(function (tx) { return parseMinimaxJSON(tx, ms); });
            }
            return r.text().then(function (tx) {
              vlog('上游回的是 JSON 不是音频：' + String(tx || '').slice(0, 160), 'err');
              throw new Error('上游不是音频：' + String(tx || '').slice(0, 200));
            });
          }
          return r.arrayBuffer().then(function (buf) {
            if (timer) clearTimeout(timer);
            /* 少数中转不带 content-type，直接把 JSON 当纯文本发回来。
               这里认一下：开头是 { 就先按 JSON 试，失败再当音频。 */
            if (c.plat === 'minimax' && buf && buf.byteLength > 2) {
              var head = new Uint8Array(buf, 0, 1);
              if (head[0] === 0x7B) {   // '{'
                try {
                  var txt = new TextDecoder('utf-8').decode(buf);
                  return parseMinimaxJSON(txt, ms);
                } catch (e) { /* 认错了，继续当音频处理 */ }
              }
            }
            var total = Date.now() - t0;
            var kb = buf ? Math.round(buf.byteLength / 1024 * 10) / 10 : 0;
            vlog('收到音频 ' + kb + ' KB · ' + total + 'ms · ' + (ct || '无类型'), 'ok');
            return buf;
          });
        }).then(function (buf) {
          if (!buf || !buf.byteLength) { vlog('拿到空音频', 'err'); throw new Error('拿到空音频'); }
          var blob = new Blob([buf], { type: guessMime(S.ttsFormat) });
          return store(k, blob, { text: text, model: S.ttsModel, voice: vv }).then(function () {
            return { cached: false, id: k, blob: blob };
          });
        }, function (e) {
          if (timer) clearTimeout(timer);
          var msg = (e && e.name === 'AbortError') ? '请求超时（' + S.ttsTimeout + 'ms）'
            : String((e && e.message) || e);
          if (/Failed to fetch|NetworkError|Load failed/i.test(msg)) {
            vlog(c.via === 'af'
              ? '连不上作者中转：检查网络，或换成「浏览器直打」再试。'
              : (isOfficial()
                ? '直连被拦：官方端点不给跨域头（CORS），浏览器一定拦下。'
                  + '把走法切到「作者的中转服务器」就能跑通。'
                : '直连被拦：这个地址没开跨域（CORS），或地址写错了。'), 'err');
          } else if (e && e.name !== 'AbortError') {
            vlog('请求失败：' + msg, 'err');
          }
          throw e;
        });
      });
    }

    /* ---- 播放 ---- */
    function play(blob, opts) {
      if (!blob) return;
      if (!ensure()) { toast('这个环境没有 Web Audio，放不了声音'); return; }
      try {
        if (cur) { try { cur.pause(); } catch (e) { /* noop */ } }
        // 上一条的音源节点断开：每播一句都新建一个接到总线上，不断开会越积越多
        if (curSrc) { try { curSrc.disconnect(); } catch (e) { /* noop */ } curSrc = null; }
        if (curUrl) { try { URL.revokeObjectURL(curUrl); } catch (e) { /* noop */ } }
        curUrl = URL.createObjectURL(blob);
        var el = new Audio(curUrl);
        cur = el;
        el.volume = clamp((opts && opts.vol != null ? opts.vol : S.voiceVol / 100), 0, 1);
        try {
          var src = ctx.createMediaElementSource(el);
          src.connect(bus);
          curSrc = src;
        } catch (e) { /* 某些环境接不了总线就退回原生播放 */ }
        var p = el.play();
        if (p && p.catch) p.catch(function () { /* 自动播放被挡，用户手动点 */ });
      } catch (e) { /* noop */ }
    }

    /* 说一句：先查缓存，没有就合成，然后播。voice 可指定音色 */
    function say(text, opts) {
      text = String(text || '').trim();
      if (!text || !voiceOn()) return Promise.resolve(null);
      var voice = (opts && opts.voice) || S.ttsVoice;
      var my = ++seq;
      if (my > 1) vlog('新的播放打断上一条（第 ' + my + ' 次）', 'warn');
      return synth(text, voice).then(function (r) {
        if (my !== seq) return null;      // 期间又来了新的一句，这条丢掉
        play(r.blob, opts);
        return r;
      }).catch(function (e) {
        var msg = (e && e.message) || String(e);
        if (my === seq) {
          // synth 里已经把细节记进日志了，这里只补一句"这一条最终没播出来"
          vlog('这一条没播出来：' + msg, 'err');
          toast('语音没出来：' + msg, 3200);
        }
        return null;
      });
    }
    /* 预热：把固定音集先合成好，之后就不占实时通道 */
    function warm(list) {
      if (!voiceOn() || !list || !list.length) return Promise.resolve(0);
      var n = 0, i = 0;
      vlog('开始预热 ' + list.length + ' 条（串行，间隔 260ms）', 'hi');
      return new Promise(function (resolve) {
        (function step() {
          if (i >= list.length) {
            vlog('预热结束：成功 ' + n + ' / ' + list.length + ' 条', n ? 'ok' : 'warn');
            return resolve(n);
          }
          synth(list[i++]).then(function () { n++; }, function () { /* noop */ }).then(function () {
            setTimeout(step, 260);        // 串行，避开中转的并发上限
          });
        })();
      });
    }
    function clearCache() {
      cache = {};
      return openDb().then(function (d) {
        if (!d) return;
        try { d.transaction('v', 'readwrite').objectStore('v').clear(); } catch (e) { /* noop */ }
      });
    }
    /* 缓存里所有的音频（合成记录就是它）。
       按时间倒序，新的在前 —— 试听时最关心的就是刚合成的那几条。 */
    function listAll() {
      return openDb().then(function (d) {
        if (!d) return [];
        return new Promise(function (resolve) {
          try {
            var r = d.transaction('v', 'readonly').objectStore('v').getAll();
            r.onsuccess = function () {
              var list = r.result || [];
              list.sort(function (a, b) { return b.at - a.at; });
              resolve(list);
            };
            r.onerror = function () { resolve([]); };
          } catch (e) { resolve([]); }
        });
      });
    }
    function getRec(id) {
      return openDb().then(function (d) {
        if (!d) return null;
        return new Promise(function (resolve) {
          try {
            var r = d.transaction('v', 'readonly').objectStore('v').get(id);
            r.onsuccess = function () { resolve(r.result || null); };
            r.onerror = function () { resolve(null); };
          } catch (e) { resolve(null); }
        });
      });
    }
    function cacheCount() {
      return openDb().then(function (d) {
        if (!d) return Object.keys(cache).length;
        return new Promise(function (resolve) {
          try {
            var r = d.transaction('v', 'readonly').objectStore('v').count();
            r.onsuccess = function () { resolve(r.result || 0); };
            r.onerror = function () { resolve(Object.keys(cache).length); };
