        for (var i = 0; i < anaBuf.length; i += 4) {
          var v = (anaBuf[i] - 128) / 128;
          sum += v * v;
        }
        return Math.sqrt(sum / (anaBuf.length / 4));
      } catch (e) { return 0; }
