      clearCache: clearCache, cacheCount: cacheCount, level: level,
      listAll: listAll, getRec: getRec,
      bzOn: function () { return bzOn; },
      voiceOn: voiceOn, buzzMode: bzMode,
      stopAll: function () { bzStop(); if (cur) { try { cur.pause(); } catch (e) { /* noop */ } } },
