      addLog: vlog,
      repaintLog: renderLog,
      clearLog: function () { LOG.length = 0; renderLog(); },
      logText: function () { return LOG.map(function (x) { return '[' + x.t + '] ' + x.m; }).join('\n'); },
      logCount: function () { return LOG.length; },
