  /* 面板里的运行日志挂一份到 window：手机上没有控制台，排语音问题时
     在酒馆的控制台里敲 __TOYLINK__.logText() 就能把现场整份捞出来。 */
  try {
    WIN.__toylink_log = {
      logText: function () { return VOC.logText(); },
      logCount: function () { return VOC.logCount(); }
    };
  } catch (e) { /* noop */ }

  function guessMime(f) {
    if (f === 'wav') return 'audio/wav';
    if (f === 'opus') return 'audio/ogg';
    return 'audio/mpeg';
  }

  /* =========================================================
   * ZIP 打包（stored 模式，不压缩）
   *
   * 面板是单文件、零依赖，所以自己写一个最小 ZIP。
   * 音频本身已经是压缩格式（mp3/opus），再压一遍收益接近零、还费 CPU，
   * 所以用 stored —— 实现简单，任何解压软件都认。
   * ======================================================= */
  var CRC_TBL = (function () {
    var t = new Uint32Array(256);
    for (var n = 0; n < 256; n++) {
      var c = n;
      for (var k = 0; k < 8; k++) c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
      t[n] = c >>> 0;
    }
    return t;
  })();
  function crc32(buf) {
    var c = 0xFFFFFFFF;
    for (var i = 0; i < buf.length; i++) c = CRC_TBL[(c ^ buf[i]) & 0xFF] ^ (c >>> 8);
    return (c ^ 0xFFFFFFFF) >>> 0;
  }
  function u16(a, o, v) { a[o] = v & 255; a[o + 1] = (v >>> 8) & 255; }
  function u32(a, o, v) { a[o] = v & 255; a[o + 1] = (v >>> 8) & 255; a[o + 2] = (v >>> 16) & 255; a[o + 3] = (v >>> 24) & 255; }

  function zipBuild(entries) {
    var enc = new TextEncoder();
    var parts = [], central = [], offset = 0;
    function cat(u8) { parts.push(u8); offset += u8.length; }

    entries.forEach(function (e) {
      var nameB = enc.encode(e.name);
      var data = e.data;
      var crc = crc32(data);
      var lh = new Uint8Array(30 + nameB.length);
      u32(lh, 0, 0x04034b50);          // 局部文件头签名
      u16(lh, 4, 20);                  // 需要的版本
      u16(lh, 6, 0x0800);              // 文件名走 UTF-8
      u16(lh, 8, 0);                   // 压缩方式 0 = stored
      u16(lh, 10, 0);                  // 修改时间
      u16(lh, 12, 0);                  // 修改日期
      u32(lh, 14, crc);
      u32(lh, 18, data.length);        // 压缩后大小
      u32(lh, 22, data.length);        // 原始大小
      u16(lh, 26, nameB.length);
      u16(lh, 28, 0);
      lh.set(nameB, 30);
      cat(lh); cat(data);

      var cd = new Uint8Array(46 + nameB.length);
      u32(cd, 0, 0x02014b50);          // 中央目录签名
      u16(cd, 4, 20);
      u16(cd, 6, 20);
      u16(cd, 8, 0x0800);
      u16(cd, 10, 0);
      u32(cd, 16, crc);
      u32(cd, 20, data.length);
      u32(cd, 24, data.length);
      u16(cd, 28, nameB.length);
      u32(cd, 42, 0);
      cd.set(nameB, 46);
      central.push(cd);
    });

    var cdSize = 0;
    central.forEach(function (c) { cdSize += c.length; });
    var eocd = new Uint8Array(22);
    u32(eocd, 0, 0x06054b50);          // 目录结束记录
    u16(eocd, 8, entries.length);
    u16(eocd, 10, entries.length);
    u32(eocd, 12, cdSize);
    u32(eocd, 16, offset);
    central.forEach(function (c) { parts.push(c); });
    parts.push(eocd);

    var total = 0;
    parts.forEach(function (p) { total += p.length; });
    var out = new Uint8Array(total), at = 0;
    parts.forEach(function (p) { out.set(p, at); at += p.length; });
    return out;
  }
  function safeName(s) {
    return String(s || '').replace(/[\\/:*?"<>|\r\n\t]+/g, '_').replace(/\s+/g, ' ').trim().slice(0, 24) || 'audio';
  }

  /* =========================================================
   * 4b. 阶段值的两个闸门：贴上 / 拿起 / 已满
   *
   * 「贴上 / 拿起」是一道总闸，描述的是"装置还在不在身上"：
   *   贴上 → 装置在，刺激在走，阶段值照常累积
   *   拿起 → 装置被拿走，刺激停下，阶段值停在当前值不动
   *   按钮上写当前状态，点一下就切换。
   *   注意它只拦累积，不拦玩家主动按的「冲击」「临界」「冲刺」——
   *   "拿起"是"不再自己往上涨"，不是"把面板锁死"。
   *
   * 阶段值满了（hi）不再像以前那样自动轮回重头：满值本身是一道锁，
   *   锁住累积，同时解锁「冲刺」。要离开满值只有两条路，都得玩家按：
   *     · 临界 → 回到临界区间或从头开始（按「到达临界后归零」那一档）
   *     · 冲刺 → 装置直冲顶点，完事后阶段值重来，而且之后要花更久才爬得回来
   * ======================================================= */
  function pushAro(d) {
    if (!S.hold || d <= 0) return;              // 装置被拿起了：不涨
    if (S.hi || S.aro >= 100) { S.aro = 100; return; }
    S.aro = clamp(S.aro + d, 0, 100);
  }

  /* 冲刺完成：阶段值从头来，并且这一次更慢 */
  function applyDashSlow() {
    S.aro = 0;
    S.stage = 1;
    S.hi = false;
    S.slow = S.dashRate;
    S.lastEvent = '冲刺完成，' + wearerName() + '被放回到适应的起点，再来一次要慢得多';
    toast('冲刺完成：阶段值归零，之后累积放慢到 ' + Math.round(S.dashRate * 100) + '%', 3600);
    react('peak');
    render();
    syncVars(true);
  }

  /* 满值锁：不自动轮回，同时解锁「冲刺」。pending 要清掉 ——
     满值那一瞬间如果还挂着"等 AI 生成"，会跟玩家的手动选择打架。 */
  function enterHi() {
    if (S.hi) return;
    S.hi = true;
    S.pending = false;
    S.lastEvent = '阶段值已满，' + wearerName()
      + '到了极限 —— 临界与冲刺都已解锁，之后怎么走由玩家按';
    toast('阶段值已满', 2600);
  }

  /* 「贴上 / 拿起」——并排两颗，选中的那颗框出来。
     它们描述的是同一个物理事实：装置还在不在身上。
       贴上 —— 装置在，刺激在走，阶段值照常累积
       拿起 —— 装置被拿走，刺激停下，阶段值不再增加
     点已经选中的那颗不做任何事（不来回切），避免"连点两下就回去了"的意外。 */
  function setHold(on) {
    if (on === S.hold) return;
    S.hold = on;
    S.lastEvent = on ? '重新贴上，阶段值继续累积' : '把装置拿起来，刺激停下，阶段值不再增加';
    toast(on ? '贴上：装置还贴着，阶段值继续上涨' : '拿起：装置已离开，阶段值不再增加');
    render();          // 里面会调 paintHold()，两颗的选中态一起刷新
    pushAction(act(
      on ? '把装置重新贴回去，继续刺激' : '把装置拿起来，先停一会儿',
      on ? '重新贴上装置，继续刺激' : '把装置拿起来'));
    persist();
    if (S.auto) react('mode');
  }
  $('#btn-put').addEventListener('click', function () { setHold(true); });
  $('#btn-take').addEventListener('click', function () { setHold(false); });

  /* 「临界」和「冲刺」的解锁在「震动模式」那一栏里处理（见 paintModeLocks）。
     它们本来就是九种模式中的两个档，不该另做一颗按钮 —— 那样同一件事有两个入口，
     玩家还得猜两处有什么区别。这里只管「贴上 / 拿起」。 */

  /* 这两个函数每帧都会被 render 调到，按钮只查一次就缓存住。
     还没插进 DOM 时（真的在 DOM 之前被调到）不缓存，下次再取，避免缓存住 null。 */
  var GATE_EL = {};
  function gateEl(id) {
    return (id in GATE_EL) ? GATE_EL[id] : (function () {
      var el = $('#' + id);
      if (el) GATE_EL[id] = el;
      return el;
    })();
  }

  /* 两颗一起刷新：贴着时「贴上」亮，拿起来了时「拿起」亮 */
  function paintHold() {
    var put = gateEl('btn-put'), take = gateEl('btn-take');
    if (put) {
      put.classList.toggle('on', !!S.hold);
      put.title = S.hold ? '装置现在还贴着（阶段值在涨）' : '点它把装置贴回去，阶段值继续累积';
    }
    if (take) {
      take.classList.toggle('on', !S.hold);
      take.title = S.hold ? '点它把装置拿起来，阶段值不再增加' : '装置已经拿起来了（阶段值冻结）';
    }
  }

  /* 「临界」「冲刺」的解锁由阶段值直接决定：
     临界 = 进入第 5 阶段即可用；冲刺 = 阶段值满了才可用。
     每帧都会被 render 调到，所以只碰 class/disabled 这类便宜操作。 */
  /* 「临界」和「冲刺」是九种模式里的两个档，按阶段解锁 —— 锁的是模式网格里
     那两颗按钮（见 buildModes 与 setMode），不是另加的一排闸门按钮。
     解锁条件是同一个阶段值：
       临界 → 进入第 5 阶段即可用（阶段值 93 以上）
       冲刺 → 阶段值满了（hi）才可用
     target='user'（遥控器在 TA 手里）时不看解锁条件，整个网格都是只读仪表。 */

  /* 每帧由 render / physics 调用，只碰 class 与 aria 这类便宜操作。 */
  var LAST_MODE_LOCK = '';
  function paintModeLocks() {
    var box = $('#modes');
    if (!box) return;
    var readOnly = (S.target === 'user');
    var sig = readOnly + '|' + S.stage + '|' + (S.hi ? 1 : 0);
    if (sig === LAST_MODE_LOCK) return;   // 状态没变就不动 DOM
    LAST_MODE_LOCK = sig;
    var kids = box.children;
    for (var i = 0; i < kids.length; i++) {
      var b = kids[i];
      var id = b.dataset ? b.dataset.id : '';
      if (id !== 'edge' && id !== 'rush') continue;
      var unlocked = readOnly ? true
        : (id === 'edge' ? S.stage >= 5 : !!S.hi);
      b.classList.toggle('lk', !unlocked);
