    return modeOpen(id);
  }
  /* 只看阶段、不看档位：AI 在 user 档报的模式也要过这道闸（modeUnlocked 在 user 档恒为 true，挡不住它） */
  function modeOpen(id) {
    if (id === 'edge') return S.stage >= 5;
    if (id === 'rush') return !!S.hi;
    return true;
  }

  /* =========================================================
   * 4c. 语音台词库
   *
   * 三档对应三种口气（1.12.0 的第三档也照顾到了）：
   *   char 档（遥控器在玩家手里）→ 被作用的是角色 → 呻吟
