    ],
    /* 「请求 TA 停下」之后 TA 的应答 —— 精简，一句就够 */
    beg: [
      { t: '……好。这就停。手给我，喘匀了再说话。' },
      { t: '……松手了。过来，让我看看你现在这个样子。' },
