  /* 按阶段与作用对象挑一条。stage 是 1-5。 */
  function voiceKind() {
    if (S.target === 'user') return 'tease';   // 遥控器在角色手里 → 调教对白
    if (S.target === 'self') return 'self';    // 都在玩家自己身上 → 没有别人，只有自己的气音
    return 'moan';                             // char 档 → 被作用的是角色
  }
  function voiceMark(kind, stage) {
    if (kind === 'beg') {
      var b = VOICE_MARK.beg;
      return b[Math.floor(Math.random() * b.length)];
    }
    var arr = VOICE_MARK[kind] || VOICE_MARK.moan;
    var i = clamp((stage || 1) - 1, 0, arr.length - 1);
    var pool = arr[i] || arr[0];
    return pool[Math.floor(Math.random() * pool.length)];
  }
  /* 名字填充：台词库里的占位符换成实际的人名 */
  function fillName(s) {
    return String(s || '')
      .split('__W__').join(wearerName(true))
      .split('__H__').join(holderName(true));
  }
  /* 取一条现成台词，**带上情绪标记**（标记在最前，官方说句首最有效） */
  function libPick(kind, stage) {
    var arr = VOICE_LIB[kind] || VOICE_LIB.moan;
    var i = clamp((stage || 1) - 1, 0, arr.length - 1);
    var pool = arr[i];
    if (!pool || !pool.length) { pool = VOICE_LIB.moan[0]; }
    var line = pool[Math.floor(Math.random() * pool.length)].t;
    return fillName(voiceMark(kind, stage) + ' ' + line);
  }
  /* 已经带标记就别再叠一层（AI 给的台词通常自带） */
  function hasMark(s) { return /^\s*\[[^\]]+\]/.test(String(s || '')); }

  /* ---------- 拦住读数串场进来的"不是台词的东西" ----------
     AI 偶尔会把读数里的枚举值当成台词塞进「语音」字段 —— 实测见过 [气声] 暴雨。
     它一旦进来就会被念出来，而玩家在面板上看到的是一句莫名其妙的模式名。
     三道拦：① 剥掉混进来的字段名；② 逐行剔掉"本身就等于某个枚举值"的裸行；
     ③ 剔掉没有标点的孤立词（台词可以是"嗯……"，但不会是光秃秃两个字）。 */
  var FIELD_NAMES = ['开关', '模式', '频率', '强度', '说明', '心声', '语音'];
  var READOUT_VALUES = ['开', '关', '脉冲', '潮汐', '心跳', '渐强', '乱流', '撩拨', '暴雨', '临界', '冲刺'];
  /* 剥掉尾巴上混进来的「模式=暴雨|」这类残片 */
  function stripFieldTail(s) {
    var out = String(s || '').replace(new RegExp('(?:' + FIELD_NAMES.join('|') + ')\\s*[=:：]\\s*[^|｜\\r\\n]*', 'g'), ' ');
    return out.replace(/[|｜]\s*$/g, '').replace(/\s{2,}/g, ' ').trim();
  }

  /* 摘片段只针对"确定不可能是台词"的词：
     模式名（九个档）、读数里的字段名、界面上的功能词、以及环境音与装置声。
     「开」「关」「震动」这类**不进这张表** —— 它们太常用，
     按片段摘会把"张不开口""关不掉""震得说不出话"砍坏；它们只参与整值判断。 */
  var READOUT_WORDS = [
    '脉冲', '潮汐', '心跳', '渐强', '乱流', '撩拨', '暴雨', '临界', '冲刺',
    '开关', '模式', '频率', '强度', '时长', '限时', '累积', '阶段',
    '声波模拟', '振动音', '嗡嗡声', '嗡鸣', '电流声', '马达', '底噪', '环境音'
  ];

  /* AI 把整个读数当台词的兜底：内容本身就只是个枚举值 → 判定为串场，丢掉。
     判据分两种：
       ① 剥掉标记和标点之后，整个就是某个枚举值（"暴雨"、"开"、"模式=暴雨"）
       ② 拿模式名当分隔符切一刀，每一段都只是标记或标点 ——
          说明整行都是模式名拼的（"暴雨 临界"），这时整行作废 */
  function looksLikeReadout(s) {
    var bare = String(s || '')
      .replace(/\[[^\]]*\]\s*/g, '')
      .replace(/[\s，。、,.;:：；！？!?…—\-~～"'「」『』]/g, '');
    if (bare && READOUT_VALUES.indexOf(bare) >= 0) return true;

    var re = new RegExp('(' + READOUT_WORDS.join('|') + ')', 'g');
    if (!re.test(String(s || ''))) return false;
    re.lastIndex = 0;
    var segs = String(s || '').split(re).filter(function (x) { return x != null && x !== ''; });
    for (var i = 0; i < segs.length; i++) {
      // 只允许「空白/标记/标点」存在；出现任何实义字就说明这行有真正的台词，留着
      if (segs[i].replace(/\[[^\]]*\]/g, '').replace(/[\s，。、,.;:：；！？!?…—\-~～"'「」『』]/g, '')) return false;
    }
    return true;
  }

  /* 这一串里有没有实义字（剥掉标记、空白和标点之后还剩东西） */
  function realWords(s) {
    return !!String(s || '')
      .replace(/\[[^\]]*\]/g, '')
      .replace(/[\s，。、,.;:：；！？!?…—\-~～"'「」『』]/g, '');
  }
  /* 只有标记和标点、没有任何实义字 —— 合成出来会是一段没有内容的气声 */
  function noRealWord(s) { return !realWords(s); }

  /* ---------- 拦住"叙述"冒充台词 ----------
     除了读数串场，还有一类更常见的污染：AI 把**旁白或环境描写**当成台词塞进语音字段。
     实测见过「[喘息] 嗡嗡声还在继续」「[气声] 她咬着牙想维持住」。它们被念出来就是
     一段莫名其妙的朗读。这里给一条便宜的叙述判据：
       出现第三人称代词（她/他/它/她们…）或"自己"，并且带着描写性动词 —— 多半是叙述。
     真正的台词是"我/你"或直接的话，不会叙述第三个人在干什么。 */
  var NARRATIVE_VERB = /(咬着|撑着|忍着|扶着|靠着|闭着|睁着|抬|低|垂|抓|攥|扯|蜷|缩|颤|抖|呼吸|喘着|看着|听着|感到|觉得|试图|努力|勉强|不由|慢慢|渐渐|已经|正在|还在|似乎|仿佛|好像|终于|依旧|仍然)/;
  function looksLikeNarration(s) {
    var t = String(s || '').replace(/\[[^\]]*\]\s*/g, '').trim();
    if (!t) return false;
    var third = /(她们|他们|它们|她|他|它|自己)/.test(t);
    if (!third) return false;
    // 「你」「我」在场时更像对话，放宽一点：只有同时带描写动词才判为叙述
    return NARRATIVE_VERB.test(t);
  }

  /* ---------- 环境音：装置声不是台词 ----------
     「嗡嗡声还在继续」这种整行都会被念出来。只摘掉"嗡嗡声"不够，
     上半句「还在继续」照样是噪音，所以还要判"整行是不是环境描写"。
     只列**以「声」结尾的词**和明确的装置声名词：这样"震动声""电流声"能摘，
     而"震得我说不出话""声音都变了"这类真台词不会被砍坏。 */
  var AMBIENT_RE = /(嗡嗡声|嗡鸣声?|电流声|马达声|振动声|震动声|底噪声?|环境音|轰鸣声?|噪[声音]|机械声|音效)/g;

  /* 这一行是不是主要在讲装置/环境在响 */
  function looksLikeAmbient(s) {
    var raw = String(s || '');
    if (!AMBIENT_RE.test(raw)) return false;
    AMBIENT_RE.lastIndex = 0;
    // 摘掉所有环境音词，剩下的若只是零碎连接词和标点（没有引号、没有语气词），
    // 就说明这一行本来就是在描述"什么东西在响"，不是人在说话
    var rest = raw.replace(AMBIENT_RE, '').replace(/\[[^\]]*\]/g, '')
      .replace(/[\s，。、,.;:：；！？!?…—\-~～"'「」『』]/g, '');
    if (rest.length >= 6) return false;                       // 还有实打实的内容，留着
    if (/[「」『』"']/.test(raw)) return false;                 // 带引号的是对白
    return true;
  }

  /* 摘掉行里混进来的模式名/环境音，并把整行是环境描写的作废 */
  function dropReadoutSeg(s) {
    var raw = String(s || '');
    if (looksLikeAmbient(raw)) return '';
    var re = new RegExp('(' + READOUT_WORDS.join('|') + ')', 'g');
    return raw
      .split(re)
      .map(function (x) { return (x != null && READOUT_WORDS.indexOf(x) >= 0) ? ' ' : x; })
      .join('')
      .replace(AMBIENT_RE, ' ')
      .replace(/\s{2,}/g, ' ')
      .trim();
  }

  /* 清一行：剥字段名 → 摘掉混进来的模式名 → 该作废的作废。
     作废的条件是**"摘之前有实义字、摘完只剩标记和标点"** —— 那说明这一句的内容
     本来就是读数里的档位名（"[气声] 暴雨" → 空话），留着只会合成出一句莫名的气声。
     本来就只有标记的「[气声]」（AI 自己排的独立标记行）不算，原样留着。
     首尾只削分隔符和空白；句末的「。」「……」「？」留着 —— 它们本来就在念的节奏里。 */
  function cleanVoiceLine(line) {
    var raw = String(line || '');
    var s = dropReadoutSeg(stripFieldTail(raw));
    if (realWords(raw) && noRealWord(s)) return '';
    if (looksLikeReadout(s)) return '';
    if (looksLikeNarration(s)) return '';   // 旁白/环境描写：不是台词，别念
    return s.replace(/^[\s，、,；;：:|｜]+|[\s，、,；;：:|｜]+$/g, '').trim();
  }

  /* 整段清洗：逐行过 cleanVoiceLine，最多留 3 行。
     行内该丢的（档位名串场）由 cleanVoiceLine 负责；这里只做行数的收口。 */
  function cleanVoiceText(t) {
    var lines = String(t || '').split(/[\r\n]+/);
    var out = [];
    for (var i = 0; i < lines.length && out.length < 3; i++) {
      var c = cleanVoiceLine(lines[i]);
      if (c) out.push(c);
    }
    return out.join('\n');   // 全被丢掉时返回空串，上层回退到台词库
  }

  /* ---- 台词库的取用接口（试听选择器与正式播放共用同一套） ---- */
  /* 某一类某一档的库本体。
     三级结构（moan/tease/self）是 [5 档][每条]；beg 是不分档的扁平 [每条]。
     判据要落在"第一层元素还是不是数组"上 —— 早先写成看 arr[0].t 是否存在，
     而 arr[0] 本身是数组、数组上没有 t，于是整类都被误判成扁平的了。 */
  function libStagePool(kind, stage) {
    var arr = VOICE_LIB[kind] || VOICE_LIB.moan;
    if (!arr.length || !Array.isArray(arr[0])) return [];   // beg：扁平数组，没有档位
    return arr[clamp((stage || 1) - 1, 0, arr.length - 1)] || [];
  }
  /* 取第 i 条原样（试听要的是"这一条"，不要随机，所以不走 libPick）。
     kind='beg' 时走那一支扁平的应答句。 */
  function libLineAt(kind, stage, i) {
    if (kind === 'beg') {
      var b = VOICE_LIB.beg;
      i = clamp(i | 0, 0, b.length - 1);
      return fillName(voiceMark('beg', stage) + ' ' + b[i].t);
    }
    var pool = libStagePool(kind, stage);
    if (!pool.length) pool = VOICE_LIB.moan[0];
    i = clamp(i | 0, 0, pool.length - 1);
    return fillName(voiceMark(kind, stage) + ' ' + pool[i].t);
  }

  /* 决定"说哪一句、用什么音色口气"。

     两条内容严格分开，别互相污染：
       · 界面上的文字说明（心声）—— 给眼睛看的，"低下头，呼吸乱了一拍。"这种
       · 要念出来的台词（语音）—— 给耳朵听的，带情绪标记，能直接进 TTS

     优先顺序（正文对白排在最前，这样"听到的"和"读到的"是同一句话）：
       1. 正文里引号包住的对白   ← 新增：正文有对白就用它，视听一致
       2. AI 在读数里明写的语音字段
       3. 台词库（自动配情绪标记）—— 正文没有对白时的兜底
     force='beg' 时走请求停止那一支。 */
  function voiceFor(voiceLine, stage, force, body) {
    var kind = (force === 'beg') ? 'beg' : voiceKind();
    /* 两套音色是可选的：
       默认共用同一个（同一个人不同处境下的声音）；
       填了「TA 拿着遥控器时的音色」就分开用 —— 那时 ta 是操控方，口气与呻吟本来就不同。 */
    var voice = (kind === 'tease' && S.ttsVoiceTease) ? S.ttsVoiceTease : S.ttsVoice;
    var out = { text: '', kind: kind, voice: voice };

    // 1) 正文里的对白：有引号、多行、按句截断、丢掉叙述 —— 只要它像台词就优先
    var spoken = extractSpeech(String(body || ''), kind, stage);
    if (spoken && voiceish(spoken)) {
      out.text = spoken;
      out.fromBody = true;
      return out;
    }
    // 2) AI 在读数里明写的语音字段。
    //    先清洗：读数里的枚举值（"暴雨"这种模式名）偶尔会被 AI 顺手塞进来，
    //    不清的话它会被原样念出来，而正文里根本没有这句话。
    var given = cleanVoiceText(fillName(String(voiceLine || '').trim()));
    if (given && voiceish(given)) {
      out.text = hasMark(given) ? given : (voiceMark(kind, stage) + ' ' + given);
      return out;
    }
    if (voiceLine && !given) {
      try { console.log('[TOY·LINK 语音] 读数里的「语音」字段被判定为读数串场，已丢弃：「' + String(voiceLine).trim().slice(0, 40) + '」'); } catch (e) { /* noop */ }
    }
    // 3) 退回台词库：按档位取现成的，自动配情绪标记
    out.text = libPick(kind, stage);
    return out;
  }

  /* 从正文里抽对白：只取引号包住的内容（「」『』“”""），
     按句号/问号/感叹号切句，每句截到 24 字，最多 3 句拼成多行。
     正文没有对白时返回 ''，交给上层回退。 */
  function extractSpeech(body, kind, stage) {
    var src = String(body || '');
    if (!src) return '';
    var out = [], re = /[「『“"]([^」』”"]{1,100})[」』”"]/g, m;
    while ((m = re.exec(src)) !== null && out.length < 3) {
      var seg = m[1].replace(/[\r\n]+/g, ' ').replace(/\s{2,}/g, ' ').trim();
      seg = seg.replace(/^[，、,。.；;：:\s]+|[，、,。.；;：:\s]+$/g, '');
      if (!seg) continue;
      // 一句太长就按句末切，取头一两句
      if (seg.replace(/\[[^\]]*\]\s*/g, '').length > 24) {
        // 不用后行断言 (?<=…)：iOS Safari 16.4 以前不认，整个脚本会在解析阶段报错、一行都不跑
        var parts = seg.match(/[^。！？!?]+[。！？!?]*|[。！？!?]+/g) || [seg];
        var acc = '';
        for (var i = 0; i < parts.length; i++) {
          if ((acc + parts[i]).replace(/\[[^\]]*\]\s*/g, '').length > 32) break;
          acc += parts[i];
        }
        seg = acc || seg.slice(0, 24);
      }
      // 原文一般不带标记，补一个，语气才跟着当前处境走
      if (!hasMark(seg)) seg = voiceMark(kind, stage) + ' ' + seg;
      out.push(seg);
    }
    return out.join('\n');
  }

  /* 判断一段文本"是不是台词"：带情绪标记、引号，或者以拟声词起头的短句。
     目的是拦住"低下头，呼吸乱了一拍。"这类叙述 —— 它们不该被念出来。
     多行台词（要求 2-3 行、每行各带标记）逐行判定：至少半数行像台词就算。 */
  function voiceish(s) {
    var str = String(s || '').trim();
    if (!str) return false;
    if (str.indexOf('\n') >= 0) {
      var ls = str.split(/[\r\n]+/).filter(function (x) { return x.trim(); });
      if (!ls.length) return false;
      var good = ls.filter(function (x) { return lineIsVoice(x); }).length;
      return good >= Math.ceil(ls.length / 2);
    }
    return lineIsVoice(str);
  }
  /* 单行判定。长度上限放宽到 80：多行台词的每一行可能较长，
     真正的护栏是"必须带标记或引号"。 */
  function lineIsVoice(s) {
    s = String(s || '').trim();
    if (!s) return false;
    /* 先排除叙述，再谈"像不像台词"。
       带标记的行以前一律放行 —— 于是「[喘息] 嗡嗡声还在继续」这种
       被标了记的旁白照样会通过，然后被念出来。这里把它拦在前面。 */
    if (looksLikeNarration(s)) return false;
    if (hasMark(s)) return true;                                  // [panting] 哈啊……
    if (/^[「『"'“]/.test(s) || /[」』"'”]$/.test(s)) return true;  // 带引号的对白
    if (s.replace(/\[[^\]]*\]\s*/g, '').length > 80) return false; // 太长且没标记，一律不是台词
    return /^[啊嗯唔哈呀哦诶咿嘻哼乖手别求慢不要]/.test(s)
      || /[……——]{1,}/.test(s) && !/[，。]{1}[^…—]/.test(s);
  }
  /* 标记数量（多行时逐行统计），用于"标记太密"的提醒 */
  function markCount(s) { return (String(s || '').match(/\[[^\]]+\]/g) || []).length; }

  /* =========================================================
   * 5. 渲染
   * ======================================================= */
  var ring1 = $('#ring1'), ring2 = $('#ring2'), ringEl = $('#ring');
  var big = $('#big'), sub = $('#sub'), mtag = $('#mtag');
  var aroEl = $('#aro'), stageName = $('#stage-name');
  var phaseEls = $('#phases').children;
  var waveCv = $('#wave'), wctx = waveCv.getContext('2d');
  var hist = [];
  var HIST_MAX = 180;
  var ringPulse = 0;
  var lastStatePaint = 0;

  function pulseRing() { ringPulse = 1; }

  function fitCanvas() {
    var r = waveCv.getBoundingClientRect();
    var dpr = Math.min(window.devicePixelRatio || 1, 2.5);
    waveCv.width = Math.max(10, Math.round(r.width * dpr));
    waveCv.height = Math.max(10, Math.round(r.height * dpr));
    wctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  }

  function drawWave() {
    var w = waveCv.width / (Math.min(window.devicePixelRatio || 1, 2.5));
    var h = waveCv.height / (Math.min(window.devicePixelRatio || 1, 2.5));
    wctx.clearRect(0, 0, w, h);
    var n = hist.length;
    if (n < 2) return;
    var stepX = w / (HIST_MAX - 1);
    var x0 = w - (n - 1) * stepX;

    function pathAt(mul, offset) {
      wctx.beginPath();
      for (var i = 0; i < n; i++) {
        var v = hist[i] * mul;
        var y = h - 4 - v * (h - 10) + offset;
        var x = x0 + i * stepX;
        if (i === 0) wctx.moveTo(x, y); else wctx.lineTo(x, y);
      }
    }
    // 填充
    pathAt(1, 0);
    wctx.lineTo(w, h); wctx.lineTo(Math.max(x0, 0), h); wctx.closePath();
    var g = wctx.createLinearGradient(0, 0, 0, h);
    g.addColorStop(0, 'rgba(' + HOT_RGB + ',.34)');
    g.addColorStop(1, 'rgba(' + HOT_RGB + ',0)');
    wctx.fillStyle = g; wctx.fill();
    // 主线
    pathAt(1, 0);
    wctx.strokeStyle = S.on ? 'rgba(' + HOT_RGB_2 + ',.95)' : 'rgba(232,214,236,.20)';
    wctx.lineWidth = 1.6; wctx.lineJoin = 'round'; wctx.stroke();
    // 余像
    pathAt(0.62, -3);
    wctx.strokeStyle = 'rgba(' + CYAN_RGB + ',.35)';
    wctx.lineWidth = 1; wctx.stroke();
  }

  function render() {
    var f = hz(), p = pow01();
    // 圆环
    var C1 = 2 * Math.PI * 52, C2 = 2 * Math.PI * 43;
    var v1 = S.on ? (0.18 + 0.82 * S.env) : 0;
    var v2 = S.aro / 100;
    ring1.setAttribute('stroke-dasharray', (C1 * clamp(v1, 0, 1)).toFixed(1) + ' ' + C1.toFixed(1));
    ring2.setAttribute('stroke-dasharray', (C2 * clamp(v2, 0, 1)).toFixed(1) + ' ' + C2.toFixed(1));
    ringEl.classList.toggle('off', !S.on);

    var shown = S.on ? Math.round(S.env * 100) : 0;
    big.innerHTML = shown + '<small>%</small>';
    sub.textContent = f.toFixed(1) + ' Hz';
    mtag.textContent = S.on ? modeById(S.mode).name : '待机';

    aroEl.textContent = Math.round(S.aro);
    var frozenNow = S.on && (HOLD || BUSY) && S.freezeOnGen;
    stageName.textContent = (frozenNow ? '⏸ ' : '') + '第 ' + S.stage + ' 阶段 · ' + STAGES[S.stage - 1].name
      + (S.hi ? ' · 已满' : (S.hold ? '' : ' · 累积已停'));
    var fm = $('#full-mark');
    if (fm) fm.hidden = !S.hi;
    paintModeLocks();
    paintHold();
    var tip = $('#freeze-tip');
    if (tip) tip.hidden = !frozenNow;
    for (var i = 0; i < phaseEls.length; i++) {
      var ph = phaseEls[i];
      var lo = STAGES[i].at;
      var hi = (i + 1 < STAGES.length) ? STAGES[i + 1].at : 100;
      var v = clamp((S.aro - lo) / (hi - lo), 0, 1);
      ph.firstElementChild.style.width = (v * 100) + '%';
      ph.classList.toggle('done', v >= 1);
    }
    // 圆环呼吸
    if (ringPulse > 0) {
      ringPulse = Math.max(0, ringPulse - 0.08);
      ringEl.style.transform = 'scale(' + (1 + ringPulse * 0.014) + ')';
    }
    $('#fv').innerHTML = f.toFixed(1) + '<em>Hz</em>';
    $('#pv').innerHTML = S.pow + '<em>%</em>';
    $('#dv').innerHTML = (S.limit === 0 ? '∞' : S.limit) + '<em>' + (S.limit === 0 ? '' : '分') + '</em>';
    var ps = $('#param-state');
    if (ps) ps.textContent = S.on ? '' : '未启动 · 调整只是预置';
    var nowMs = Date.now();
    if (nowMs - lastStatePaint > 800 && !$('#v-config').hidden) {
      lastStatePaint = nowMs;
      $('#state-box').value = stateText();
    }
    // 遥控器在 TA 手里时，这个键不是"开关"，只是"催 TA 一次"
    var userT = (S.target === 'user');
    $('#power').textContent = userT ? (S.on ? '再催一次' : '催 TA 一次') : (S.on ? '停 止' : '启 动');
    $('#power').classList.toggle('stop', S.on && !userT);
  }

  function paintSlider(el) {
    var pct = ((+el.value - +el.min) / (+el.max - +el.min)) * 100;
    el.style.setProperty('--p', pct + '%');
  }

  /* =========================================================
   * 6. 主循环
   * ======================================================= */
  var raf = 0, lastTs = 0, lastSync = 0, lastDraw = 0, lastPhys = 0;

  // 物理推进与绘制分离：界面被折叠、iframe 不可见或浏览器暂停 rAF 时，
  // 定时器仍能维持装置运行，不会出现"启动了但数值不动"。
  function physics(dt) {
    if (S.on) {
      // clock 驱动波形与包络，一直在走；t 是剧情时间，AI 生成期间可以冻结。
      // LLM 出字慢，若生成期间继续累积，回复落地时状态早就变了，
      // 表现为"换阶段"和"回复"撞在同一时刻。
      S.clock += dt;
      var m = modeById(S.mode);
      S.env = m.env(S.clock, { pow: pow01(), hz: hz(), phase: S.clock * 0.37 });

      var frozen = (HOLD || BUSY) && S.freezeOnGen;
      if (!frozen) {
        S.t += dt;

        // 累积：强度与频率共同决定，模式有增益差。
        // 再乘两道系数 —— slow 是冲刺后的减速，「贴上」开关关着时 pushAro 直接不放行。
        var rate = (0.075 * pow01() + 0.055 * Math.pow(S.freq / 100, 0.8)) * m.gain * (S.gain / 100) * (S.slow || 1);
        pushAro(rate * dt * 6.2);

        var st = stageOf(S.aro);
        if (st !== S.stage) {
          var up = st > S.stage;
          S.stage = st;
          S.lastEvent = '进入第 ' + st + ' 阶段 · ' + STAGES[st - 1].name;
          // 冲刺模式是一次性直冲，阶段会被瞬间跨过好几级；
          // 逐级触发生成只会把它切成一段段冻结，所以这一档不响应阶段跃迁。
          if (up && !m.oneShot) {
            if (S.stageForce && S.auto) react('stage');
            toast('进入第 ' + st + ' 阶段 · ' + STAGES[st - 1].name);
          }
        }

        // 阶段值一变就刷模式锁定状态（内部有签名比较，同值直接返回，不做无谓的 DOM 操作）
        paintModeLocks();

        /* 阶段值满了：不再自动轮回，改成一道锁。
           以前这里是"pop 一次 → 归零 → 继续爬"，无限循环；
           现在满值停下来，由玩家按「临界」或「冲刺」决定往哪走。
           满值只触发一次（用 !S.hi 挡重复）。 */
        if (S.aro >= 99.5 && !S.hi) {
          S.aro = 100;
          S.stage = 5;
          enterHi();
          paintModeLocks();
          // 冲刺模式到顶视为"这一轮冲完了"：阶段值重来并放慢，装置交给玩家决定收不收
          if (m.oneShot) {
            HAP.fire(S.env, hz());
            applyDashSlow();
            return;
          }
          HAP.burst();
          S.peak++;
          S.lastEvent = '第 ' + S.peak + ' 次临界爆发（阶段值已满，临界与冲刺已解锁）';
          react('peak');
        }
        // 满值期间掉下来（被玩家按了临界/冲刺之外的路径改过）就解锁，允许重新累积
        if (S.hi && S.aro < 99) { S.hi = false; paintModeLocks(); }

        // 限时到点自动停
        if (S.limit > 0 && S.t >= S.limit * 60) stop('限时结束');
      }

      HAP.fire(S.env, hz());
      AUD.update(S.env, hz());
      VOC.tick(S.env);      // 振动音与 TTS 输出在这条链上统一同步
    } else {
      S.env = 0;
      VOC.tick(0);          // 装置停了也要调一次，交给它自己收干净
    }
  }

  function paint() {
    var now = performance.now();
    if (now - lastDraw < 32) return;
    lastDraw = now;
    hist.push(S.on ? S.env : 0);
    if (hist.length > HIST_MAX) hist.shift();
    drawWave();
    render();
  }

  function step() {
    var now = performance.now();
    var dt = lastPhys ? Math.min((now - lastPhys) / 1000, 0.5) : 0;
    lastPhys = now;
    physics(dt);
    paint();
    // 变量同步（5 秒一次，差量写入）
    if (now - lastSync > 5000) {
      lastSync = now;
      if (S.on) syncVars(true);
    }
  }

  // 省电：装置关着时物理层只会把 env 归零，没必要 60 帧地画。
  // rAF 只在装置运行时跑；停下后由下面那个心跳以 ~4Hz 兜底，启动时再把 rAF 拉起来。
  // （这四处是从仓库产物的 v1.10.3 回移过来的，改动者是 fannnnnnn5822。）
  var lastIdle = 0;
  function loop(ts) {
    raf = S.on ? requestAnimationFrame(loop) : 0;
    step();
  }
  function wakeLoop() { if (!raf) raf = requestAnimationFrame(loop); }
  function heartbeat() {
    if (S.on) { if (!raf) wakeLoop(); step(); return; }
    var now = performance.now();
    if (now - lastIdle < 250) return;
    lastIdle = now;
    step();
  }

  /* =========================================================
   * 7. 与角色交互
   * ======================================================= */
  /* forVar：写进聊天变量 toy_state 的那一份。它会被常驻世界书「② 实时状态」每一轮都带上，
     所以不能带「附一句心声」的输出要求 —— 否则玩家正常聊天、装置都没碰，AI 也每条回复都附一行
     <TOY>心声=…</TOY>（普通回复不经过面板，这行也没人剥，还会被后面的回复照抄）。
     心声只在面板发起的那一轮要（注入 / 面板内生成），那几处调用不传 forVar。 */
  function stateText(forVar) {
    var m = modeById(S.mode);
    var sn = STAGES[S.stage - 1].name;
    var L = [];
    var cn = charName();
    var selfT = (S.target === 'self');
    var wn = wearerName();    // 装置戴在谁身上：char 档是 cn，另两档是玩家
    var hn = holderName();    // 遥控器在谁手里：user 档是 cn，另两档是玩家
    var dv = devOf();
    var suck = (S.dev === 'suck');
    L.push('【TOY·LINK 装置 · 实时状态】');
    // 归属必须写死、而且要点名：光靠世界书那一条很容易被角色卡自己的设定盖过去，
    // 用"角色""对方"这类词也容易被多 NPC 的卡指错人。
    if (S.target === 'user') {
      L.push('归属：装置戴在【玩家自己】身上，遥控器在【' + cn + '】手里。被震动的是玩家，不是 ' + cn + '。');
    } else if (selfT) {
      // 自己玩：世界卡 / 沙盒卡上 cn 可能是「系统」「旁白」，AI 会顺手安排它来拿遥控器 —— 这里必须堵死
      L.push('归属：装置戴在【玩家自己】身上，遥控器也在【玩家自己】手里。没有人在操控、没有人知道。'
        + '不要安排 ' + cn + ' 或任何人来拿遥控器。');
      L.push('▲ 档位全由玩家自己按。不要凭空安排人物登场；场景里如果有别人，他们不知道装置的存在，'
        + '只能注意到玩家外在的异样。' + cn + ' 是旁白、世界、系统这类身份时，用旁白视角写。');
    } else {
      L.push('归属：装置戴在【' + cn + '】身上。【玩家】身上没有装置，玩家手里只有遥控器。');
      L.push('▲ 被震动、被刺激、出现身体反应的是 ' + cn + '，不是玩家。'
        + '不要写玩家的下腹、大腿、腰或皮肤下面有任何东西在动。');
      L.push('▲ 如果前面的楼层里出现过"贴着你""你的大腿发软"这类描写，那是写错了：'
        + '从这条回复开始一律改成写 ' + cn + ' 的身体，直接改过来，不要解释这件事。');
    }
    // 描述句里占位符两侧的空格是给 {{char}} 宏留的，换成中文名字时一并吃掉
    L.push('装置形态：' + dv.name + '（' + dv.desc.replace(/ ?__WEARER__ ?/g, wn) + '）');
    L.push('运行状态：' + (S.on ? '运行中（装置此刻正在工作）' : '已停止（' + (S.stopReason || '已关闭') + '）'));
    L.push('模式：' + m.name + '｜频率：' + hz().toFixed(1) + ' Hz｜强度：' + S.pow + '%');
    L.push('已持续：' + fmtTime(S.t) + (S.limit > 0 ? '｜本次限时：' + S.limit + ' 分钟' : ''));
    L.push('阶段：第 ' + S.stage + ' 阶段·' + sn + '（累积 ' + Math.round(S.aro) + '/100，累计临界 ' + S.peak + ' 次）');
    // 满值与"装置还在不在身上"必须明说，否则 AI 会一直写"还在往上爬"，跟面板对不上
    if (S.hi) {
      L.push('▲ 累积已经满格：' + wn + ' 顶到头了，不会自己再涨。'
        + '要往下走只有两条路，都是玩家亲手按的 —— 「临界」（放回临界区间或从头开始）或「冲刺」（直冲顶点，之后归零并放慢）。'
        + '这一轮不要写"数值继续攀升"，改写"停在顶点上被反复摩擦、等着那一下"。');
    } else if (!S.hold) {
      L.push('▲ 装置已经被拿起来、离开了身体，刺激停下：累积值冻结在当前这一档，不会继续增加。'
        + '可以写余韵、喘息、缓过来，或者反过来写"忽然空下来"的难耐，但不要写数值还在涨，'
        + '也不要写装置还在身上震。');
    }
    L.push('最近变化：' + S.lastEvent);
    if (S.lastActionNote) {
      L.push(cn + ' 自己定下的意图：' + S.lastActionNote + '（接着往下写时保持这个方向）');
    }
    L.push('');
    if (S.actions.length) {
      L.push(hn + '刚刚在遥控器上的操作：');   // user 档动作是 TA 按的（act 的 asNpc 那半），主语不能写成玩家
      for (var k = 0; k < S.actions.length; k++) L.push('　' + (k + 1) + '. ' + S.actions[k]);
      L.push('');
    }
    L.push('写作要求（优先级最高）：');
    if (!S.explicit) {
      // 忍耐 · 假装镇定：不写体内，全部落到外部可观察的表现上。
      // 这三条与「世界书 ④⑧⑪ 的忍耐版」同款，两边都写是有意的 ——
      // 用的是角色卡自带世界书时，世界书那半改不到，注入这半才是兜底。
      L.push('· 描写尺度是【忍耐 · 假装镇定】：不写体内感觉、不写生理机制、不写液体，'
        + '也不写"高潮""受不了了"这类结论句。全部落在外面：呼吸、姿态、手在抓什么、话说到第几个字、'
        + '声音从哪里漏出来，以及对周围事物的失手。');
      L.push('· 全篇的主体是"在忍"：嘴硬、转移话题、硬撑着做原来的事；破绽落在动作和语言上 —— '
        + '手比嘴诚实，声音比表情诚实。');
      L.push('· 顶点只写"装不住了"的那一下（话断在半句、身体从支撑物上滑下去、几秒里发不出声音），'
        + '以及之后怎么把场面收拾回来。');
    } else {
      // 身体版本要显式告诉模型，免得它在男女的反应机制上串线
      L.push(S.body === 'male'
        ? '· 被作用者的身体是【男性】：顶点是一次性的释放，到达后有不应期，那段时间里继续刺激只会变成酸胀难受，'
          + '不要再写连续高潮。回落之后写恢复期的疲惫与敏感过头，不要立刻爬第二波。'
        : '· 被作用者的身体是【女性】：没有明确的不应期，一波刚落下一波就能接上，累积回落之后反而更敏感，'
          + '所以顶点不是"结束"，而是下一轮更容易被推上去的起点。');
    }
    L.push('· 装置形态是【' + dv.name + '】：' + dv.tip);
    // 冲刺到顶是个特殊时刻：装置已经停了，但正文要写的是"她刚到顶点"这件事
    if (S.stopReason && S.stopReason.indexOf('冲刺') === 0) {
      L.push(S.explicit
        ? '▲ ' + wn + ' 刚被冲刺模式一路推到顶点。这一轮正文就写这次高潮本身：到达的那一刻、脱力的痉挛、'
          + '止不住的眼泪与随后的余韵。不要写慢慢积累的过程，也不要把重点放在"装置停了"上。'
        : '▲ ' + wn + ' 刚被冲刺模式一路推到顶点。这一轮不写体内的过程，只写"装不住了"的那一下：'
          + '话断在半句、身体从支撑物上滑下去、几秒里发不出声音；随后是脱力、发愣、手抖，以及收拾自己。'
          + '不要写慢慢积累的过程，也不要把重点放在"装置停了"上。');
    }
    // 三档互斥：谁被作用、谁拿遥控器、正文该写谁
    if (S.target === 'user') {
      L.push('· 被作用的是玩家，不是你。写 ' + cn + ' 的掌控动作、表情变化和说的话；玩家身体上的外在反应可以写，但不要替玩家写内心想法和台词。');
    } else if (selfT) {
      L.push('· 装置和遥控器都在玩家自己身上，没有人在操控。不要安排 ' + cn + ' 或任何人登场来拿遥控器、调档位、发现装置；'
        + '场景里如果有别人，他们只能注意到玩家外在的异样，不知道原因。');
    } else {
      L.push('· 装置戴在 ' + cn + ' 身上，玩家身上没有装置，玩家手里只有遥控器。不要写成玩家自己在被震动，也不要把遥控器写到 ' + cn + ' 手里。');
    }
    if (S.actions.length) {
      if (S.target === 'user') {
        L.push('· 回复的开头先用一两句话写 ' + cn + ' 刚才这些操作（按了什么键、拨到哪一档），再接着写玩家身体上的反应。动作描写要简短。');
      } else if (selfT) {
        L.push('· 回复的开头先用一两句话写玩家刚才自己按下的这些操作（按了什么键、拨到哪一档），再接着写玩家自己的身体反应。动作描写要简短，不要替玩家说台词。');
      } else {
        L.push('· 回复的开头先用一两句话，从玩家的视角描写玩家刚才这些操作（按了什么键、拨到哪一档），再接着写 ' + cn + ' 的身体反应。动作描写要简短，不要展开成玩家的心理活动，也不要替玩家说台词。');
      }
    }
    if (S.on) {
      L.push('· 装置此刻正在运行。不要描写它被关闭、被取下、被调低，也不要假设玩家按了上面没提到的键。');
    } else {
      L.push('· 装置此刻不在运行，可以写余韵和恢复，但不要描写新的震动。');
      if (S.stopReason) L.push('· 停止原因：' + S.stopReason + '。按这个原因来写，不要改写成玩家手动关掉。');
    }
    if (selfT) {
      // 没有别人可写：主体落在玩家身上，这一档允许写玩家的身体与内心感受，但主动决定仍归玩家
      L.push('· 正文主体是玩家的身体反应与周围环境：写清部位、程度、玩家在忍什么，以及声音、别人的目光、手头正在做的事被打断。'
        + '这一档允许写玩家的身体与内心感受，但不要写结论句。');
      L.push('· 不要替玩家做主动决定：不替玩家改档位、不替玩家关掉装置、不替玩家说台词（不自主漏出的气音、闷哼可以写）。');
    } else {
      L.push('· 正文主体是 ' + cn + ' 的反应：写清部位、程度、' + cn + ' 的应对，以及环境声音的变化，不要写结论句。');
      L.push('· 不要替玩家行动、说话，也不要替玩家决定剧情走向。');
    }
    L.push('');
    // 面板上只显示这一句，正文在聊天记录里已经有了，面板再放一遍就是重复
    if (!forVar) {
      L.push('【正文之后另起一行，附一句心声】');
      L.push('格式必须完全照下面这样，单独一行：');
      if (selfT) {
        L.push('<TOY>心声=玩家此刻心里真正压不住的念头</TOY>');
        L.push('· 写玩家此刻心里真正压不住的念头，不是嘴上说的 —— 越是装没事，这里越要写实话。');
      } else {
        L.push('<TOY>心声=' + cn + '此刻心里真正的想法</TOY>');
        L.push('· 写 ' + cn + ' 心里想的，不是嘴上说的 —— 口是心非的时候，这里要写实话。');
    }
    L.push('· 一句话，25 字以内，不要引号，不要句号结尾。');
    L.push('· 这一行是给面板读的，正文里绝对不要提到它，也不要解释这是什么。');
    }
    L.push('· 不要出现"装置状态""系统""面板""数据"这类词，也不要复述上面的数字，用身体去表现它们。');
    // 模式名里如果出现"重击"这类打击乐比喻，模型会顺着写成"砰、砰"的敲击声。
    // 它贴在皮肤上高频震颤，不是被敲打，所以这一条必须写死。
    if (suck) {
      // 吸吮式不是震：照搬下面那两条会把它写成「嗡嗡发麻」
      L.push('· 它是**吸**，不是震，也不是敲：感受是被抽吸、被拉扯、含住又松开，不要写"震""嗡""麻"，'
        + '也不要写"砰""咚""啪"这类撞击声和"砸""捶""碾""撞开"这类动作。');
      L.push('· 它几乎无声 —— 大多数情况下不用写声音；要写就写极轻的、贴身的抽吸声，不要写有节拍的闷响。');
    } else {
      L.push('· 它是**震**，不是敲：感受是麻、酥、酸、发胀，不要写"砰""咚""啪"这类撞击声，'
        + '也不要写"砸""捶""碾""撞开"这类动作。');
      L.push('· 它只有极轻的嗡鸣，贴身几乎听不出来 —— 大多数情况下不用写声音；'
        + '要写就写持续的低频"嗡"，不要写有节拍的闷响。');
    }
    return L.join('\n');
  }

  /* 「自动反应」默认关闭。老存档里的 true 是旧默认塞进去的，不算用户选择 ——
     AUTO_SET_STAMP 记下"用户开始自己管这个开关"的版本，早于 AUTO_DEFAULT_FROM 的值一律不认。 */
  var AUTO_DEFAULT_FROM = '1.13.30';
  var AUTO_SET_STAMP = '';

  var LAST_VARS_SIG = '';
  function syncVars(reactive) {
    if (!BRIDGE.ready) return false;
    var m = modeById(S.mode);
    var payload = {
      toy_on: S.on ? 'on' : 'off',
      toy_mode: S.mode,
      toy_mode_name: m.name,
      toy_freq: S.freq,
      toy_hz: hz().toFixed(1),
      toy_intensity: S.pow,
      toy_elapsed: fmtTime(S.t),
      toy_elapsed_sec: Math.round(S.t),
      toy_stage: S.stage,
      toy_stage_name: STAGES[S.stage - 1].name,
      toy_arousal: Math.round(S.aro),
      toy_peak: S.peak,
      toy_limit: S.limit,
      // 阶段值满不满 / 还涨不涨 —— AI 得知道现在是不是"顶到头了"，不然会继续写"一路往上"
      toy_full: S.hi ? 'on' : 'off',
      toy_hold: S.hold ? 'on' : 'off',
      toy_slow: Math.round((S.slow || 1) * 100),
      toy_last_event: S.lastEvent,
      toy_state: stateText(true)
    };
    var sig = JSON.stringify(payload);
    if (sig === LAST_VARS_SIG) return true;          // 无变化就不打扰酒馆
    LAST_VARS_SIG = sig;
    var ok = BRIDGE.setVars(payload, 'chat');
    if (ok && !reactive) toast('状态已同步到酒馆变量');
    return ok;
  }

  function injectOnce() {
    if (!S.inject || !BRIDGE.ready) return null;
    return BRIDGE.inject([{
      id: 'toy_state_sync',
      position: 'in_chat',
      depth: 0,
      role: 'system',
      content: stateText(),
      should_scan: true
    }], { once: true });
  }

  function react(kind, force) {
    if (!S.auto && !force) return;

    // 装置没在运行时调参数只是预设置，不叫 AI 说话。
    // 预置的动作会留在动作序列里，等按下启动键时一起交代给 AI。
    var paramEvent = (kind === 'mode' || kind === 'freq' || kind === 'power');
    if (paramEvent && !S.on) return;

    if (BRIDGE.ready === false) { fakeReact(kind); return; }
    var now = Date.now();
    // 启停与手动冲击是即时动作，不受冷却约束；求人停下更不该等冷却
    var hard = (kind === 'manual' || kind === 'burst' || kind === 'start' || kind === 'stop'
      || kind === 'beg' || (kind === 'stage' && S.stageForce));
    if (!force && !hard && now - LAST_REACT < S.cd * 1000) {
      // 冷却期间的操作不丢弃：记下来，冷却一结束用最新状态补触发一次。
      // 连续调几个参数只会补一次，动作序列会把它们一起带过去。
      PEND_KIND = kind;
      clearTimeout(PEND_TIMER);
      PEND_TIMER = setTimeout(function () {
        var k = PEND_KIND;
        PEND_KIND = null;
        if (k) react(k);
      }, Math.max(600, S.cd * 1000 - (now - LAST_REACT) + 200));
      return;
    }
    LAST_REACT = now;

    syncVars(true);
    pushMsg('sys', kindLabel(kind));

    if (S.drive === 'inner') {
      innerGenerate();
    } else {
      floorTrigger();
    }
  }

  function kindLabel(kind) {
    switch (kind) {
      case 'mode': return '切换模式 → ' + modeById(S.mode).name;
      case 'freq': return '频率调整 → ' + hz().toFixed(1) + ' Hz';
      case 'power': return '强度调整 → ' + S.pow + '%';
      case 'stage': return '阶段跃迁 → 第 ' + S.stage + ' 阶段 · ' + STAGES[S.stage - 1].name;
      case 'peak': return '临界爆发';
      case 'start': return '装置启动';
      case 'stop': return '装置停止' + (S.stopReason ? '（' + S.stopReason + '）' : '');
      case 'manual': return '手动触发';
      case 'burst': return '冲击键';
      case 'beg': return '开口请求 ' + charName() + ' 停下（第 ' + S.beg + ' 次）';
      default: return '状态同步';
    }
  }

  /* =========================================================
   * 世界书自管理
   * 把上面那套通用设定写进一本世界书，并挂到当前角色卡，
   * 这样脚本装到任何角色卡上都能直接用，不必另外导世界书。
   * 两条安全线：不覆盖用户自己的同名世界书；不抢角色卡的主世界书。
   * ======================================================= */
  function wbEntriesForTavern() {
    var useUser = (S.target === 'user');
    var useSelf = (S.target === 'self');
    var useMale = (S.body === 'male');
    var usePlain = !S.explicit;   // 忍耐 · 假装镇定：只写外部可观察的表现
    var altMap = useUser ? WB_ENTRIES_ALT : (useSelf ? WB_ENTRIES_ALT_SELF : null);
    // 装置形态：描述句里的主语按作用对象换（char 档戴在 {{char}} 身上，另两档戴在 {{user}} 身上）
    var dev = devOf();
    var devDesc = dev.desc.split('__WEARER__').join(S.target === 'char' ? '{{char}}' : '{{user}}');
    var vibeNote = (S.dev === 'suck') ? WB_SUCK_NOTE : WB_VIBE_NOTE;
    var devFeel = ['【装置形态 · ' + dev.name + ' 怎么写】']
      .concat(usePlain ? ['（忍耐档：下面只取看得见的部分——动作、姿态、被打断的地方；体内的感觉照样不写。）'] : [])
      .concat(dev.feel).join('\n');
    var list = WB_ENTRIES.map(function (e) {
      var alt = altMap && altMap[e.name];
      var src = alt || e;
      var content = src.content;
      var keys = e.keys || [];
      // 描写尺度优先于身体版本：忍耐档下男女各有一版外部表现条目
      // ④ 按被作用者的身体换整条：男女的顶点机制不同，不能共用一套
      if (usePlain && e.name === '⑧ 临界与停机（关键词触发）') {
        content = WB_PEAK_PLAIN;
      } else if (usePlain && e.name === '⑪ 感受链怎么写（常驻）') {
        content = WB_CHAIN_PLAIN;
      } else if (e.name === '④ 强度档位 × 身体反应（常驻）') {
        content = usePlain
          ? (useMale ? WB_BODY_PLAIN_M : WB_BODY_PLAIN_F)
          : (useMale ? WB_BODY_MALE : content);
      } else if (usePlain && WB_PLAIN_ADDON[e.name]) {
        content = content + '\n' + WB_PLAIN_ADDON[e.name];
      }
      // 装置形态：①③ 的描述句、⑨ 末尾的「震还是吸」、⑪ 末尾追加一段写法、③ 的触发词
      content = content.split('__DEV__').join(devDesc).split('__VIBE__').join(vibeNote);
      if (e.name === '⑪ 感受链怎么写（常驻）') content = content + '\n\n' + devFeel;
      if (e.name === '③ 装置设定（关键词触发）') {
        keys = keys.concat(dev.keys.filter(function (k) { return keys.indexOf(k) < 0; }));
      }
      return {
        name: e.name,
        enabled: true,
        strategy: {
          type: e.strategy === 'selective' ? 'selective' : 'constant',
          keys: keys,
          keys_secondary: { logic: 'and_any', keys: [] },
          scan_depth: 'same_as_global'
        },
        position: {
          type: e.position,
          role: e.role || 'system',
          depth: e.depth || 4,
          order: e.order || 100
        },
        content: content,
        probability: 100,
        recursion: { prevent_incoming: false, prevent_outgoing: false, delay_until: null },
        effect: { sticky: null, cooldown: null, delay: null },
        extra: { toylink_managed: VERSION }   // 标记：这本世界书由本脚本管理
      };
    });
    if (useUser || useSelf) {
      var x = useSelf ? WB_EXTRA_SELF : WB_EXTRA_USER;
      list.push({
        name: x.name,
        enabled: true,
        strategy: { type: 'constant', keys: [], keys_secondary: { logic: 'and_any', keys: [] }, scan_depth: 'same_as_global' },
        position: { type: x.position, role: x.role, depth: x.depth, order: x.order },
        content: x.content,
        probability: 100,
        recursion: { prevent_incoming: false, prevent_outgoing: false, delay_until: null },
        effect: { sticky: null, cooldown: null, delay: null },
        extra: { toylink_managed: VERSION }
      });
    }
    // 归属条目永远排在最后（数组末尾），确保它是注入列表里最靠后、最贴近最新消息的一条
    var anchor = WB_ANCHOR;
    list.push({
      name: anchor.name,
      enabled: true,
      strategy: { type: 'constant', keys: [], keys_secondary: { logic: 'and_any', keys: [] }, scan_depth: 'same_as_global' },
      position: { type: anchor.position, role: anchor.role, depth: anchor.depth, order: anchor.order },
      content: useUser ? WB_ANCHOR_USER.content : (useSelf ? WB_ANCHOR_SELF.content : anchor.content),
      probability: 100,
      recursion: { prevent_incoming: false, prevent_outgoing: false, delay_until: null },
      effect: { sticky: null, cooldown: null, delay: null },
      extra: { toylink_managed: VERSION }
    });
    // 「对方是谁」：填了名字就把所有 {{char}} 换成它。用 split/join 不用正则，名字里有什么符号都原样保留
    var hold = (typeof S.holder === 'string') ? S.holder.trim() : '';
    if (hold) {
      list.forEach(function (it) { it.content = it.content.split('{{char}}').join(hold); });
    }
    return list;
  }

  function syncWorldbook(silent) {
    if (!S.manageWb || !BRIDGE.ready) return;
    var listFn = th('getWorldbookNames');
    var getFn = th('getWorldbook');
    var putFn = th('createOrReplaceWorldbook');
    var charFn = th('getCharWorldbookNames');
    var bindFn = th('rebindCharWorldbooks');
    if (!listFn || !putFn) {
      console.log('[TOY·LINK] 当前酒馆助手没有世界书接口，跳过自动建库');
      return;
    }

    var bind = function () {
      if (!charFn || !bindFn) return;
      try {
        var cur = charFn('current') || {};
        var add = cur.additional || [];
        if (add.indexOf(WB_NAME) >= 0) return;
        var done = function () { if (!silent) toast('装置设定已挂到当前角色卡'); };
        var p = bindFn('current', { primary: cur.primary || null, additional: add.concat([WB_NAME]) });
        if (p && p.then) p.then(done, function () { /* noop */ }); else done();
      } catch (e) { /* noop */ }
    };

    var write = function () {
      try {
        var p = putFn(WB_NAME, wbEntriesForTavern(), { render: 'none' });
        if (p && p.then) p.then(bind, function () { /* noop */ }); else bind();
      } catch (e) { bind(); }
    };

    var names = [];
    try { names = listFn() || []; } catch (e) { names = []; }

    if (names.indexOf(WB_NAME) < 0) { write(); return; }

    // 已存在：只有带本脚本标记的才更新，避免覆盖用户自己的同名世界书
    if (!getFn) { bind(); return; }
    var check = function (wb) {
      var mine = (wb || []).some(function (e) { return e && e.extra && e.extra.toylink_managed; });
      if (mine) { write(); return; }
      console.log('[TOY·LINK] 已有同名世界书但不是本脚本建的，保持原样，只做绑定');
      bind();
    };
    try {
      var r = getFn(WB_NAME);
      if (r && r.then) r.then(check, function () { /* noop */ }); else check(r);
    } catch (e) { bind(); }
  }

  // ---- 路线一：写入隐藏楼层 + 触发发言（回复落在酒馆聊天里） ----
  // 酒馆在生成回复期间会拒绝 /trigger，所以生成中先把请求记下来，等结束再补。
  // 注意生成结束的信号不止一个：正常结束是 generation_ended，
  // 被停止按钮打断是 generation_stopped，面板内 generate() 走的是 js_generation_*。
  var BUSY = false, PENDING = false, PENDING_TIMER = 0, BUSY_GUARD = 0;
  var BUSY_SINCE = 0, BUSY_WATCH = 0;

  /* 我们自己掌控的"剧情时间暂停"标记。
     为什么不用 BUSY：BUSY 是靠酒馆事件推出来的，事件可能被别的东西提前打断
     （比如别的生成结束、消息事件），一旦被误清，冻结就悄悄失效了。
     HOLD 只在"我们确实发起了一次生成"时打开，在它自己的回调里关闭，
     不依赖任何外部事件，所以冻结一定站得住。 */
  var HOLD = false, HOLD_GUARD = 0;

  function holdOn() {
    HOLD = true;
    clearTimeout(HOLD_GUARD);
    HOLD_GUARD = setTimeout(function () { HOLD = false; }, 180000);
  }
  function holdOff() {
    HOLD = false;
    clearTimeout(HOLD_GUARD);
  }

  function markBusy() {
    if (!BUSY) BUSY_SINCE = Date.now();
    BUSY = true;
    // 保险丝一：无论事件有没有丢，180 秒后自动解除，避免永久卡在"生成中"
    clearTimeout(BUSY_GUARD);
    BUSY_GUARD = setTimeout(function () { markIdle(); }, 180000);
    startWatch();
  }

  function markIdle() {
    clearTimeout(BUSY_GUARD);
    if (BUSY_WATCH) { clearInterval(BUSY_WATCH); BUSY_WATCH = 0; }
    if (!BUSY && !PENDING) return;
    BUSY = false;
    if (PENDING) {
      PENDING = false;
      clearTimeout(PENDING_TIMER);
      setTimeout(function () { floorTrigger(); }, 300);
    }
  }

  /* 问一次酒馆到底在不在生成：
   * true = 明确在生成，false = 明确没在生成，null = 判断不了 */
  function externalGen() {
    try {
      if (typeof SillyTavern !== 'undefined' && SillyTavern && typeof SillyTavern.getContext === 'function') {
        var c = SillyTavern.getContext();
        if (c && typeof c.isGenerating === 'function') return !!c.isGenerating();
      }
    } catch (e) { /* noop */ }
    try {
      // 生成中时酒馆的发送按钮会变成停止图标。用原生查询，不依赖 jQuery 版本差异。
      var btn = DOC.querySelector('#send_but');
      if (btn) return !!btn.querySelector('.fa-stop');
    } catch (e) { /* noop */ }
    return null;
  }

  /* 保险丝二：看门狗。事件全丢的时候把冻结解开。
   * 酒馆明确说没在生成就立刻解冻；判断不了就等 90 秒。 */
  function startWatch() {
    if (BUSY_WATCH) return;
    BUSY_WATCH = setInterval(function () {
      if (!BUSY) { clearInterval(BUSY_WATCH); BUSY_WATCH = 0; return; }
      if (Date.now() - BUSY_SINCE < 4000) return;   // 刚进入生成，给它一点时间
      var g = externalGen();
      if (g === false) markIdle();
      else if (g === null && Date.now() - BUSY_SINCE > 90000) markIdle();
    }, 2000);
  }

  function stBusy() {
    if (BUSY) return true;
    return externalGen() === true;
  }

  function findStateFloor() {
    var f = th('getChatMessages');
    if (!f) return -1;
    var id = BRIDGE.lastMsgId();
    if (id < 0) return -1;
    var lo = Math.max(0, id - 15);
    try {
      var arr = f(lo + '-' + id, { hide_state: 'hidden' }) || [];
      for (var i = arr.length - 1; i >= 0; i--) {
        var t = arr[i] && arr[i].message;
        if (typeof t === 'string' && t.indexOf('【装置状态同步】') === 0) return arr[i].message_id;
      }
    } catch (e) { /* noop */ }
    return -1;
  }

  var ACTION_EXPIRE = 0;

  /* 动作序列要两条通道都走：
   * 1) 注入（injectPrompts）—— 只对这一次生成有效，干净但可能被环境吞掉；
   * 2) 聊天变量 toy_state —— 世界书条目读的就是它，实测最可靠。
   * 变量这份在触发后保留 25 秒再清掉，既够 AI 读到，又不会在后续几轮里
   * 反复描述同一个操作。 */
  function scheduleActionExpiry() {
    clearTimeout(ACTION_EXPIRE);
    ACTION_EXPIRE = setTimeout(function () { syncVars(true); }, 25000);
  }

  /* 直接用 generate 请求生成，绕开 /trigger。
   * 酒馆在生成期间会拒绝 /trigger（弹「在回复生成时无法运行 /trigger 命令」），
   * 而 generate 走的是酒馆助手自己的请求通道，不吃这个限制。
   * 回复拿到后用 createChatMessages 落进聊天记录，观感与 /trigger 一致。 */
  function generateToChat() {
    markBusy();
    holdOn();          // 我们发起的生成，冻结由自己开关
    markPending(true); // 遥控器在 TA 手里时，先摆出"等 TA 决定"的中间态
    var res = BRIDGE.gen({
      user_input: '（装置控制台同步，接着上一楼继续）',
      should_stream: false,
      should_silence: false,
      injects: innerInjections()
    });
    S.actions.length = 0;   // 这批动作已经交给 AI 了
    scheduleActionExpiry();

    var done = function (text) {
      markIdle();
      holdOff();
      var d = applyToyDirective(typeof text === 'string' ? text : '');
      markPending(false);   // 面板此刻显示的已经是 TA 刚选定的那一档
      var body = cleanReply(d.text);
      if (!body) { toast('没有拿到回复，检查 API 与预设'); settleBeg(false); return; }
      settleBeg(true);      // 回复到了才算数：TA 答没答应，这里结账
      BRIDGE.addMsg({ role: 'assistant', message: body });
      // 面板上只放心声（文字说明），正文已经在聊天记录里了。
      // 语音是另一条内容：AI 明写的台词优先，否则按档位从台词库取 —— 每轮都会有一句。
      /* 语音：优先取正文里的对白（这样听到的就是读到的那句），正文没有对白才用读数里的语音字段 */
      var vt = voiceFor(d.voice, S.stage, null, body).text;
      pushMsg('ai', d.heart || heartFallback(), vt, body);
    };
    if (res && res.then) res.then(done, function () { markIdle(); holdOff(); markPending(false); settleBeg(false); }); else done('');
  }

  function floorTrigger() {
    if (!BRIDGE.ready) { fakeReact('auto'); return; }

    // 默认走 generate：不会撞上酒馆的生成锁，也就没有那条报错
    if (S.sendMode === 'generate' && th('generate')) { generateToChat(); return; }

    if (stBusy()) {
      // AI 正在生成，插队会撞上酒馆的「无法运行 /trigger」拦截
      if (PENDING) return;
      PENDING = true;
      // 兜底：万一结束事件没来（中断、报错），12 秒后自己重试一次
      clearTimeout(PENDING_TIMER);
      PENDING_TIMER = setTimeout(function () {
        if (PENDING) { PENDING = false; BUSY = false; floorTrigger(); }
      }, 12000);
      return;
    }
    var payload = stateText();
    var fire = function () { BRIDGE.slash('/trigger'); };

    // 首选：把状态作为 system 提示注入到最新位置，只对这一次生成有效。
    // 不写进聊天记录，AI 也不会把它当成玩家说的话来接。
    // 注意：动作序列必须在注入之后才清空，否则注入的那一份会是空的。
    if (S.inject && th('injectPrompts')) {
      injectOnce();
      S.actions.length = 0;
      fire();
      scheduleActionExpiry();
      return;
    }

    S.actions.length = 0;
    scheduleActionExpiry();
    // 兜底：老版本酒馆助手没有注入接口时，退回写一条隐藏楼层
    var after = fire;
    var reuse = findStateFloor();
    if (reuse >= 0) {
      // 复用最近的状态楼层，避免隐藏楼层无限堆积
      var setF = th('setChatMessages');
      if (setF) {
        try {
          setF([{ message_id: reuse, message: payload }], { refresh: 'none' });
          after();
          return;
        } catch (e) { /* 退化到新建楼层 */ }
      }
    }
    var p = BRIDGE.addMsg({ role: 'user', message: payload, is_hidden: true }, { refresh: 'none' });
    if (p && p.then) p.then(after, after); else after();
  }

  // ---- 路线二：界面内自行生成并落库 ----
  // 预设常会带出容器标签、流程注释、草稿标记，面板里只留正文与对白
  var CLEAN_FORMAT_PROMPT = [
    '【输出格式】只输出角色这一轮的动作神态与对白本身。',
    '不要输出任何标签、注释、分隔线、标题、进度标记、草稿或思考过程；',
    '诸如 <!-- -->、<content>、<ts>、### 这类东西一律不要出现在输出里。',
    '不要复述状态数据，也不要写"正文""第一段""草稿"这类结构提示。'
  ].join('\n');

  function cleanReply(text) {
    if (!text) return '';
    var t = String(text);
    t = t.replace(/<TOY>[\s\S]*?<\/TOY>/gi, '');   // 装置读数由脚本消费，不给玩家看
    t = t.replace(/<!--[\s\S]*?-->/g, '');
    t = t.replace(/<(think|thinking|reasoning|analysis|scratchpad|chain_of_thought)\b[^>]*>[\s\S]*?<\/\1>/gi, '');
    t = t.replace(/<\/?(content|maintext|main_text|reply|output|正文|内容|输出)\b[^>]*>/gi, '');
    t = t.replace(/<ts\b[^>]*>[\s\S]*?<\/ts>/gi, '');   // 情绪标注整块（含角色名/情绪这类元信息）
    t = t.replace(/<\/?ts\b[^>]*>/gi, '');
    t = t.replace(/^\s*#{1,6}\s*(正文|回复|内容|输出)\s*$/gmi, '');
    t = t.replace(/^\s*```[a-zA-Z]*\s*$/gmi, '');
    t = t.replace(/\n{3,}/g, '\n\n');
    return t.trim();
  }

  /* 遥控器在角色手里时的"决策格式"。
     这一档下玩家不是操控方，面板上的按钮只是"推进一次"的信号，
     调到什么档、想达到什么效果由角色自己决定；角色把这个决定写进一行读数，
     脚本解析后把面板切到那一档——所以是"读完回复界面才变"，而不是反过来。 */
  function decidePrompt() {
    var cn = charName();
    var L = [
      '【这一轮由你决定装置怎么用】',
      '遥控器在 ' + cn + ' 手里。玩家按下的只是一个"开始"的信号，'
        + '具体调到什么档、想达到什么效果，由你按 ' + cn + ' 的性格与此刻的心情决定。',
      '',
      '正文写完之后，另起一行附上装置读数，格式必须完全照下面这样：',
      '<TOY>开关=开|模式=潮汐|频率=45|强度=70|说明=想让你在人前先开口求他|心声=嘴上说着求我，其实自己也快撑不住了|语音=乖，坐好，别出声</TOY>',
      '',
      '规则：',
      '· 开关填「开」或「关」。填「关」表示这一轮把装置停了。',
      '· 模式只能填这九个之一：脉冲、潮汐、心跳、渐强、乱流、撩拨、暴雨、临界、冲刺。',
      '· 频率与强度填 1-100 的整数。',
      '· 说明用一句短话写清这次想干什么、想看到什么样的反应。',
      '· 心声写 ' + cn + ' 此刻心里真正的想法，不是嘴上说的话，一句话、25 字以内。'
        + '面板上只显示这一句，所以它要能独立看懂。',
      '· 语音填 ' + cn + ' 这一轮**说出口**的话。**每一轮都必须填，不能留空** —— 它会被直接念成声音。',
      '· 语音要写成 **2 到 3 行**，每行都是一句能念出来的话，**每行开头都要带情绪标记**。',
      '· 每行 **35-48 字**，长度照着下面正确例子来 —— 太短会"啊……"一下就没了，'
        + '太长会变成朗读。用省略号、破折号把句子断开，让它在气声里一段段漏出来。',
      '· 标记用方括号，可以写英文固定标记（[panting] [gasping] [sobbing] [whispering] [soft tone] '
        + '[nervous] [pleased] [chuckling] [sighing]）或中文描述（[气声] [颤抖] [压低的声音] [黏腻]）；'
        + '一行最多叠 3 个。',
      '· 三行之间要有推进：从**试探**到**说透**，最后一句可以是**退让、打岔或撒娇**收尾。',
      '· 语音里**只写能念出来的话**：拟声（哈啊……不、不行……）、短命令（乖，坐好。求我。）、'
        + '压在喉咙里的碎音。**不要写动作、不要写旁白、不要用括号包住叙述** ——'
        + '"低下头""呼吸乱了一拍"这类是给眼睛看的，写在正文和心声里。',
      '· 语音里**不许出现读数里的任何信息** —— 不许写模式名（脉冲／潮汐／心跳／渐强／乱流／撩拨／暴雨／临界／冲刺）、'
        + '开关状态、频率、强度、累积、阶段。那些只写在上面那几个字段里。'
        + '**「暴雨」「撩拨」这种词单独出现时会被当成噪音念出来**，玩家听到的就是一句莫名其妙的档位名。',
      '· 语音里**不许写环境音和装置声** —— 嗡嗡声、嗡鸣、电流声、马达声、震动声、底噪，'
        + '这些都不是 ' + cn + ' 说出口的话。它们只写在正文里。',
      '· 语音要写成 ' + cn + ' **直接说出口的话**，不要叙述：'
        + '不要出现"她/他/它/自己"，也不要写"咬着牙""撑着""忍不住""慢慢"这种描写的动作 ——'
        + '一句台词是关于"我"和"你"的，不是关于第三个人在做什么的。',
      '· 反例（这些都会被丢掉，别写）：[喘息] 嗡嗡声还在继续 ／ [气声] 她咬着牙想维持住 ／ [气声] 撩拨',
      '· 正确例子（照这个**长度和格式**写：2-3 行，每行开头都是方括号标记）：',
      '　[soft tone][whispering] 你怎么还没睡呀……我都醒了有一会儿了，听着你在那边翻身……',
      '　[inhale] 我只是……有点想你了。也没别的事，就是忽然想听听你的声音，没打扰你吧？',
      '　[short pause][chuckling] 好啦，别笑我……我说完这句就不说了，你先去忙你的……',
      '· 这一行是给装置读的，正文里绝对不要提到它，也不要解释这是什么。'
    ];

    // 玩家按了「请求停下」：这一轮的重点从"怎么调"变成"肯不肯放"
    if (S.beg > 0) {
      var give = S.begDocile || (S.beg >= S.begNeed);
      L.push('');
      L.push('【玩家在求你停下】');
      L.push('这是第 ' + S.beg + ' 次开口。' + cn + ' 的语气一次比一次软，'
        + '这一次' + (S.beg === 1 ? '还带着点不好意思' : (S.beg === 2 ? '已经是在服软了' : '几乎是明着认输')) + '。');
      if (give) {
        L.push('这一轮应当答应：让 ' + cn + ' 松口，把装置停下。'
          + '正文写 ' + cn + ' 停手之后的样子——那口终于松下来的气、余韵、'
          + '以及 ' + cn + ' 对玩家服软的反应（得意、心疼、或者嘴上不认但手上停了，按性格来）。');
        L.push('读数里的「开关」填「关」。');
      } else {
        L.push('按 ' + cn + ' 的性格，这一次可以不听——' + cn + ' 还想再看一会儿，或者故意拖着不答应，'
          + '甚至反过来把档位往上拨一点。');
        L.push('但不许写死：如果 ' + cn + ' 的人设本来就不忍心，也可以提前答应。');
        L.push('读数里的「开关」按你的决定填：答应了填「关」，没答应填「开」。');
      }
    }
    return L.join('\n');
  }

  /* 解析回复里的装置读数，把面板切到那一档。返回剥离读数后的正文。 */
  function applyToyDirective(text) {
    var raw = String(text || '');
    var cn = charName();
    var m = /<TOY>([\s\S]*?)<\/TOY>/i.exec(raw);
    if (!m) return { text: raw, applied: false };
    var body = m[1];
    var pick = function (k) {
      var r = new RegExp(k + '\\s*[=:：]\\s*([^|｜\\r\\n]+)');
      var mm = r.exec(body);
      return mm ? mm[1].trim() : '';
    };

    var powerOn = pick('开关');
    var modeName = pick('模式');
    var freq = parseInt(pick('频率'), 10);
    var pow = parseInt(pick('强度'), 10);
    var note = pick('说明');
    var heart = pick('心声');   // 面板上显示这一句，不放正文
    var voice = pick('语音');   // 这一轮要说出口的话，交给语音念出来

    // 只有遥控器在 TA 手里时，读数里的档位才算数。另两档遥控器在玩家手里，AI 只交心声；
    // 以前这里不分档，每条回复都会把「最近变化」写成「××调到：维持原档」——
    // 自己玩那一档里 ×× 是「系统」「旁白」，AI 读到就以为有人拿着遥控器。
    if (S.target !== 'user') {
      return { text: raw.replace(/<TOY>[\s\S]*?<\/TOY>/gi, '').trim(), applied: false, heart: heart, voice: voice };
    }

    var changed = [];
    var i;
    var wanted = null;
    for (i = 0; i < MODES.length; i++) {
      if (MODES[i].name === modeName && MODES[i].id !== S.mode) { wanted = MODES[i]; break; }
    }
    /* 锁着的档不接受 —— 否则 AI 一句"模式=冲刺"就把阶段解锁绕过去了。
       只有玩家手动切才带 modeForce；机器播报里说的模式不越权。 */
    if (wanted && modeOpen(wanted.id)) {
      S.mode = wanted.id;
      var nodes = $('#modes').children;
      for (var k = 0; k < nodes.length; k++) nodes[k].classList.toggle('on', nodes[k].dataset.id === S.mode);
      changed.push('模式「' + wanted.name + '」');
    } else if (wanted) {
      VOC.addLog('AI 想切到还没解锁的「' + wanted.name + '」，已忽略', 'warn');
    }
    if (freq >= 1 && freq <= 100 && freq !== S.freq) {
      S.freq = freq;
      var fe = $('#freq'); if (fe) { fe.value = freq; paintSlider(fe); }
      changed.push('频率 ' + hz().toFixed(1) + ' Hz');
    }
    if (pow >= 1 && pow <= 100 && pow !== S.pow) {
      S.pow = pow;
      var pe = $('#pow'); if (pe) { pe.value = pow; paintSlider(pe); }
      changed.push('强度 ' + pow + '%');
    }
    if (powerOn === '开' && !S.on) {
      startSilent();
      changed.push('已启动');
    } else if (powerOn === '关' && S.on) {
      stop(cn + '关掉了装置', true);
      changed.push('已停止');
    }

    S.lastEvent = cn + '调到：' + (changed.length ? changed.join('，') : '维持原档');
    if (note) S.lastActionNote = note;
    render();
    syncVars(true);

    if (changed.length) {
      toast(cn + '调到了 ' + changed.join('，'), 2600);
    } else if (note) {
      toast(cn + '的想法：' + note, 2600);
    }
    return { text: raw.replace(/<TOY>[\s\S]*?<\/TOY>/gi, '').trim(), applied: true, note: note, heart: heart, voice: voice };
  }

  /* 用户和状态之间的翻译层：拿不到心声时不要编。
     硬凑一句"她心里想着……"是假的，不如老实报当前档位。 */
  function heartFallback() {
    if (!S.on) return wearerName(true) + '还没被碰到 · 装置待机';   // 装置戴在谁身上就说谁
    return '强度 ' + S.pow + '% · 第 ' + S.stage + ' 阶段·' + STAGES[S.stage - 1].name;
  }

  function innerInjections() {
    var arr = [];
    if (S.inject) {
      arr.push({ role: 'system', content: stateText(), position: 'in_chat', depth: 0, should_scan: true });
    }
    // 遥控器在她手里时，档位由她决定，得额外告诉模型怎么把决定交回来
    if (S.target === 'user') {
      arr.push({ role: 'system', content: decidePrompt(), position: 'in_chat', depth: 0, should_scan: false });
    }
    arr.push({ role: 'system', content: CLEAN_FORMAT_PROMPT, position: 'in_chat', depth: 1, should_scan: false });
    return arr;
  }

  function innerGenerate() {
    if (!BRIDGE.ready) { fakeReact('auto'); return; }
    var holder = pushMsg('ai', '');
    var bubble = holder.querySelector('.bubble');
    bubble.classList.add('blink', 'now');
    // 流式期间只往这个 span 里写字：这样结束后能整条换成"台词 + 说明 + 播放键"的结构，
    // 不会被流式文本冲掉。流式过程照旧看得见，只是不参与最终排版。
    var live = document.createElement('span');
    live.className = 'live';
    bubble.appendChild(live);
    var buf = '';
    var streamFn = function (text) {
      buf = text || '';
      live.textContent = cleanReply(buf);
      scrollFeed();
    };
    var offStream = function () {
      var f = th('eventRemoveListener');
      if (f) { try { f(EVT.STREAM_FULL, streamFn); } catch (e) { /* noop */ } }
    };
    BRIDGE.on(EVT.STREAM_FULL, streamFn);

    markBusy();
    holdOn();
    markPending(true);   // 遥控器在 TA 手里时，先摆出"等 TA 决定"的中间态
    var res = BRIDGE.gen({
      user_input: '（装置控制台同步，接着上一楼继续）',
      should_stream: true,
      should_silence: false,
      injects: innerInjections()
    });
    var finish = function (text) {
      offStream();
      markIdle();
      holdOff();
      var d = applyToyDirective((typeof text === 'string' && text) ? text : buf);
      markPending(false);   // 面板此刻显示的已经是 TA 刚选定的那一档
      var body = cleanReply(d.text);
      if (body) {
        // 整条重建：先取好台词（AI 明写的优先，否则按档位从台词库取），
        // 再把 holder 换成标准的「说明 + 台词 + 播放键」结构 —— 和另一条路径一致。
        var vt2 = voiceFor(d.voice, S.stage, null, body).text;
        holder.remove();
        pushMsg('ai', d.heart || heartFallback(), vt2, body);
        BRIDGE.addMsg({ role: 'assistant', message: body }, { refresh: 'none' });
        settleBeg(true);
      } else {
        holder.remove();
        toast('没有拿到回复，检查 API 与预设');
        settleBeg(false);
      }
      scrollFeed();
    };
    if (res && res.then) res.then(finish, finish); else finish('');
  }

  // ---- 离线演示 ----
  // 每组 = 正文（可能带引号对白）+ 说明文字 + 兜底台词。
  // 带对白的组演示"正文说什么就念什么"；不带的组演示"正文没对白 → 用台词库"。
  var FAKE = {
    low: [
      { b: '她抬眼看了一下，又飞快地移开。\n「嗯……你怎么突然……」\n后半句没说完，她自己先笑了。',
        n: '轻轻吸了口气，膝盖不自觉地并了并。',
        v: '[气声] 嗯……\n[soft tone] 你怎么突然……\n[chuckling] 没事，你继续。' },
      { n: '攥住手边的布料，声音里带出一点黏。',
        v: '[whispering] 唔……别、别这样……\n[soft tone] 有人会看见的……\n[sighing] 算了，当我没说。' },
      { b: '她低下头，呼吸乱了一拍。\n「不、不行……你等一下……」',
        n: '低下头，呼吸乱了一拍。',
        v: '[panting] 哈啊……等一下……\n[inhale] 我缓一缓就好。\n[soft tone] 你、你别过来。' }
    ],
    mid: [
      { b: '她整个人抖了一下，指尖掐进掌心。\n「你手别动……我真的会叫出来的。」',
        n: '整个人抖了一下，指尖掐进掌心，喉咙里漏出一声没压住的轻哼。',
        v: '[panting] 不、不行……\n[gasping] 你手别动……\n[sobbing] 我真的会叫出来的。' },
      { n: '试着稳住呼吸，可腰已经自己塌了下去。',
        v: '[gasping] 啊——嗯……不要……\n[panting][气声] 慢、慢一点……\n[whispering] 求你，别看我的脸。' },
      { b: '「我说不……说不完整了……」\n后半句被自己咽了回去，只剩一点气音。',
