      { b: '「我什么都不知道了……」\n这一句几乎听不出字，尾音散在喘里。',
        n: '意识被搅成一团白光，只能本能地追着那点节奏。',
        v: '[sobbing] 啊……啊——\n[panting] 哈啊……哈啊……\n[whispering] 我什么都不知道了……' }
    ]
  };
  function fakeReact() {
    var bank = S.aro < 25 ? FAKE.low : (S.aro < 65 ? FAKE.mid : FAKE.high);
    var pick = bank[Math.floor(Math.random() * bank.length)];
    setTimeout(function () {
      // 有正文就一起交给 pushMsg：它会先从句子里抽对白当台词，抽不到才用兜底台词
      pushMsg('ai', pick.n, pick.v, pick.b || '');
    }, 420);
  }

  /* =========================================================
   * 8. 声音流渲染
   * ======================================================= */
  function scrollFeed() {
    var v = $('#v-chat');
    v.scrollTop = v.scrollHeight;
  }
  /* 这一页是谁的声音：自己玩那一档没有 TA，是玩家自己的呻吟 */
  function heartLabel() { return S.target === 'self' ? '你的声音' : 'TA 的声音'; }
  function feedEmptyHtml() {
    return '<div class="feed-empty">还没有声音<br>' + (S.target === 'self'
      ? '装置跑起来之后，你自己的声音会显示在这里'
      : '装置跑起来之后，TA 会发出什么声音会显示在这里') + '</div>';
  }
  /* 面板上每一条声音在这里落地。三个参数：谁、给眼睛看的说明文字、给耳朵听的台词。
     说明文字常驻显示，台词带情绪标记并配播放键 —— 两者职责不混。
     台词相关的节点挂在 rec 上，供「重写这句」取用（每次都从 DOM 现取，不用闭包里的旧引用，
     否则重写一次之后闭包指向的就是被换掉的旧节点了）。 */
  function pushMsg(kind, text, speak, body) {
    var feed = $('#feed');
    var empty = feed.querySelector('.feed-empty');
    if (empty) empty.remove();
    var el = document.createElement('div');
    el.className = 'msg ' + (kind === 'ai' ? 'ai' : (kind === 'me' ? 'me' : 'sys'));
    var who = kind === 'ai' ? heartLabel() : (kind === 'me' ? '你' : '装置');
    el.innerHTML = '<div class="who"><i></i>' + who + '</div><div class="bubble"></div>';

    /* 台词来源：正文对白 > 传进来的 speak > 台词库。
       正文有对话时，念出来的就是你在正文里读到的那一句 —— 视听一致。 */
    var voiceText = String(speak || '').trim();
    var fromBody = '';
    if (kind === 'ai' && String(body || '').trim()) {
      fromBody = extractSpeech(body, voiceKind(), S.stage);
    }
    if (fromBody && voiceish(fromBody)) voiceText = fromBody;
    else if (!voiceText || !voiceish(voiceText)) {
      voiceText = fromBody || voiceFor(voiceText, S.stage, null, body).text;
    }

    var rec = { root: el, text: String(text || ''), voice: voiceText, prev: '' };
    var bubble = el.querySelector('.bubble');
    // skipSub：重写时用 —— 旧的那种不带"说明"分支只为了兼容 pushMsg('ai','') 的占位调用
    var sub = null;
    if (rec.voice) {
      lineEl(rec);
      if (rec.text) sub = subEl(bubble, rec.text);
    } else {
      bubble.textContent = rec.text;
    }
    feed.appendChild(el);
    scrollFeed();

    // 语音与重写控件。音色与口气由**台词**决定，说明文字不参与合成。
    if (VOC.voiceOn() && rec.voice) vbarFor(rec, null, true);
    editBtnFor(rec);
    return el;
  }

  /* 台词行：整块替换（重写后用它把新台词写上） */
  function lineEl(rec) {
    var bubble = rec.root.querySelector('.bubble');
    var old = bubble.querySelector('.vline');
    if (old) old.remove();
    var d = document.createElement('div');
    d.className = 'vline';
    d.textContent = rec.voice;
    bubble.insertBefore(d, bubble.firstChild);
    return d;
  }
  /* 说明文字行 */
  function subEl(bubble, txt) {
    var old = bubble.querySelector('.sub');
    if (old) old.remove();
    var s = document.createElement('span');
    s.className = 'sub';
    s.textContent = txt;
    bubble.appendChild(s);
    return s;
  }
  /* 播放条 */
  function vbarFor(rec, oldBar, autoplay) {
    var vm = voiceFor(rec.voice, S.stage);
    if (oldBar) oldBar.remove();
    var bar = document.createElement('div');
    bar.className = 'vbar';
    var b = document.createElement('button');
    b.className = 'vplay';
    b.type = 'button';
    b.innerHTML = '<span class="ico">▶</span>语音播放';
    b.addEventListener('click', function () {
      b.classList.add('on');
      VOC.say(rec.voice, { vol: S.voiceVol / 100, voice: voiceFor(rec.voice, S.stage).voice });
    });
    bar.appendChild(b);
    rec.root.appendChild(bar);
    if (autoplay && S.voiceAuto) {
      VOC.say(rec.voice, { vol: S.voiceVol / 100, voice: vm.voice });
      b.classList.add('on');
    }
    return bar;
  }
  /* 重写按钮：把这一条挂到顶部重写栏当目标。
     用 .ebar 而不是 .vbar —— 两者样式几乎一样，但混用会让「播放条数量」这类检查失真，
     也让 CSS 里出现规则打架。 */
  function editBtnFor(rec) {
    if (!rec.voice) return;
    var wrap = document.createElement('div');
    wrap.className = 'ebar';
    var b = document.createElement('button');
    b.className = 'vplay';
    b.type = 'button';
    b.innerHTML = '<span class="ico">✎</span>重写这句';
    b.addEventListener('click', function () { selectRelay(rec); });
    wrap.appendChild(b);
    rec.root.appendChild(wrap);
  }

  /* 演示模式下的假重写：按方向里的关键词拼三行，看得出"改过"就行。
     只服务于没接酒馆时的离线演示，真环境永远走 BRIDGE.genRaw。 */
  function mockRewriteLine(dir) {
    var d = String(dir || '');
    if (/慢|拖|缓|拉长/.test(d)) {
      return '[soft tone][whispering] 慢一点……别急……\n[panting] 你、你听我说……\n[short pause] 我真的……快撑不住了。';
    }
    if (/快|急|紧凑|加快/.test(d)) {
      return '[panting] 哈啊……哈啊……太快了……\n[gasping] 不、不行，你慢一点……\n[sobbing] 我快不行了……';
    }
    if (/多|长|再说|多一点/.test(d)) {
      return '[soft tone] 你想听我说话吗？\n[panting] 那……那你先让我喘口气。\n[chuckling] 好啦，我说就是了……';
    }
    if (/少|短|简洁|安静/.test(d)) {
      return '[gasping] ……嗯。\n[soft tone] 别说话。';
    }
    if (/沙哑|哑|低/.test(d)) {
      return '[groaning] 唔……嗓子哑了……\n[whispering] 你、你听得清吗……\n[sighing] 算了，别管我。';
    }
    if (/哭|泪|委屈/.test(d)) {
      return '[sobbing] 呜……你别这样……\n[crying loudly] 我真的受不了了……\n[whispering] 抱一会儿……就一会儿。';
    }
    if (/硬|傲|嘴硬|命令|凶/.test(d)) {
      return '[confident] 别出声。撑住。\n[soft tone] 看着我。\n[chuckling] 这就不行了？';
    }
    if (/求|软|服软/.test(d)) {
      return '[nervous][气声] 求你……我真的不行了……\n[panting] 你就饶了我吧……\n[soft tone] 我什么都答应你。';
    }
    if (/喘|气/.test(d)) {
      return '[panting] 哈啊……哈……\n[gasping] 哈啊……哈啊……\n[sighing] 呼……总算缓过来了。';
    }
    return '[soft tone][whispering] 你怎么还没睡呀？\n[inhale] 我只是……有点想你了。\n[short pause][chuckling] 好啦，别笑我。';
  }

  /* =========================================================
   * 语气符号模板与自定义试听
   *
   * 符号表照着 Fish 官方 Emotion Control 文档整理：音效、情绪、语调三类是官方固定标记，
   * 中文那一组用的是"括号里可写自然语言"那条规则（Bracket cues can use natural language）。
   * 点一下复制到剪贴板 —— 不是为了偷懒，是因为方括号在各种输入法里都难打。
   * ======================================================= */
  var MARK_TPL = [
    { mark: '[panting]', cn: '喘', grp: 'fx' },
    { mark: '[gasping]', cn: '抽气', grp: 'fx' },
    { mark: '[groaning]', cn: '闷哼', grp: 'fx' },
    { mark: '[sobbing]', cn: '哽咽', grp: 'fx' },
    { mark: '[crying loudly]', cn: '大哭', grp: 'fx' },
    { mark: '[sighing]', cn: '叹息', grp: 'fx' },
    { mark: '[chuckling]', cn: '轻笑', grp: 'fx' },
    { mark: '[laughing]', cn: '笑', grp: 'fx' },
    { mark: '[clear throat]', cn: '清嗓', grp: 'fx' },

    { mark: '[nervous]', cn: '紧张', grp: 'emo' },
    { mark: '[scared]', cn: '害怕', grp: 'emo' },
    { mark: '[embarrassed]', cn: '羞', grp: 'emo' },
    { mark: '[upset]', cn: '委屈', grp: 'emo' },
    { mark: '[pleased]', cn: '愉悦', grp: 'emo' },
    { mark: '[satisfied]', cn: '满足', grp: 'emo' },
    { mark: '[confident]', cn: '笃定', grp: 'emo' },
    { mark: '[calm]', cn: '平静', grp: 'emo' },
    { mark: '[sad]', cn: '低落', grp: 'emo' },
    { mark: '[relaxed]', cn: '放松', grp: 'emo' },

    { mark: '[whispering]', cn: '耳语', grp: 'tone' },
    { mark: '[soft tone]', cn: '轻声', grp: 'tone' },
    { mark: '[shouting]', cn: '喊', grp: 'tone' },
    { mark: '[screaming]', cn: '惊叫', grp: 'tone' },
    { mark: '[in a hurry tone]', cn: '急促', grp: 'tone' },
    { mark: '[emphasis]', cn: '重读', grp: 'tone' },

    { mark: '[气声]', cn: '', grp: 'cn' },
    { mark: '[颤抖]', cn: '', grp: 'cn' },
    { mark: '[黏腻]', cn: '', grp: 'cn' },
    { mark: '[压低的声音]', cn: '', grp: 'cn' },
    { mark: '[破碎的喘息]', cn: '', grp: 'cn' },
    { mark: '[慵懒]', cn: '', grp: 'cn' },
    { mark: '[咬牙切齿]', cn: '', grp: 'cn' },
    { mark: '[带着哭腔]', cn: '', grp: 'cn' },
    { mark: '[强装镇定]', cn: '', grp: 'cn' },
    { mark: '[气息不稳]', cn: '', grp: 'cn' },

    { mark: '[break]', cn: '短停', grp: 'pause' },
    { mark: '[long-break]', cn: '长停', grp: 'pause' }
  ];

  function drawTags(id, grp) {
    var box = $('#' + id);
    if (!box) return;
    box.innerHTML = '';
    MARK_TPL.filter(function (m) { return m.grp === grp; }).forEach(function (m) {
      var b = document.createElement('button');
      b.type = 'button';
      b.className = 'tag';
      b.textContent = m.mark;
      b.title = '点击复制' + (m.cn ? '（' + m.cn + '）' : '');
      if (m.cn) {
        var s = document.createElement('b');
        s.textContent = m.cn;
        b.appendChild(s);
      }
      b.addEventListener('click', function () {
        var self = this;
        var flash = function (msg) {
          self.classList.add('ok');
          setTimeout(function () { self.classList.remove('ok'); }, 900);
          toast(msg, 2400);
        };
        copyTextAsync(m.mark, function () {
          flash('已复制 ' + m.mark);
        }, function (txt) {
          /* 剪贴板写不进去时不能只说"失败了" —— 给一条真能用的路：
             先试着把标记直接插进「自定义试听」的文本框（同一个页面，用户本来就是要往那儿写）。 */
          var ta = $('#s-custom-text');
          if (ta) {
            var cur = String(ta.value || '');
            ta.value = (cur === '' || /\n$/.test(cur)) ? (cur + txt + ' ') : (cur.replace(/\s+$/, '') + ' ' + txt + ' ');
            /* 滚动到它：标记按钮在「自定义试听」上面一段，不滚过去用户看不到"放进去了" */
            try { ta.scrollIntoView({ block: 'center' }); } catch (e) { /* noop */ }
            try { ta.focus(); ta.setSelectionRange(ta.value.length, ta.value.length); } catch (e) { /* noop */ }
            if (typeof paintLen === 'function') paintLen();
            flash('这个环境不让写剪贴板，已把 ' + txt + ' 放进下面「自定义试听」的文本框');
            return;
          }
          if (revealForManualCopy(txt)) flash('剪贴板被禁，' + txt + ' 已选中，按 Ctrl/Cmd+C 复制');
          else flash('复制没成功，请手动输入 ' + txt);
        });
      });
      box.appendChild(b);
    });
  }

  function bindCustomSay() {
    drawTags('tag-fx', 'fx');
    drawTags('tag-emo', 'emo');
    drawTags('tag-tone', 'tone');
    drawTags('tag-cn', 'cn');
    drawTags('tag-pause', 'pause');

    var ta = $('#s-custom-text');
    function paintLen() {
      var box = $('#c-custom-len');
      if (!box || !ta) return;
      var v = String(ta.value || '');
      var n = v.replace(/\[[^\]]*\]\s*/g, '').length;      // 提示"要念几个字"，标记不算
      var lines = v.split(/[\r\n]+/).filter(function (x) { return x.trim(); }).length;
      box.textContent = n + ' 字 · ' + lines + ' 行';
      var tag = $('#vs-custom-tag');
      if (tag) tag.textContent = !lines ? '空' : (n > 200 ? '偏长' : (lines > 4 ? '行数偏多' : ''));
      box.classList.toggle('on', n > 0);
    }
    if (ta) {
      ta.addEventListener('input', paintLen);
      // 中文输入法组字过程中不算长度，不然会跳字
      ta.addEventListener('compositionend', paintLen);
    }
    paintLen();

    onEl('#c-custom-clear', 'click', function () {
      if (ta) { ta.value = ''; paintLen(); ta.focus(); }
    });

    onEl('#c-custom-say', 'click', function () {
      if (!ta) return;
      var txt = String(ta.value || '').trim();
      if (!txt) { toast('先写一段话'); return; }
      var bareLen = txt.replace(/\[[^\]]*\]\s*/g, '').length;
      if (bareLen > 200 && !confirm('这段去掉标记有 ' + bareLen + ' 字，合成会明显变慢（首字延迟长）。继续吗？')) return;
      VOC.resume();
      if (VOC.buzzMode() && S.on) VOC.tick(S.env);
      if (!VOC.voiceOn()) { toast('语音开关还没开（要在 TTS 语音或两个都要）'); return; }
      if (!S.ttsTarget) { toast('先填「合成地址」'); return; }
      // 经作者中转也要 Key（它用的是你自己的官方 Key），只有本机脚本那档才可以留空
      if (S.ttsTransport !== 'relay' && S.ttsAuth !== 'none' && !S.ttsKey) { toast('这一档要填令牌 / 官方 API Key'); return; }
      /* 多行时逐行补标记 —— 用户可能只给第一行写了标记，其余行空着；
         每行各自带标记，念出来的语气才会跟着走。 */
      var ck = voiceKind();
      var line = txt.split(/[\r\n]+/).filter(function (x) { return x.trim(); }).map(function (x) {
        return hasMark(x) ? x.trim() : (voiceMark(ck, S.stage) + ' ' + x.trim());
      }).join('\n');
      var nl = line.split('\n').length;
      VOC.say(line, { vol: S.voiceVol / 100, voice: (ck === 'tease' && S.ttsVoiceTease) ? S.ttsVoiceTease : S.ttsVoice });
      VOC.addLog('自定义试听：' + line.replace(/[\r\n]+/g, ' ／ ').slice(0, 60), 'hi');
      toast('试听：' + nl + ' 行', 2200);
    });
  }


  /* =========================================================
   * 8b. 语音重写
   *
   * 反应页顶部那条输入栏不是用来跟 TA 说话的 —— 它是"这句话该怎么念"的指挥台。
   * 点某一条的「✎ 重写这句」把它挂成目标，在输入框里写方向（语速更慢一点、
   * 话再多一点、更沙哑、别求饶），回车就让 AI 重写这一句台词。
   *
   * 走 genRaw：不注入角色卡与世界书，只为一句台词花一次短生成。
   * 代价是不带上下文，所以在提示词里补上角色名与当前阶段，两边都照顾到。
   * ======================================================= */
  var RELAY = { target: null };

  function selectRelay(rec) {
    RELAY.target = rec;
    rec.root.classList.add('relay-on');
    var inp = $('#relay-input'), goB = $('#relay-go'), tg = $('#relay-target');
    if (inp) { inp.disabled = false; inp.focus(); }
    if (goB) goB.disabled = false;
    if (tg) {
      tg.className = 'rtarget on';
      tg.innerHTML = '要重写的是：<b>' + esc4(tgText(rec)) + '</b>';
    }
    var rv = $('#relay-revert'), cc = $('#relay-cancel');
    if (rv) rv.hidden = !rec.prev;
    if (cc) cc.hidden = false;
  }

  function clearRelay() {
    if (RELAY.target) RELAY.target.root.classList.remove('relay-on');
    RELAY.target = null;
    var inp = $('#relay-input'), goB = $('#relay-go'), tg = $('#relay-target');
    if (inp) { inp.disabled = true; inp.value = ''; }
    if (goB) goB.disabled = true;
    if (tg) {
      tg.className = 'rtarget';
      tg.textContent = '没选目标 · 点下面任意一条的「✎ 重写这句」';
    }
    var rv = $('#relay-revert'), cc = $('#relay-cancel');
    if (rv) rv.hidden = true;
    if (cc) cc.hidden = true;
  }

  function tgText(rec) { return String(rec.voice || rec.text || '').replace(/\[[^\]]*\]\s*/g, '').slice(0, 28); }
  function esc4(s) {
    return String(s || '').replace(/[&<>"']/g, function (m) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[m];
    });
  }

  /* 重写用的提示词。参考信息只给必要的三样（角色名 / 阶段 / 装置状态），
     不给整张卡 —— 这是 genRaw 的前提。 */
  function rewritePrompt(cur, dir) {
    var who = wearerName(true);                 // 被作用者：char 档是角色名，另两档是"你"
    var kind = voiceKind();
    var role = (kind === 'tease') ? who + '是操控方，说话带命令与挑逗的口气'
      : (kind === 'self' ? '没有别人在场，是玩家自己压着声音' : who + '是被作用的一方');
    var L = [
      '【任务】重写下面这一句语音台词，只输出改写后的台词本身，不要解释、不要引号、不要换行。',
      '',
      '参考：' + role + '。当前第 ' + S.stage + ' 阶段（强度 ' + S.pow + '%，模式 ' + modeById(S.mode).name + '）。',
      '原句：' + cur,
      '修改要求：' + dir,
      '',
      '硬性要求：',
      '· 写成 **2 到 3 行**，每行一句台词，**每行开头都要带方括号情绪标记**。',
      '· 每行 **35-48 字**，照着下面示例的长度写 —— 太短念一下就完了，太长会变成朗读。',
      '· 标记可以写英文固定标记（[panting] [gasping] [sobbing] [whispering] [soft tone] [nervous] '
        + '[chuckling] [sighing]）或中文描述（[气声] [颤抖] [黏腻]）；一行最多叠 3 个。',
      '· 三行之间要有推进：从试探到说透，最后一句可以退让、打岔或撒娇收尾。',
      '· 只写能念出来的话（拟声、短命令、压在喉咙里的碎音），不要写动作、不要写旁白，'
        + '也不要写环境音（嗡嗡声、电流声这类既不是台词也不是人声）。',
      '',
      '格式示例（照这个长度和格式写）：',
      '　[soft tone][whispering] 你怎么还没睡呀……我都醒了有一会儿了，听着你在那边翻身……',
      '　[inhale] 我只是……有点想你了。也没别的事，就是忽然想听听你的声音，没打扰你吧？',
      '　[short pause][chuckling] 好啦，别笑我……我说完这句就不说了，你先去忙你的……'
    ];
    var warn = voiceish(cur) ? '' : '\n· 注意：原句看起来像旁白而不是台词，改写后必须变成能直接念出来的话。';
    return L.join('\n') + warn;
  }

  /* 把结果收拾成一句干净台词：剥引号、剥标签注释、压成一行、去标记后算长度 */
  function tidyLine(t) {
    t = String(t || '')
      .replace(/<[^>]{1,40}>/g, ' ')                       // 各种标签
      .replace(/```[\s\S]*?```/g, ' ')
      .replace(/^[\s"'「『]+|[\s"'」』]+$/g, '')            // 首尾引号
      // 保留换行 —— 结论是"2-3 行、每行带标记"，压成一行就把结构毁了
      .split(/[\r\n]+/)
      .map(function (l) { return l.replace(/^[\s"'「『]+|[\s"'」』]+$/g, '').replace(/\s{2,}/g, ' ').trim(); })
      .filter(function (l) { return l; })
      .join('\n');
    var bare = t.replace(/\[[^\]]*\]\s*/g, '').replace(/[\r\n]+/g, ' ').trim();
    return { line: t, bare: bare, lines: t ? t.split('\n').length : 0 };
  }

  function rewriteVoice(dir) {
    var rec = RELAY.target;
    if (!rec) return;
    var inp = $('#relay-input'), goB = $('#relay-go'), tg = $('#relay-target');
    var oldLabel = goB ? goB.textContent : '';
    if (goB) { goB.disabled = true; goB.textContent = '生成中…'; }
    if (tg) tg.innerHTML = '正在让模型重写…（只发一句短提示，不注入角色卡）';

    var res = BRIDGE.genRaw({
      user_input: rewritePrompt(rec.voice, dir),
      should_stream: false,
      should_silence: false
    });
    // 没接酒馆（离线演示）时用假的顶上，否则这一页的重写会直接报错、看不出效果
    var demo = false;
    if (!res) { res = BRIDGE.mockRaw({ user_input: dir }); demo = true; }
    if (!res) {
      if (goB) { goB.disabled = false; goB.textContent = oldLabel; }
      if (tg) tg.innerHTML = '这个环境没有生成接口，重写用不了';
      toast('没拿到生成接口');
      return;
    }

    var handle = function (text) {
      if (goB) { goB.disabled = false; goB.textContent = oldLabel; }
      var o = tidyLine(typeof text === 'string' ? text : (res && res.text) || '');
      var line = o.line;
      if (!line) {
        if (tg) tg.innerHTML = '没生成出内容，再试一次或换个说法';
        toast('重写失败：空结果');
        return;
      }
      /* 收紧尺度随多行放宽：单行上限约 40 字、整段约 120 字。
         原来的 26 字是给单行台词定的，多行台词照那个卡会把结果削掉大半。 */
      var linesArr = line.split('\n');
      if (o.bare.length > 120) {
        line = linesArr.slice(0, 3).join('\n');
        o = tidyLine(line);
      }
      if (!voiceish(line) && o.bare.length > 60) {
        if (tg) tg.innerHTML = '模型这次写成了旁白，没采用 —— 换个说法再试一次';
        toast('这次写成旁白，没采用');
        return;
      }
      // 落盘：台词换掉，音色与口气按新台词重算（原文可还原）
      if (!rec.prev) rec.prev = rec.voice;
      rec.voice = line;
      lineEl(rec);
      var bar = rec.root.querySelector('.vbar');
      if (VOC.voiceOn()) vbarFor(rec, bar, true); else if (bar) bar.remove();
      if (tg) tg.innerHTML = '已改成：<b>' + esc4(tgText(rec)) + '</b>';
      var rv = $('#relay-revert');
      if (rv) rv.hidden = false;
      if (inp) inp.value = '';
      scrollFeed();
      toast(demo ? '台词已重写（演示模式：本地假数据）' : '台词已重写', demo ? 3200 : 2000);
    };

    if (res && res.then) res.then(handle, function () { handle(''); });
    else handle('');
  }

  /* 重写栏的接线 */
  (function bindRelay() {
    var form = $('#relay-form');
    if (form) {
      form.addEventListener('submit', function (e) {
        e.preventDefault();
        var inp = $('#relay-input');
        var dir = inp ? inp.value.trim() : '';
        if (!RELAY.target) { toast('先点某一条下面的「✎ 重写这句」'); return; }
        if (!dir) { toast('写一句修改方向，比如「语速更慢一点」'); return; }
        rewriteVoice(dir);
      });
    }
    onEl('#relay-cancel', 'click', clearRelay);
    onEl('#relay-revert', 'click', function () {
      var rec = RELAY.target;
      if (!rec || !rec.prev) { toast('这一条没有可还原的原文'); return; }
      rec.voice = rec.prev;
      rec.prev = '';
      lineEl(rec);
      var bar = rec.root.querySelector('.vbar');
      if (VOC.voiceOn()) vbarFor(rec, bar, false); else if (bar) bar.remove();
      this.hidden = true;
      var tg = $('#relay-target');
      if (tg) tg.innerHTML = '已还原：<b>' + esc4(tgText(rec)) + '</b>';
      toast('已还原原来的台词');
    });
  })();

  /* =========================================================
   * 9. 启停与事件绑定
   * ======================================================= */
  /* 只把装置跑起来，不触发 AI。
     给"她自己按下启动键"这条路径用——那是回复里发生的事，
     不该反过来再叫一次生成。 */
  function startSilent() {
    if (S.on) return false;
    S.on = true;
    wakeLoop();       // 装置跑起来了，把渲染循环拉起来（关着时它不跑）
    S.beg = 0;        // 新的一轮，请求次数清零
    paintTargetLock();   // 装置跑起来了，作用对象先锁住
    S.t = 0;
    S.clock = 0;
    S.aro = 0;
    S.stage = 1;
    S.hi = false;       // 新一轮：满值锁解除
    S.slow = 1;         // 新一轮：冲刺留下的减速清掉（贴上/拿起是玩家设置，保留）
    S.stopReason = '';
    lastPhys = 0;
    if (S.audio) AUD.start();
    render();
    return true;
  }

  function start() {
    if (S.on) return;
    S.lastEvent = '装置启动，' + modeById(S.mode).name + ' 模式 ' + hz().toFixed(1) + ' Hz';
    pushAction(act(
      '按下遥控器的启动键，装置开始运行：' + modeById(S.mode).name + ' 模式，频率 ' + hz().toFixed(1) + ' Hz，强度 ' + S.pow + '%',
      '把遥控器拿在手里，按下了启动键：' + modeById(S.mode).name + ' 模式，频率 ' + hz().toFixed(1) + ' Hz，强度 ' + S.pow + '%'));
    startSilent();
    HAP.tap([0, 45, 70, 45]);   // 启动：两下，给点仪式感
    voiceOnStart();             // 语音已开的话，这里把振动音拉起来、顺手预热音集
    // 每一轮重新掷"这次要为难你几回"，2 或 3
    S.beg = 0;
    S.begNeed = 2 + Math.round(Math.random());
    paintBeg();
    render();
    toast('装置已启动');
    if (S.auto) toast('自动反应开着：状态变化会让 AI 新生成回复', 3200);
    setTimeout(function () { react('start'); }, 260);
  }
  function stop(reason, silent) {
    if (!S.on) return;
    S.on = false;
    S.stopReason = reason || '玩家手动关闭';
    S.lastEvent = '装置停止（' + S.stopReason + '）';
    pushAction((S.stopReason === '玩家手动关闭')
      ? act('按下遥控器的关闭键，装置停下', '把遥控器关掉，装置停下')
      : '装置因「' + S.stopReason + '」自行停下，没有人碰遥控器');
    HAP.kill();   // 先把跟随震动掐掉，不然会震完剩下的一段
    AUD.stop();
    VOC.stopAll();   // 振动音和语音一起收，别让声音留在装置停之后
    S.beg = 0;    // 停了就不用再求了
    S.hi = false; // 满值锁随停机解除；下次启动是从头爬，不是从"已满"接着算
    S.slow = 1;   // 减速也一起清掉，别把上一次冲刺的惩罚带到下一轮
    paintBeg();
    paintTargetLock();   // 停了，作用对象可以换了
    render();
    syncVars(true);   // 停止要立刻反映到变量，不能等下一次定时同步
    if (silent) { HAP.tap(50); return; }   // 她自己关的，不必再叫一次生成
    HAP.tap(70);   // 停止：一下长的，手感上收得住
    toast('装置已停止');
    setTimeout(function () { react('stop'); }, 240);
  }

  function buildModes() {
    var box = $('#modes');
    box.innerHTML = '';
    MODES.forEach(function (m) {
      var b = document.createElement('button');
      b.className = 'mode' + (m.id === S.mode ? ' on' : '');
      b.dataset.id = m.id;
      b.title = m.desc;
      b.disabled = (S.target === 'user');   // 只读仪表：真禁用，连程序化点击也拦
      b.innerHTML = '<svg viewBox="0 0 24 24" fill="currentColor">' + m.icon + '</svg><span>' + m.name + '</span>';
      b.addEventListener('click', function () { setMode(m.id); });
      box.appendChild(b);
    });
    LAST_MODE_LOCK = '';   // 重建之后签名作废，强制重画一次
    paintModeLocks();      // 临界 / 冲刺 的初始锁定状态
  }
  function setMode(id) {
    if (S.target === 'user') return;   // 遥控器不在玩家手里，档位点了也不算
    if (!modeUnlocked(id)) {
      // 锁着就明说为什么 —— 用 aria-disabled 而不是 disabled 就是为了留这条路
      toast(id === 'edge' ? '「临界」还没解锁：进入第 5 阶段才可用'
        : '「冲刺」还没解锁：阶段值满了才可用', 2600);
      return;
    }
    if (S.mode === id) return;
    S.mode = id;
    var m = modeById(id);
    if (S.recFreq) {
      $('#freq').value = m.rec;
      paintSlider($('#freq'));
      S.freq = m.rec;
      syncSliders();
    }
    S.lastEvent = '切换到「' + m.name + '」模式' + (S.recFreq ? '，频率适配至 ' + hz().toFixed(1) + ' Hz' : '');
    HAP.tap(22);   // 切模式：一下短促的确认
    pushAction(act('在遥控器上把模式切到「' + m.name + '」', '把遥控器上的模式拨到「' + m.name + '」')
      + (S.recFreq ? '，频率随之拨到 ' + hz().toFixed(1) + ' Hz' : ''));
    var nodes = $('#modes').children;
    for (var i = 0; i < nodes.length; i++) nodes[i].classList.toggle('on', nodes[i].dataset.id === id);
    render();
    react('mode');
  }

  function syncSliders() { render(); }

  // 拖动滑杆会连续触发 input：等手停下来再叫 AI，避免一次调整说三遍
  var REACT_DEBOUNCE = 0;
  function scheduleReact(kind) {
    clearTimeout(REACT_DEBOUNCE);
    REACT_DEBOUNCE = setTimeout(function () { react(kind); }, 750);
  }

  $('#freq').addEventListener('input', function (e) {
    var oldHz = hz().toFixed(1);
    S.freq = +e.target.value;
    var newHz = hz().toFixed(1);
    paintSlider(e.target);
    if (Math.abs(S.freq - LAST_FREQ_PUSH) >= 9) {
      LAST_FREQ_PUSH = S.freq;
      S.lastEvent = '频率' + (newHz >= oldHz ? '提升' : '降低') + '至 ' + newHz + ' Hz';
      pushAction(act('把频率从 ' + oldHz + ' Hz 拨到 ' + newHz + ' Hz', '把频率拨到 ' + newHz + ' Hz'));
      scheduleReact('freq');
    }
    render();
  });
  $('#pow').addEventListener('input', function (e) {
    var oldPow = S.pow;
    S.pow = +e.target.value;
    paintSlider(e.target);
    if (Math.abs(S.pow - LAST_POW_PUSH) >= 12) {
      LAST_POW_PUSH = S.pow;
      S.lastEvent = '强度调整至 ' + S.pow + '%';
      pushAction(act('把强度从 ' + oldPow + '% 推到 ' + S.pow + '%', '把强度推到 ' + S.pow + '%'));
      scheduleReact('power');
    }
    render();
  });
  $('#dur').addEventListener('input', function (e) {
    S.limit = +e.target.value;
    paintSlider(e.target);
    markDurChip();
