    for (var i = 0; i < cs.length; i++) cs[i].classList.toggle('on', +cs[i].dataset.d === S.limit);
  }

  $('#power').addEventListener('click', function () { S.on ? stop() : start(); });

  /* 底栏那颗「立即反应一次」：催一条新回复，装置状态一点都不动。
     不看装置开没开、不改阶段值、不动档位 —— 它就是"催一下"。
     （以前这里是「冲击一次」：同样是生成，却顺手把阶段值 +26，
       想让 TA 说句话都得先付出状态代价。） */
  $('#btn-now').addEventListener('click', function () {
