  $('#c-copy').addEventListener('click', function () {
    copyToClipboard(stateText(), '快照已复制');
  });
  /* ---------- 复制文本 ----------
     沙箱 iframe 里写剪贴板经常是"假成功"：execCommand('copy') 失败时只返回 false、
     不抛错，而 navigator.clipboard.writeText 在部分宿主里会 resolve 但没写进去。
     老的 fallbackCopy 没看返回值，于是弹了「已复制」而剪贴板是空的 —— 用户粘不上。
     现在逐级尝试并把结果如实返回；全失败时把文本选中亮出来，让人按 Ctrl/Cmd+C 或长按复制。 */
  function revealForManualCopy(t) {
    try {
      var ta = document.createElement('textarea');
      ta.value = t; ta.readOnly = true;
      ta.setAttribute('style', 'position:fixed; left:8px; right:8px; bottom:8px; height:46px; z-index:5;'
        + 'font-size:12px; padding:6px 8px; border:1px solid var(--line); border-radius:8px;'
        + 'background:rgba(20,8,24,.96); color:var(--ink); box-sizing:border-box;');
      var host = DOC.body || (WIN.document && WIN.document.body);
      if (!host) return false;
      host.appendChild(ta);
      try { ta.scrollIntoView({ block: 'center' }); } catch (e) { /* noop */ }
      try { ta.focus(); } catch (e) { /* noop */ }
      try { ta.select(); ta.setSelectionRange(0, t.length); } catch (e) { /* noop */ }
      setTimeout(function () { try { ta.remove(); } catch (e) { /* noop */ } }, 9000);
      return true;
    } catch (e) { return false; }
  }
  /* 返回 done() 表示"已经进了剪贴板"；fail(t) 表示没写成功，由调用方给退路。 */
  function copyTextAsync(t, done, fail) {
    t = String(t == null ? '' : t);
    var ok = function () { done && done(); };
    var no = function () { fail ? fail(t) : (done && done()); };
    var legacy = function () {
      var wrote = false;
      try {
        var ta = document.createElement('textarea');
        ta.value = t; ta.setAttribute('readonly', '');
        ta.setAttribute('style', 'position:fixed; top:0; left:0; width:1px; height:1px; opacity:0;');
        (DOC.body || DOC.documentElement).appendChild(ta);
        ta.focus(); ta.select();
        try { ta.setSelectionRange(0, t.length); } catch (e) { /* noop */ }
        wrote = !!(DOC.execCommand && DOC.execCommand('copy'));   // ← 关键：以前没查这个返回值
        ta.remove();
      } catch (e) { wrote = false; }
      wrote ? ok() : no();
    };
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(t).then(ok, legacy);
    } else legacy();
  }
  // 复制 + 统一反馈：#c-copy 那类按钮用它
  function copyToClipboard(t, okMsg) {
    copyTextAsync(t, function () { toast(okMsg || '已复制', 1600); }, function (txt) {
      if (revealForManualCopy(txt)) toast('这个环境不让写剪贴板 —— 文本已选中，按 Ctrl/Cmd+C 复制', 6000);
      else toast('复制没成功，请手动记下：' + String(txt).slice(0, 40), 6000);
    });
  }
  $('#c-wipe').addEventListener('click', function () {
    $('#feed').innerHTML = feedEmptyHtml();
    toast('记录已清空');
  });
  $('#c-reset').addEventListener('click', function () {
    stop();
    S.t = 0; S.aro = 0; S.peak = 0; S.stage = 1; S.env = 0;
    S.lastEvent = '装置复位';
    hist.length = 0;
    render();
    toast('装置已复位');
  });

  // 设置页
  function bindSettings() {
    $('#s-auto').classList.toggle('on', S.auto);
    $('#s-wb').classList.toggle('on', S.manageWb);
    var sendBtn = $('#s-send');
    if (sendBtn) sendBtn.textContent = (S.sendMode === 'slash' ? 'slash /trigger' : 'generate');
    var bodyBtn = $('#s-body');
    if (bodyBtn) bodyBtn.textContent = (S.body === 'male' ? '男性' : '女性');
    var holderIn = $('#s-holder');
    if (holderIn) {
      holderIn.value = S.holder || '';
      holderIn.placeholder = rawCharName();   // 留空时用的就是它，直接摆给人看
    }
    var devBox = $('#s-dev');
    if (devBox) {
      for (var di = 0; di < devBox.children.length; di++) {
        devBox.children[di].classList.toggle('on', devBox.children[di].getAttribute('data-dev') === S.dev);
      }
    }
    var devNote = $('#s-dev-note');
    if (devNote) devNote.textContent = devOf().note;
    var expSw = $('#s-explicit');
    if (expSw) expSw.classList.toggle('on', S.explicit);
    var scaleNote = $('#s-scale-note');
    if (scaleNote) {
      scaleNote.innerHTML = S.explicit
        ? '<b>当前：直写。</b>体内的感觉、装置怎么震、顶点怎么来，照写。<br>'
          + '关掉换成「忍耐 · 假装镇定」：不写体内，只写呼吸、姿态、手在抓什么、话说得完不完整、'
          + '声音从哪里出来，以及对周围事物的失手。'
        : '<b>当前：忍耐 · 假装镇定。</b>不写体内感觉与生理机制；顶点写成「装不住了」的那一下与之后的收拾，'
          + '主体是「还在装」。<br>改的是脚本自动建的那本世界书；用角色卡自带世界书时，'
          + '靠状态注入里那条同款禁令兜底。';
    }
    $('#s-beg').classList.toggle('on', S.begDocile);
    var cFreeze = $('#c-freeze');
    if (cFreeze) cFreeze.classList.toggle('on', S.freezeOnGen);
    $('#s-freeze').classList.toggle('on', S.freezeOnGen);
    $('#s-inject').classList.toggle('on', S.inject);
    $('#s-stage').classList.toggle('on', S.stageForce);
    $('#s-reset').classList.toggle('on', S.resetOnPeak);
    $('#s-recfreq').classList.toggle('on', S.recFreq);
    $('#s-drive').textContent = (S.drive === 'inner' ? '面板内生成' : '酒馆聊天');
    $('#s-cd').value = S.cd;
    $('#s-gain').value = S.gain;
    $('#s-dashrate').value = S.dashRate;
    $('#c-auto').classList.toggle('on', S.auto);
    $('#c-haptap').classList.toggle('on', S.hapticTap);
    $('#c-hapfol').classList.toggle('on', S.hapticFollow);
    $('#c-audio').classList.toggle('on', S.audio);

    // 震动这条要说清两件事：哪个开关管什么，以及这台设备到底震不震得起来
    var hapHint = $('#hap-hint');
    if (hapHint) {
      if (!HAP.ok()) {
        hapHint.innerHTML = '<b>这台设备拿不到马达。</b>iOS / Safari 全平台都没有 Vibration 接口，'
          + '开关留着不影响使用，但按下不会有震动 —— 想要手感就打开上面的「声波模拟」，用低频声代替。';
      } else {
        hapHint.innerHTML = '<b>按键震动</b>管的是操作手感：切模式、启停、切换作用对象各给一下不同长度的短震。'
          + '<b>跟随震动</b>管的是装置运行时按实时频率一直震 —— 默认关着，因为手机马达分辨不出频率，'
          + '实际听到的是断续的哒哒声，而且持续运转费电发热，也盖不住其它通知。';
      }
    }

    // 自动反应是个会花额度的开关，界面上必须说清楚它到底做什么
    var autoBtn = $('#c-auto');
    if (autoBtn) autoBtn.textContent = '自动反应 · ' + (S.auto ? '开' : '关');
    var autoHint = $('#auto-hint');
    if (autoHint) {
      autoHint.innerHTML = S.auto
        ? '<b>自动反应：开。</b>模式切换、频率大幅调整、阶段跃迁、临界爆发，都会让 AI <b>立刻新生成一条回复</b>。'
          + '这会消耗额度，也会写进聊天记录。不需要时点上面的开关关掉，装置本身照常运行。'
        : '<b>自动反应：关。</b>装置照常运行、状态照常同步给角色，但不会主动叫 AI 说话。'
          + '想让它开口就点「立刻反应一次」。';
    }
    var setAuto = $('#s-auto-note');
    if (setAuto) {
      setAuto.textContent = S.auto
        ? '当前：开。装置状态变化会自动触发 AI 生成。'
        : '当前：关。装置运行时不产生新的 AI 回复。';
    }
    paintTarget();
  }

  /* 作用对象：首页顶部的分段开关。
     切到「自己」后整台机器换一套身份——不是换几个参数，而是从"遥控台"变成"只读仪表"：
     配色换成酒红、档位控件锁住、当前档位只等 TA 的回复来更新。
     第三档「自己玩」：遥控器在玩家自己手里，所以和 char 档一样是可操作的梅紫遥控台，只是没有 TA。 */
  function paintTarget() {
    var user = (S.target === 'user');
    var selfT = (S.target === 'self');
    // 画布上色跟着主题走
    var tc = THEME_RGB[S.target] || THEME_RGB.char;
    HOT_RGB = tc.hot; HOT_RGB_2 = tc.hot2; CYAN_RGB = tc.cyan;
    var shell = $('#shell');
    if (shell) {
      shell.classList.toggle('tgt-user', user);
      shell.classList.toggle('tgt-self', selfT);
    }
    var tb = $('#tgtbar');
    if (tb) tb.setAttribute('data-t', S.target);
    ['char', 'user', 'self'].forEach(function (k) {
      var b = $('#tgt-' + k); if (b) b.classList.toggle('on', S.target === k);
    });
    // 心声页：自己玩没有 TA
    var chatTab = $('.tab[data-go="chat"]');
    if (chatTab) chatTab.innerHTML = '<b>❖</b>' + heartLabel();
    var empty = $('#feed .feed-empty');
    if (empty) empty.outerHTML = feedEmptyHtml();

    // 档位控件降级为只读：看得见，点不动
    var dev = $('#v-device');
    if (dev) dev.classList.toggle('locked', user);
    ['#freq', '#pow', '#dur'].forEach(function (s) {
      var el = $(s); if (el) el.disabled = user;
    });
    // 模式卡用真 disabled：只靠 CSS 的 pointer-events 拦不住程序化点击
    var modesBox = $('#modes');
    if (modesBox) {
      for (var k = 0; k < modesBox.children.length; k++) modesBox.children[k].disabled = user;
    }
    var chips = $('#dur-chips');
    if (chips) {
      for (var i = 0; i < chips.children.length; i++) chips.children[i].disabled = user;
    }
    var lb = $('#lockbar');
    if (lb) lb.hidden = !user;
    var mt = $('#modes-tag');
    if (mt) mt.textContent = user ? '由 TA 决定' : '';

    // 参数面板原本用「未启动 · 调整只是预置」这个标记，两者不能打架；
    // render 会一并把启动键的文案改掉（"启动" → "催 TA 一次"）
    render();
    paintPending();
    paintBeg();
    paintTargetLock();
  }

  /* 等 TA 决定的中间态：催过一次、回复还没到。 */
  function paintPending() {
    var lb = $('#lockbar');
    if (!lb || S.target !== 'user') return;
    var b = lb.querySelector('b'), s = lb.querySelector('span');
    lb.classList.toggle('pending', !!S.pending);
    if (!b || !s) return;
    if (S.pending) {
      b.textContent = 'TA 正在决定这一轮怎么用…';
      s.textContent = '等这条回复写完，上面的档位就会跳到 TA 选的那一档。';
    } else {
      b.textContent = '遥控器在 TA 手里';
      s.textContent = '档位由 TA 决定。下面的按钮只是"催一下"，TA 回复到了这里才会更新成现在的档位。';
    }
  }

  /* 遥控器在 TA 手里时，玩家按的按钮只是"催一下"：
     从催下去到回复落地这段时间面板显示"TA 正在决定"，
     回复一到就切回当前档位——那正是 TA 刚选的那一档。
     90 秒兜底，免得请求失败时提示一直转着不走。 */
  var PD_TIMER = 0;
  function markPending(on) {
    clearTimeout(PD_TIMER);
    if (S.target !== 'user') { S.pending = false; paintPending(); return; }
    S.pending = !!on;
    paintPending();
    if (on) PD_TIMER = setTimeout(function () { markPending(false); }, 90000);
  }

  /* 请求停止：遥控器在 TA 手里时，玩家唯一还能做的事。
     文案随请求次数往上走，让人看得出已经求了几回。 */
  function paintBeg() {
    var bar = $('#begbar'), b = $('#beg-stop');
    if (!bar || !b) return;
    var user = (S.target === 'user');
    bar.hidden = !user;
    if (!user) return;
    var t = b.querySelector('b'), s = b.querySelector('i');
    if (t) {
      t.textContent = S.beg === 0 ? '请求 TA 停下' : (S.beg === 1 ? '再求一次' : '最后一次求 TA');
    }
    if (s) {
      if (!S.on) s.textContent = '装置已经停着了';
      else if (S.beg === 0) s.textContent = S.begDocile ? 'TA 会松口的' : 'TA 未必肯听';
      else if (S.begDocile || S.beg >= S.begNeed) s.textContent = '已经求了 ' + S.beg + ' 次 · TA 该松口了';
      else s.textContent = '已经求了 ' + S.beg + ' 次 · TA 还没答应（大概还要 ' + (S.begNeed - S.beg) + ' 次）';
    }
    b.disabled = !S.on;
  }

  /* 请求的落点。放在回复解析完之后判断：
     AI 自己肯停最好；没停的话看玩家求够了没有——默认模式求一次就兜底，
     顽固模式要两三回。不留兜底的话"说了会停"就落不了地。 */
  function settleBeg(hadReply) {
    if (S.target !== 'user' || S.beg <= 0) return;
    if (!hadReply) return;                          // 生成失败：留着计数，让人能再按
    if (!S.on) { S.beg = 0; paintBeg(); return; }   // TA 自己答应了
    if (S.begDocile || S.beg >= S.begNeed) {
      stop(charName() + '终于松了口', true);
      S.beg = 0;
      paintBeg();
      return;
    }
    paintBeg();
  }

  /* 装置运行中锁住作用对象切换。
     换对象要整本重写世界书，而装置还带着上一个对象的运行状态，
     两边对不上，AI 会同时收到两套设定。所以先停、后换。
     写得很轻，因为它每次启停都会被调到。 */
  function paintTargetLock() {
    var tb = $('#tgtbar');
    if (!tb) return;
    tb.classList.toggle('locked', S.on);
    tb.title = S.on ? '装置运行中，先停止才能换作用对象' : '';
  }

  /* 只有这一个入口改 S.target，避免两处状态各说各话 */
  function setTarget(t, notify) {
    if (t !== 'user' && t !== 'char' && t !== 'self') return;
    if (S.on) return;            // 运行中不许换，兜底
    if (S.target === t) return;
    S.target = t;
    S.pending = false;
    S.lastActionNote = '';
    S.beg = 0;   // 换了谁拿着遥控器，请求次数重新算
    bindSettings();
    persist();
    S.lastEvent = (t === 'user')
      ? '装置改为作用在玩家身上，遥控器交到 ' + charName() + ' 手里'
      : (t === 'self'
        ? '装置改为戴在玩家自己身上，遥控器也在玩家自己手里'
        : '装置改为作用在 ' + charName() + ' 身上，遥控器在玩家手里');
    syncWorldbook(true);   // 世界书要按新模式整本重写
    HAP.tap(t === 'user' ? 30 : 22);
    if (notify) {
      toast(t === 'user'
        ? '已切换：遥控器交给' + charName() + '，档位由 TA 决定'
        : (t === 'self'
          ? '已切换：自己玩，遥控器和装置都在你这'
          : '已切换：遥控器回到你手里'), 2600);
    }
  }
  /* =========================================================
   * 语音设置页（VOC）
   *
   * 两种传输方式，令牌归属不同：
   *   直连中转（默认）  → URL + 令牌都填在面板里，令牌随聊天变量存档
   *   经作者中转        → 面板必须填官方 Key，中转只转发、不留存
   * 默认直连是因为多数中转自己开了跨域、开箱即用；代价是令牌会进聊天文件，
   * 所以界面上明确标了这一点，不想要的人可以切到转发。
   * ======================================================= */
  function paintVoice() {
    var btn = $('#s-voice');
    if (btn) btn.textContent = VOICE_LABEL[S.voice] || '关';

    // 配置齐了没有 —— 一个地方算清楚，三处文案都用它，免得各说各话。
    // 令牌按通道算：直连与经作者中转都要 Key（作者中转只用你自己那把官方 Key）。
    var needTts = (S.voice === 'tts' || S.voice === 'both');
    var isAF = usingAF();
    var missing = [];
    if (needTts) {
      if (!S.ttsTarget) missing.push('合成地址');
      if (isAF && !afURL(S.ttsTarget)) missing.push('（这个官方地址本脚本中转不认）');
      if (S.ttsAuth !== 'none' && !S.ttsKey) missing.push(isAF ? '官方 API Key' : '令牌');
    }
    var ready = missing.length === 0;
    var missText = missing.join('、');
    // 通道名：文案里要说清"还差的那几项是为哪条路要的"
    var chanName = isAF ? '经作者中转' : '浏览器直打';

    var tag = $('#voice-tag');
    if (tag) {
      tag.textContent = (S.voice === 'off') ? ''
        : (S.voice === 'buzz' ? '未测试' : (ready ? 'TTS' : '待配置'));
    }
    var vsTag = $('#vs-tag');
    if (vsTag) {
      vsTag.textContent = (S.voice === 'off') ? '未开'
        : (S.voice === 'buzz' ? '未测试' : (ready ? '已配置' : '待配置'));
    }
    /* 语音页的状态摘要与"下一步做什么"，写在该页第一块面板的提示行里。
       检查结果与试听反馈各有各的位置（#vs-ping-hint / #vs-try-hint），不再互相覆盖。 */
    var vsHint = $('#vs-hint');
    if (vsHint) {
      vsHint.innerHTML = '当前：<b style="color:var(--cyan)">' + (VOICE_LABEL[S.voice] || '关') + '</b>　'
        + (VOICE_NOTE[S.voice] || '')
        + (needTts && !ready
          ? '<br><b style="color:var(--amber)">还差：' + esc4(missText) + '（'
            + chanName + '）—— 都在下面的「连接」里填。</b>'
          : '')
        + (needTts && ready
          ? '<br><b style="color:var(--amber)">' + chanName
            + '：令牌随聊天变量存档，注意环境。</b>'
          : '');
    }
    var note = $('#s-voiceai-note');
    if (note) {
      note.innerHTML = S.voiceAI
        ? '<b>当前：AI 生成。</b>随正文一起写一句「语音」进来，不多花一次额度；拿不到就自动退回台词库。'
        : '<b>当前：台词库。</b>零费用、零延迟，台词按阶段与作用对象取，每句自动配情绪标记；'
          + '打开 AI 生成则改为让模型写，更贴但更慢。';
    }
    // 设置页那条只是"怎么开"的入口提示，每次刷新都按当前状态重写
    var h = $('#voice-hint');
    if (h) {
      h.textContent = (S.voice === 'off')
        ? '语音目前是关的。开关、音色、合成地址都在「语音设置」页里。'
        : (needTts && !ready
          ? '当前是「' + VOICE_LABEL[S.voice] + '」，还差：' + missText + ' —— 去「语音设置」页补上。'
          : '当前是「' + VOICE_LABEL[S.voice] + '」。要调参数或试听，去「语音设置」页。');
    }
  }

  var AUTH_LABEL = { bearer: 'Bearer', raw: '裸 Authorization', 'x-api-key': 'x-api-key', none: '不带' };
  var AUTH_ORDER = ['bearer', 'raw', 'x-api-key', 'none'];

  /* 音色槽位（1 = 你拿着遥控器，2 = TA 拿着遥控器）。
     这里不预置任何具体音色 ID —— 音色是各平台自己的，写死一个等于给别的平台埋一个必然失败的默认值。 */
  function fillVoiceSelect(n) {
    var inp = $('#s-voice-' + n + '-input');
    if (!inp) return;
    var val = (n === 1 ? S.ttsVoice : S.ttsVoiceTease) || '';
    if (inp.value !== val) inp.value = val;
  }

  /* 输入框打字时别每个字都存一遍（每次都写聊天文件 + 全局设置 + localStorage）：停手 600ms 再存；
     change / blur 立即存 */
  var persistTimer = 0;
  function persistSoon(ev) {
    clearTimeout(persistTimer);
    if (ev && ev.type === 'input') { persistTimer = setTimeout(persist, 600); return; }
    persist();
  }
  function bindVoiceSlot(n, key) {
    var inp = $('#s-voice-' + n + '-input');
    if (!inp) return;
    var apply = function (ev) {
      S[key] = String(inp.value || '').trim();
      persistSoon(ev);
      paintVoice();
    };
    inp.addEventListener('input', apply);
    inp.addEventListener('change', apply);
    inp.addEventListener('blur', apply);
  }

  /* =========================================================
   * 合成平台：决定请求长什么样
   *
   * 只列"直接返回音频二进制"的平台 —— 这一类可以走同一条链路，换个请求体与字段名即可。
   * MiniMax / Gemini 返回的是 JSON 包 base64 音频（MiniMax 在 data.audio，还带 hex 的 status），
   * 需要额外的解码层，没有实测环境就不列进来装作支持。
   * ======================================================= */
  var PLATFORMS = {
    fish: {
      name: 'Fish Audio',
      lib: 'https://fish.audio/app/',
      libHint: '进页面后打开音色库（Voice），点进某个音色复制它的 ID',
      voiceField: 'reference_id',
      voiceHint: '在 Fish 音色库页面复制 model id（32 位十六进制）',
      /* 型号清单按官方文档列（models-overview）：
         s1 用 (括号) 情绪、S2 系列用 [方括号]；s1 将于 2026-12-31 退役。
         官方没有"列出 TTS 型号"的接口（GET /model 列的是你的音色，不是引擎型号），
         所以这里是静态清单，不是拉取来的。
         顺序有讲究：第一条是「推荐」按钮填的那个，所以放免费的
         s2.1-pro-free —— 付费档要求账号里有 API credit（和平台 credit 是两套），
         新用户拿付费档开箱就吃 402。 */
      modelList: [
        { id: 's2.1-pro-free', label: 'S2.1-Pro Free · $0 档，同一个模型（公平使用限额）' },
        { id: 's2.1-pro', label: 'S2.1-Pro · 质量档，按次计费，账号里要有 API credit' },
        { id: 's2-pro', label: 'S2-Pro · 上一代' },
        { id: 's1', label: 'S1 · 已弃用，2026-12-31 退役' }
      ],
      modelHint: '官方型号只有这四个（<code>s1</code> 与 S2 系列的情绪写法不同：'
        + 'S2 用 <code>[方括号]</code>，S1 用 <code>(括号)</code>）。<br>'
        + '<b>付费档要有 API credit</b> —— 它和网页版的平台 credit 是分开的两套，'
        + '余额不足时官方直接回 402。'
        + '想先跑通路就选 <code>s2.1-pro-free</code>（同一个模型的免费档）。'
        + '官网没有"列型号"的接口，这份清单照官方文档写死，可以自己改。',
      note: '主推：情绪标记（<code>[panting]</code> <code>[气声]</code>）完整支持，'
        + '音色库与本站同一套协议。<br>音色 ID 在音色库页面点进某个音色后复制。',
      req: function (c, text, vv) {
        var b = {
          text: text, format: c.format, sample_rate: 44100, normalize: true,
          latency: c.latency, temperature: 0.7, top_p: 0.7,
          chunk_length: 300, min_chunk_length: 50,
          prosody: { speed: c.speed, volume: 0, normalize_loudness: true }
        };
        if (vv) b[c.voiceField] = vv;
        if (c.format === 'mp3') b.mp3_bitrate = 128;
        return b;
      }
    },
    openai: {
      name: 'OpenAI 兼容',
      lib: 'https://platform.openai.com/docs/guides/text-to-speech',
      libHint: '音色是固定名字，文档里列了全部；中转可能另有自己的名字',
      voiceField: 'voice',
      voiceHint: '填官方音色名（alloy / ash / coral / nova / onyx / sage / shimmer …），或中转提供的名字',
      note: '走 <code>/v1/audio/speech</code>。音色是固定名字，不是十六进制 ID。'
        + '<br><b>注意：这套协议不认识情绪标记</b> —— 念出来会有点平，适合先试通路。',
      /* OpenAI 协议这边的型号由各家实现自定（官方 tts-1 / tts-1-hd / gpt-4o-mini-tts，
         中转另有自己的名字），所以只给提示不给清单。 */
      modelList: [],
      modelHint: '这套协议没有统一型号：官方是 <code>tts-1</code> / <code>tts-1-hd</code> / '
        + '<code>gpt-4o-mini-tts</code>，中转多半另有名字，按那边的说明填。',
      req: function (c, text, vv) {
        var b = { model: c.model || 'tts-1', input: text, response_format: 'mp3', speed: c.speed };
        if (vv) b.voice = vv;
        // instructions 是较新模型才有的字段，默认不发；打开开关才带
        if (c.langBoost) b.instructions = '用气声、喘息与不稳定的语气念，像是在极力忍耐；不要平铺直叙。';
        return b;
      }
    },
    /* MiniMax（T2A v2）。和上面两家最大的不同有两点：
       ① 它返回的是 **JSON**，音频藏在 `data.audio` 里、还是 **hex 编码**的字符串，
          不是音频二进制 —— 所以要靠 resp:'minimax' 走另一条解析路径；
       ② 情绪/喘息的写法是**全角括号**（气声）（pant），不是 [方括号]。
          官方还只在 speech-2.8 系列上支持这类插词，其余模型会把它当正文念出来，
          所以标记转不转要跟着模型名走。
       国际版端点 api.minimax.io、国内版 api.minimaxi.com —— OFFICIAL_URL 里默认给的是国际版，
       国内账号把「合成地址」改成 api.minimaxi.com 那一条即可。 */
    minimax: {
      name: 'MiniMax 语音',
      lib: 'https://platform.minimax.io/',
      libHint: '开放平台的音色列表（System Voice ID List）里复制 voice_id，'
        + '形如 Chinese (Mandarin)_Lyrical_Voice、English_Graceful_Lady',
      voiceField: 'voice_id',
      voiceHint: '填 voice_id（如 Chinese (Mandarin)_Lyrical_Voice / English_Graceful_Lady），'
        + '不是十六进制',
      /* 型号清单照官方 OpenAPI 的 model enum 抄（t2a_v2）：
         speech-2.8 / 2.6 / 02 / 01 各 hd 与 turbo 两档，共八条。
         官方没有"列出 TTS 型号"的接口，所以这份是静态清单。 */
      modelList: [
        { id: 'speech-2.8-turbo', label: 'Speech 2.8 Turbo · 默认，快，支持情绪插词' },
        { id: 'speech-2.8-hd', label: 'Speech 2.8 HD · 质量更好，支持情绪插词' },
        { id: 'speech-2.6-turbo', label: 'Speech 2.6 Turbo · 不支持插词，标记会被去掉' },
        { id: 'speech-2.6-hd', label: 'Speech 2.6 HD · 不支持插词' },
        { id: 'speech-02-turbo', label: 'Speech 02 Turbo · 不支持插词' },
        { id: 'speech-02-hd', label: 'Speech 02 HD · 不支持插词' },
        { id: 'speech-01-turbo', label: 'Speech 01 Turbo · 不支持插词' },
        { id: 'speech-01-hd', label: 'Speech 01 HD · 不支持插词' }
      ],
      modelHint: '官方型号是这八个（<code>speech-2.8-hd / 2.8-turbo</code> 及各自的老版本）。'
        + '<b>只有 2.8 系列认情绪插词</b>，选老版本时面板会自动把标记去掉。'
        + '官网没有"列型号"的接口，这份清单照官方文档写死，可以自己改。',
      note: '走 <code>POST /v1/t2a_v2</code>，鉴权只要 <code>Authorization: Bearer &lt;API key&gt;</code>'
        + '（不需要 GroupId）。<br>音色填 voice_id。'
        + '<b>情绪标记只在 speech-2.8-hd / speech-2.8-turbo 上生效</b>：'
        + '换成别的模型（speech-2.6 / speech-02 / speech-01）时面板会自动把标记去掉 ——'
        + '否则它们会被当正文念出来。',
      resp: 'minimax',
      req: function (c, text, vv) {
        var b = {
          model: c.model || 'speech-2.8-turbo',
          text: text,
          stream: false,
          language_boost: 'auto',     // 中英混排都能认
          output_format: 'hex',       // 官方默认就是 hex，写明免得以后默认值变了
          voice_setting: { speed: c.speed, vol: 1, pitch: 0 },
          audio_setting: { format: c.format || 'mp3', sample_rate: 32000, bitrate: 128000, channel: 1 }
        };
        if (vv) b.voice_setting.voice_id = vv;
        return b;
      }
    },
    custom: {
      name: '其他 / 自定义协议',
      lib: 'https://fish.audio/app/',
      libHint: '没有固定入口，按你平台的文档找',
      voiceField: 'reference_id',
      voiceHint: '音色 ID',
      note: '自己填字段名与额外请求头去凑。'
        + '<b>只适用于返回音频二进制的接口</b>；返回 JSON 包 base64 的协议当前接不了。',
      modelList: [],
      modelHint: '自定义协议没有固定型号清单，按你那边中转给的型号名填。',
      req: function (c, text, vv) {
        var b = {
          text: text, format: c.format, sample_rate: 44100, normalize: true,
          latency: c.latency, temperature: 0.7, top_p: 0.7,
          chunk_length: 300, min_chunk_length: 50,
          prosody: { speed: c.speed, volume: 0, normalize_loudness: true }
        };
        if (vv) b[c.voiceField] = vv;
        if (c.format === 'mp3') b.mp3_bitrate = 128;
        return b;
      }
    }
  };

  /* 官方地址的下拉候选：只列真正有官方端点的平台。
     OpenAI 兼容与「其他/自定义」没有固定官方地址（要用户自己填），
     把它们塞进下拉只会让人以为「照官方地址打就一定通」—— 其实那两家都是中转协议。 */
  var ADDR_LABEL = { fish: 'Fish Audio', minimax: 'MiniMax' };
  var ADDR_ALT = [
    { url: 'https://api.minimax.io/v1/t2a_v2', label: 'MiniMax 语音 · 国际站' },
    { url: 'https://api.minimaxi.com/v1/t2a_v2', label: 'MiniMax 语音 · 国内站' }
  ];
  function fillTargetOptions() {
    var dl = $('#s-target-list');
    if (!dl || !OFFICIAL_URL) return;   // 这段可能早于 OFFICIAL_URL 的赋值被调到
    dl.innerHTML = '';
    var seen = {};
    function put(url, label) {
      if (!url || seen[url]) return;
      seen[url] = 1;
      var o = document.createElement('option');
      o.value = url; o.label = label;
      dl.appendChild(o);
    }
    put(OFFICIAL_URL[S.ttsPlatform], (ADDR_LABEL[S.ttsPlatform] || S.ttsPlatform) + ' 官方端点');
    ADDR_ALT.forEach(function (a) { put(a.url, a.label); });
  }
  // 手打了某个已知官方地址 → 平台自动跟过去，免得"地址是 A 家、协议按 B 家发"
  function adoptPlatformFromTarget() {
    var t = String(S.ttsTarget || '').replace(/\/+$/, '');
    var keys = Object.keys(OFFICIAL_URL);
    for (var i = 0; i < keys.length; i++) {
      if (OFFICIAL_URL[keys[i]].replace(/\/+$/, '') !== t) continue;
      // minimax 两家地址都算 MiniMax；多家共用一条地址时按平台自身顺序取第一个
      if (S.ttsPlatform === keys[i]) return;
      S.ttsPlatform = keys[i];
      var sel = $('#s-platform'); if (sel) sel.value = keys[i];
      paintPlatform(); paintTransport();
      return;
    }
  }

  /* 模型候选：按当前平台填进 datalist，并更新说明。
     说清楚一件事 —— 官方没有"列出 TTS 型号"的接口（Fish 的 GET /model 列的是
     你的音色、MiniMax 的 get_voice 列的是音色），所以这份清单是照官方文档写死的，
     可编辑；真要拿到适配你账号的型号，只有试听一次才算数。 */
  function fillModelOptions() {
    var p = PLATFORMS[S.ttsPlatform] || PLATFORMS.fish;
    var hint = $('#s-model-hint');
    if (hint) hint.innerHTML = p.modelHint || '按中转支持的模型名填。';
    var dl = $('#s-model-list');
    if (dl) {
      dl.innerHTML = '';
      (p.modelList || []).forEach(function (m) {
        var o = document.createElement('option');
        o.value = m.id; o.label = m.label;
        dl.appendChild(o);
      });
    }
    // 「推荐」那颗按钮：这个平台没有清单时就收起来，别摆一个点了没用的东西
    var btn = $('#c-model-refresh');
    if (btn) btn.style.display = (p.modelList && p.modelList.length) ? '' : 'none';
  }
  /* 换平台时，把"上一家的型号"换成新平台的推荐型号。
     判据是显式的：当前型号为空、或者属于**别的**平台的清单 —— 那样留着它一定发不出去
     （比如 Fish 的 s2.1-pro-free 发给 MiniMax）。用户自己输的第三方型号名不动。 */
  function adoptModelForPlatform() {
    var p = PLATFORMS[S.ttsPlatform] || PLATFORMS.fish;
    var list = p.modelList || [];
    if (!list.length) return;
    var cur = String(S.ttsModel || '').trim();
    var foreign = false;
    Object.keys(PLATFORMS).forEach(function (k) {
      if (k === S.ttsPlatform) return;
      (PLATFORMS[k].modelList || []).forEach(function (m) { if (m.id === cur) foreign = true; });
    });
    if (!cur || foreign) {
      S.ttsModel = list[0].id;
      var el = $('#s-tts-model'); if (el) el.value = S.ttsModel;
    }
  }

  function paintPlatform() {
    var p = PLATFORMS[S.ttsPlatform] || PLATFORMS.fish;
    var sel = $('#s-platform');
    if (sel && sel.value !== S.ttsPlatform) sel.value = S.ttsPlatform;
    var note = $('#s-plat-note');
    if (note) note.innerHTML = '<b>' + esc4(p.name) + '</b>　' + p.note;
    var n1 = $('#s-voice1-note');
    if (n1) n1.textContent = '被作用的是 TA，出的是呻吟。' + p.voiceHint;
    var i1 = $('#s-voice-1-input');
    if (i1) i1.placeholder = p.voiceHint;
    var i2 = $('#s-voice-2-input');
    if (i2) i2.placeholder = p.voiceHint;
    var lb = $('#s-tts-langboost');
    if (lb) lb.classList.toggle('on', !!S.ttsLangBoost);
    // 高级区按平台显隐：Fish 那套字段对 OpenAI 不适用，混在一起会让人以为要全填
    var forOpenai = (S.ttsPlatform === 'openai');
    var gFish = $('#s-adv-fish'), gOai = $('#s-adv-openai');
    if (gFish) gFish.style.display = forOpenai ? 'none' : 'block';
    if (gOai) gOai.style.display = forOpenai ? 'block' : 'none';
    // 地址下拉候选随平台走（选 Fish 时把 Fish 端点排在第一个）
    fillTargetOptions();
    // 模型候选与说明也随平台走
    fillModelOptions();
  }

  /* 音色库链接：不同平台入口不一样，给个按钮直接过去找，省得"我去哪拿 ID"。
     三级退路 —— window.open 在沙箱 iframe 里会被静默拦下（返回 null 而不是抛错），
     所以光靠 try/catch 抓不到；退回真实 <a> 点击，再不行就把地址复制到剪贴板。 */
  function openLib(which) {
    var p = PLATFORMS[S.ttsPlatform] || PLATFORMS.fish;
    var url = p.lib || '';
    if (!url) { toast('这个平台没有固定的音色库页面'); return; }
    var slot = (which === 2) ? 'TA 拿着遥控器时' : '你拿着遥控器时';
    VOC.addLog('打开音色库（' + p.name + '）→ ' + url, 'hi');
    toast('去音色库找 ID，找到填到「' + slot + '的音色」里', 3600);
    /* ① 常规跳转。被拦时返回 null（不抛错），所以必须查返回值 */
    try { if (window.open(url, '_blank', 'noopener')) return; } catch (e) { /* 落到下一级 */ }
    /* ② 造一个真实的 <a> 点它：这条路绕开 window.open 的弹窗判定 */
    try {
      var a = document.createElement('a');
      a.href = url; a.target = '_blank'; a.rel = 'noopener noreferrer';
      a.style.display = 'none';
      (WIN.document.body || DOC.body).appendChild(a);
      a.click();
      setTimeout(function () { try { a.remove(); } catch (e) { /* noop */ } }, 1200);
      return;
    } catch (e2) { /* 落到下一级 */ }
    /* ③ 复制地址并指路：至少让用户能自己粘到浏览器里 */
    copyTextAsync(url, function () {
      toast('跳转被拦下了。地址已复制：' + url, 5600);
    }, function (txt) {
      if (revealForManualCopy(txt)) toast('跳转被拦下了，剪贴板也不可用 —— 地址已选中，复制它：' + txt, 7000);
      else toast('跳转被拦下了，请手动打开：' + txt, 7000);
    });
  }

  (function bindPlatform() {
    var sel = $('#s-platform');
    if (sel) {
      sel.addEventListener('change', function () {
        /* 用 sel.value 而不是 this.value：这条路上不该依赖 this 的绑定，
           合成事件（程序触发 change）时 this 未必是这个 select。 */
        var before = isOfficialAddr(S.ttsTarget);   // 判断要在改平台之前做：isOfficial() 认的是"当前平台"
        S.ttsPlatform = sel.value;
        // 上一家的型号发给新平台一定失败，这里换成新平台的推荐型号
        adoptModelForPlatform();
        var next = officialKeyOf(S.ttsTarget);
        /* 只有官网 api 那一档、且确实是官方端点时才替用户换地址：
           中转 api 那一档地址是你自己的中转站，替它改掉等于把配置清了。 */
        if (before) {
          var off = OFFICIAL_URL[sel.value];
          // OpenAI 兼容 / 自定义没有固定官方地址，保持用户原样
          if (off) {
            S.ttsTarget = off;
            var tg = $('#s-tts-target'); if (tg) tg.value = off;
            next = officialKeyOf(off);
          }
        }
        /* 通道跟着地址走：走作者中转要求地址必须是它认的两个官方端点之一，
           换到它不认的地址（MiniMax 国内站之类）时必须退回直连 ——
           否则用户会看到"作者的中转服务器"亮着，实际发不出去。 */
        if (usingAF() && !afReady()) S.ttsTransport = 'direct';
        paintPlatform();
        paintTransport();
        persist();
        var p = PLATFORMS[S.ttsPlatform];
        var sameFamily = next && before && next !== before;
        toast('合成平台：' + p.name
          + (sameFamily ? '（地址已换成它的官方端点）' : ''), 2600);
      });
    }
    // 地址是选出来的、也是手打的：认得出是哪家官方地址时，平台跟着走
    onEl('#c-open-lib', 'click', function () { openLib(1); });
    // 「推荐」：一键填当前平台的首选型号（清单里第一条就是官方推荐的那个）
    onEl('#c-model-refresh', 'click', function () {
      var p = PLATFORMS[S.ttsPlatform] || PLATFORMS.fish;
      var list = p.modelList || [];
      if (!list.length) { toast('这个平台没有固定的型号清单，按中转给的说明填'); return; }
      S.ttsModel = list[0].id;
      var el = $('#s-tts-model'); if (el) el.value = S.ttsModel;
      persist();
      toast('模型：' + list[0].id + '（' + list[0].label + '）', 3200);
    });
    onEl('#c-lib-1', 'click', function () { openLib(1); });
    onEl('#c-lib-2', 'click', function () { openLib(2); });
  })();

  /* =========================================================
   * 保存按钮
   *
   * 配置本来就是"改动即存"（input/change/blur 都挂了 persist），这个按钮是**显式再存一次**：
   * 手机上输入法还开着、最后一个字没落进输入框时，点一下会把界面上的当前值重读一遍，
   * 顺带给出"确实存了"的确认。它不会做任何自动保存做不到的事，只是一个确定动作。
   * ======================================================= */
  function saveAll(pick) {
    var n = 0;
    if (pick !== 'voice') {
      // 连接：地址 / 令牌
      var tg = $('#s-tts-target'); if (tg) { S.ttsTarget = String(tg.value || '').trim(); n++; }
      var ky = $('#s-tts-key'); if (ky) { S.ttsKey = String(ky.value || '').trim(); n++; }
    }
    if (pick !== 'conn') {
      // 音色与合成参数
      var v1 = $('#s-voice-1-input'); if (v1) { S.ttsVoice = String(v1.value || '').trim(); n++; }
      var v2 = $('#s-voice-2-input'); if (v2) { S.ttsVoiceTease = String(v2.value || '').trim(); n++; }
      var md = $('#s-tts-model'); if (md) { S.ttsModel = String(md.value || '').trim(); n++; }
      var sp = $('#s-tts-speed');
      if (sp) { S.ttsSpeed = clamp(parseFloat(sp.value) || 1, 0.5, 1.5); sp.value = S.ttsSpeed; n++; }
    }
    // 高级项（两个平台分组各有一个额外请求头框，值本来共用）
    var mh = $('#s-tts-modelhdr'); if (mh) S.ttsModelHdr = String(mh.value || '').trim() || 'model';
    var rf = $('#s-tts-reffield'); if (rf) S.ttsRefField = String(rf.value || '').trim() || 'reference_id';
    var exA = $('#s-tts-extra'), exB = $('#s-tts-extra-oai');
    var ex = (exA && exA.value) || (exB && exB.value) || '';
    S.ttsExtraHdrs = String(ex).trim();

    persist();
    paintTransport();
    paintPlatform();
    paintVoice();
    VOC.addLog('手动保存：已把界面上的值写回（' + n + ' 项）', 'ok');

    // 存完了顺带说清"现在缺什么"，比只弹一句"已保存"有用
    var miss = [];
    if (!S.ttsTarget) miss.push('合成地址');
    if (S.ttsAuth !== 'none' && !S.ttsKey) miss.push(usingAF() ? '官方 API Key' : '令牌');
    if (usingAF() && !afURL(S.ttsTarget)) miss.push('这个地址作者中转不认');
    var h = $('#vs-ping-hint');
    if (miss.length) {
      if (h) h.textContent = '已保存。还差：' + miss.join('、') + ' —— 补齐后才能出声。';
      toast('已保存 · 还差 ' + miss.join('、'), 3200);
    } else {
      if (h) h.textContent = '已保存。要点「连通性检查」确认通道，然后就能试听了。';
      toast('已保存 · 可以去点「连通性检查」', 2800);
    }
  }
  /* 保存按钮的接线。
     「保存音色与参数」只负责把界面上的值写回配置；要往音色簿里存一条，
     走音色簿那一行的「存为新的」—— 两件事分开，按钮上就不用再藏第二个作用。 */
  onEl('#c-save-conn', 'click', function () { saveAll('conn'); });
  onEl('#c-save-voice', 'click', function () { saveAll('voice'); });

  /* 第二个音色是可选功能：关掉时清空它，两个档位共用第一个音色 */
  function bindVoiceTwo() {
    var sw = $('#s-voice-two');
    var box = $('#s-voice-2-box');
    // 只看 ttsVoiceTease 的话，开了开关还没填 ID 时一刷新就变回关：开关状态单独记一份
    var on = !!S.ttsVoiceTease || !!S.voiceTwo;
    if (sw) sw.classList.toggle('on', on);
    if (box) box.style.display = on ? 'block' : 'none';
    if (sw) {
      sw.addEventListener('click', function () {
        var next = !sw.classList.contains('on');
        S.voiceTwo = next;
        sw.classList.toggle('on', next);
        if (box) box.style.display = next ? 'block' : 'none';
        if (!next) {
          S.ttsVoiceTease = '';
          var inp = $('#s-voice-2-input');
          if (inp) inp.value = '';
          fillVoiceSelect(2);
        }
        persist();
        toast(next ? 'TA 拿着遥控器时用单独的音色' : '两个档位共用同一个音色');
      });
    }
  }
  bindVoiceSlot(1, 'ttsVoice');
  bindVoiceSlot(2, 'ttsVoiceTease');
  bindVoiceTwo();

  /* =========================================================
   * 音色簿
   *
   * 「保存音色与参数」按下去时，除了把界面上的值写回配置，还会把**当前这套**
   * （音色 ID + 模型 + 格式 + 语速）另存成音色簿里的一条。之后这个下拉框才出现：
   * 挑一条就把那套参数整套还原，不用再一个个格子重填。
   *
   * 命名走 window.prompt —— 手机上是一个原生输入框，比再做一个重命名面板短得多。
   * 同名再存就是覆盖，这是"改完再存一次"的自然期望，所以不拦。
   * ======================================================= */
  function slotInput(n) { return $('#' + (n === 2 ? 's-voice-2-input' : 's-voice-1-input')); }
  function slotSelKey(n) { return n === 2 ? 'voiceSel2' : 'voiceSel1'; }

  function findBook(name) {
    for (var i = 0; i < S.voiceBook.length; i++) if (S.voiceBook[i].name === name) return i;
    return -1;
  }
  /* 把当前这套存成一条。n 决定"当前音色 ID"取哪个槽位 ——
     在第二格上按保存时，取的是 TA 那一格的值，不能一律拿 ttsVoice。 */
  function addBook(name, n) {
    name = String(name || '').trim().slice(0, 16);
    if (!name) { name = '音色 ' + (S.voiceBook.length + 1); }
    var rec = {
      name: name,
      id: ((n === 2 ? S.ttsVoiceTease : S.ttsVoice) || ''),
      model: S.ttsModel || '',
      format: S.ttsFormat || 'mp3',
      speed: S.ttsSpeed || 1
    };
    var at = findBook(name);
    if (at >= 0) { S.voiceBook[at] = rec; return { rec: rec, over: true }; }
    S.voiceBook.push(rec);
    return { rec: rec, over: false };
  }
  function renameBook(oldName, newName) {
    newName = String(newName || '').trim().slice(0, 16);
    var at = findBook(oldName);
    if (at < 0) return { ok: false, why: '这一条已经不在了' };
    if (!newName) return { ok: false, why: '名字不能是空的' };
    if (newName === oldName) return { ok: true, same: true };
    if (findBook(newName) >= 0) return { ok: false, why: '已经有同名的了' };
    S.voiceBook[at].name = newName;
    for (var s = 1; s <= 2; s++) {
      var k = slotSelKey(s);
      if (S[k] === oldName) S[k] = newName;
    }
    return { ok: true, renamed: newName };
  }
  function delBook(name) {
    var at = findBook(name);
    if (at < 0) return;
    S.voiceBook.splice(at, 1);
    for (var s = 1; s <= 2; s++) { var k = slotSelKey(s); if (S[k] === name) S[k] = ''; }
  }

  /* 把某一条的整套参数还原到界面上。
     不动合成平台与高级请求头 —— 那些是"这条中转怎么打"的设置，
     换个音色不该顺手把它们也换了。 */
  function applyBook(n, name) {
    var at = findBook(name);
    if (at < 0) return false;
    var b = S.voiceBook[at];
    var inp = slotInput(n);
    if (inp) inp.value = b.id;
    if (n === 2) S.ttsVoiceTease = b.id; else S.ttsVoice = b.id;
    if (b.model) S.ttsModel = b.model;
    if (b.format) S.ttsFormat = b.format;
    if (typeof b.speed === 'number') S.ttsSpeed = clamp(b.speed, 0.5, 1.5);
    S[slotSelKey(n)] = b.name;
    paintVoice();
    paintBook();
    persist();
    VOC.addLog('音色簿：套用「' + b.name + '」' + (b.id ? '（' + b.id.slice(0, 12) + '…）' : '（没有 ID）'), 'hi');
    toast('已套用音色「' + b.name + '」', 2200);
    return true;
  }

  /* 画音色簿。常驻显示，不再按"存过没存过"整块隐藏 ——
     空的时候下拉框给一句占位说明，「改名」「删除」置灰，只剩「存为新的」可点。 */
  var BOOK_PAINTING = false;
  function paintBook() {
    BOOK_PAINTING = true;
    for (var n = 1; n <= 2; n++) {
      var sel = $('#vb-' + n + '-sel');
      if (!sel) continue;
      var cur = S[slotSelKey(n)];
      var hasCur = !!(cur && findBook(cur) >= 0);
      var h;
      if (!S.voiceBook.length) {
        h = '<option value="">（音色簿是空的 —— 点「存为新的」把当前这套存进来）</option>';
      } else {
        h = '<option value="">（选一个存过的音色）</option>';
        for (var i = 0; i < S.voiceBook.length; i++) {
          var b = S.voiceBook[i];
          h += '<option value="' + esc4(b.name) + '"' + (b.name === cur ? ' selected' : '') + '>'
            + esc4(b.name) + (b.id ? '' : '（没有 ID）') + '</option>';
        }
      }
      sel.innerHTML = h;
      sel.value = hasCur ? cur : '';
      /* 「改名」「删除」要有目标才能点：没选中任何一条就置灰。
         以前它们点了只弹一句"先在下拉框里选一个音色"，不如直接不让点。 */
      var ren = $('#vb-' + n + '-ren'), del = $('#vb-' + n + '-del');
      if (ren) ren.disabled = !hasCur;
      if (del) del.disabled = !hasCur;
    }
    BOOK_PAINTING = false;
  }

  (function bindBook() {
    for (var n = 1; n <= 2; n++) {
      (function (n) {
        onEl('#vb-' + n + '-sel', 'change', function () {
          if (BOOK_PAINTING) return;
          if (!this.value) { S[slotSelKey(n)] = ''; persist(); paintBook(); return; }
          applyBook(n, this.value);
        });
        /* 「存为新的」：把当前这一格（ID + 模型 + 格式 + 语速）存成一条。
           以前这件事藏在「保存音色与参数」里，按钮上看不出它会做两件事。 */
        onEl('#vb-' + n + '-new', 'click', function () {
          var curId = (n === 2 ? S.ttsVoiceTease : S.ttsVoice);
          if (!curId) { toast('先在上面填一个音色 ID，再存进音色簿', 2800); return; }
          var guess = '';
          for (var i = 0; i < S.voiceBook.length; i++) {
            var b = S.voiceBook[i];
            if (b.id && b.id === curId && b.model === S.ttsModel) guess = b.name;
          }
          var name = window.prompt('给它起个名字（重名会覆盖）：', guess);
          if (name === null) return;
          var r = addBook(name, n);
          S[slotSelKey(n)] = r.rec.name;
          paintBook();
          persist();
          toast(r.over ? '已覆盖「' + r.rec.name + '」' : '已存进音色簿：「' + r.rec.name + '」', 2600);
          VOC.addLog('音色簿：' + (r.over ? '覆盖' : '新增') + '「' + r.rec.name + '」', 'ok');
        });
        onEl('#vb-' + n + '-ren', 'click', function () {
          var cur = S[slotSelKey(n)];
          if (!cur) { toast('先在下拉框里选一个音色'); return; }
          var name = window.prompt('给它改个名字（最多 16 字）', cur);
          if (name === null) return;
          var r = renameBook(cur, name);
          if (!r.ok) { toast('改名失败：' + r.why, 2800); return; }
          if (r.same) return;
          paintBook();
          paintVoice();      // 音色槽位上的名字也刷新，别让两处对不上
          persist();
          toast('已改名为「' + r.renamed + '」');
        });
        onEl('#vb-' + n + '-del', 'click', function () {
          var cur = S[slotSelKey(n)];
          if (!cur) { toast('先在下拉框里选一个音色'); return; }
          if (!window.confirm('从音色簿里删掉「' + cur + '」？\n只会少一条保存记录，音色 ID 本身不会动。')) return;
          delBook(cur);
          paintBook();
          persist();
          toast('已删除「' + cur + '」');
        });
      })(n);
    }
  })();

  /* 传输方式的显示与说明。以前这一段的函数头被误写成了 bindVoice，
     导致 paintTransport 根本不存在 —— 启动流程第一次调用它就抛
     "paintTransport is not defined"，整个 boot 中断，window.__TOYLINK__ 永远
     挂不上去，面板看着在、实际全是死的。函数名务必和下面那个 bindVoice 区分开。 */
  /* 连接面板的显示与说明。
     两个按钮选择"连到哪儿"（官网 / 中转），一个开关选"走哪条路"（浏览器直打 / 本机转发）。
     以前只有一个在两种传输方式之间切的按钮，名字里没提官网还是中转，
     结果让人以为"直连中转"就是官网直连 —— 其实它一直是中转站。 */
  var OFFICIAL_URL = {
    fish: 'https://api.fish.audio/v1/tts',
    minimax: 'https://api.minimax.io/v1/t2a_v2'
  };
  // 认官网不能只认 fish 那一个域名；MiniMax 国际版/国内版是两个域名，都算官网
  var OFFICIAL_HOST = {
    fish: ['api.fish.audio'],
    minimax: ['api.minimax.io', 'api.minimaxi.com']
  };
  function isOfficial() {
    var off = OFFICIAL_URL[S.ttsPlatform];
    if (!off) return false;
    var t = String(S.ttsTarget || '');
    var hosts = OFFICIAL_HOST[S.ttsPlatform] || [];
    for (var i = 0; i < hosts.length; i++) if (t.indexOf(hosts[i]) >= 0) return true;
    return false;
  }
  /* 反过来问：这个地址是"哪一家"的官方端点？返回 null 表示它不是官方端点。
     需要它是因为 isOfficial() 是拿"当前平台"的 host 去比地址的 ——
     换了平台之后再问它，旧地址当然答"不是官方"，会把换平台时的判断带偏。 */
  function officialKeyOf(url) {
    var t = String(url || '');
    if (!t) return null;
    var keys = Object.keys(OFFICIAL_URL);
    for (var i = 0; i < keys.length; i++) {
      var hosts = OFFICIAL_HOST[keys[i]] || [];
      for (var j = 0; j < hosts.length; j++) if (t.indexOf(hosts[j]) >= 0) return keys[i];
    }
    return null;
  }
  // 这个地址是不是某家平台的官方端点（与"当前选的是哪家"无关）
  function isOfficialAddr(url) { return !!officialKeyOf(url); }

  /* =========================================================
   * 经作者的中转服务器转发
   *
   * 官方端点不给跨域头，浏览器直打一定被拦。以前靠本机跑一个 node 脚本
   * （工具-转发.js）绕开，但手机用户跑不了那个脚本 —— 现在改成作者自己的中转服务器：
   * 公网 HTTPS，浏览器直接打得到，打开跨域，鉴权用的还是你自己填的官方 Key。
   *
   * 它只认两个固定的官方端点（服务器按路径白名单转发，不是任意网址代理），
   * 所以能不能走这条路，看的是"当前官方地址是不是它认识的那两个"——
   * 不是看平台名。MiniMax 国内站 api.minimaxi.com 服务器连不上，这里也不给它映射。
   * ======================================================= */
  var AF = 'https://rp-tavern-fj.koreacentral.cloudapp.azure.com/tts';
  var AF_URL = {
    'https://api.fish.audio/v1/tts': AF + '/fish/v1/tts',
    'https://api.minimax.io/v1/t2a_v2': AF + '/mm/v1/t2a_v2'
  };
  /* 官方地址 → 中转地址。认不出就返回空串（调用方据此提示走别的通道）。
     比对整条地址而不只是域名 —— 免得用户把地址改成别的路径时被误判成"还能中转"。 */
  function afURL(official) {
    var t = String(official || '').replace(/\/+$/, '');
    return (AF_URL && AF_URL[t]) || '';
  }
  // 现在这一格填的官方地址，是不是作者中转认识的那两个之一
  function afReady() { return !!afURL(S.ttsTarget); }
  /* 「经本机转发」（本机跑 node 工具-转发.js）已经拆掉：手机用户跑不了那个脚本，
     能跑的人也没因此省掉一步麻烦。现在只剩两条路：
       'direct' 浏览器直打（打用户填的地址，官方或第三方中转）
       'af'     经作者的中转服务器转发（由官方地址固定映射出来）
     老配置里是 'relay' 的，恢复时会被折算成 'direct' —— 宁可让用户重新点一次，
     也不能把他的 Key 与台词悄悄送到别人的服务器上。 */
  function usingAF() { return S.ttsTransport === 'af'; }
  // 是不是"经转发"（作者中转）。保留这个包装是为了让调用处的语义读起来完整。
  function forwarding() { return usingAF(); }
  // 健康检查地址：中转根下的 /tts/health，不带 Key、不带文本，不产生合成费用
  function afHealth() { return AF + '/health'; }

  function paintTransport() {
    var direct = !forwarding();
    var official = isOfficial();
    // 两个按钮的选中态
    var bo = $('#s-tp-official'), br = $('#s-tp-relay');
    if (bo) bo.classList.toggle('on', official);
    if (br) br.classList.toggle('on', !official);

    // 字段标题与说明随"连到哪儿"变
    var tlb = $('#s-target-lb'), tnt = $('#s-target-note');
    var klb = $('#s-key-lb'), knt = $('#s-key-note'), ant = $('#s-auth-note');
    if (official) {
      if (tlb) tlb.textContent = '官方地址';
      if (tnt) tnt.innerHTML = '官方 TTS 端点。一般不用改 —— 换平台时这里会自动跟着换。';
      if (klb) klb.textContent = '官方 API Key';
      if (ant) ant.textContent = '官方走标准 Bearer，不用改。';
    } else {
      if (tlb) tlb.textContent = '中转地址';
      if (tnt) tnt.innerHTML = '你的中转站完整地址，例如 <code>https://你的中转域名/v1/tts</code>。';
      if (klb) klb.textContent = '中转令牌';
      if (ant) ant.textContent = '中转不走标准 Bearer 时改这里。';
    }

    /* 走法只剩两条：作者的中转服务器（默认）/ 浏览器直打（备选）。
       「经本机转发」（本机跑 node 工具-转发.js）已经拆掉 —— 手机用户跑不了那个脚本，
       能跑的人也没因此少一步麻烦，留着只会让人点进死路。 */
    /* 通道标签只在"官网那一档"才有意义：
       「作者的中转服务器」是官网模式专用的转发；切到「中转 api」之后它就不成立了。
       所以这里必须同时看 official —— 只看 S.ttsTransport 的话，
       用户从官网切到中转 api 后按钮仍写着「作者的中转服务器」（实际地址已是中转地址），
       得再点一次才消失。 */
    var af = usingAF() && official;                 // 真的在走作者中转
    var afUsable = afReady() || !official;          // 作者中转这条通道能不能用

    // 令牌说明：按实际通道给对应的话
    if (knt) {
      if (af) {
        knt.innerHTML = '走这一档时<b>必须填</b>：中转只转发，不带任何 Key，'
          + '官方那边认的就是你自己的这一把。存在本机（跟着用户存档），新建对话不用重填。';
      } else if (official) {
        knt.innerHTML = '<b style="color:var(--amber)">现在的走法是「浏览器直打」，这样打不通</b>：'
          + '官方端点不给跨域头，浏览器一定拦下（报 Failed to fetch）。<br>'
          + '点上面那颗切回「作者的中转服务器」—— 那才是默认能用的一条。';
      } else {
        knt.innerHTML = '第三方中转给你的 API Key。按密码处理：输入时遮住，右边可以临时看一眼；'
          + '存在本机（跟着用户存档），新建对话不用重填。';
      }
    }
    /* 两条通道摆在一起，但官网那一档下它们并不等价：
       「作者的中转服务器」是打得通的那条，「浏览器直打」必然被官方跨域拦下。
       所以按钮文案自己带状态，说明文只讲"你现在选的这条会怎样" —— 不平均用力。 */
    var fw = $('#s-tp-forward');
    if (fw) {
      fw.classList.toggle('on', !direct);
      fw.textContent = direct ? '浏览器直打' : '作者的中转服务器';
    }
    var fn = $('#s-forward-note');
    if (fn) {
      if (af) {
        fn.innerHTML = '请求经上面的<b>「作者的中转服务器」</b>转发到官方端点，两端都是 HTTPS，'
          + '用的是你自己填的官方 API Key。<br>'
          + '换回「浏览器直打」就要那个官方端点自己开跨域 —— 官方没有，所以这条路走不通。';
      } else if (official && afUsable) {
        fn.innerHTML = '<b style="color:var(--amber)">你选的是「浏览器直打」：官方端点不给跨域头，'
          + '一定会被浏览器拦下（报 <code>Failed to fetch</code>）—— 这是备选，不是能用的那条。</b><br>'
          + '点这颗切回「作者的中转服务器」就能跑通，手机上也能用。';
      } else if (official) {
        fn.innerHTML = '<b style="color:var(--amber)">这个官方地址作者中转不认</b> —— '
          + '它只固定转发 Fish 官方 <code>api.fish.audio/v1/tts</code> 与 MiniMax 国际站 '
          + '<code>api.minimax.io/v1/t2a_v2</code> 两条（不是任意网址代理）。<br>'
          + 'MiniMax 国内站（<code>api.minimaxi.com</code>）、别的第三方或自建中转都走不了这条路。'
          + '要么把「合成地址」改回官方端点，要么切到上面的「中转 api」填你自己的中转地址。';
      } else {
        fn.innerHTML = '直连你自己填的那个中转地址。'
          + '通不通取决于<b>它有没有开跨域（CORS）</b> —— 开了就直接用，没开就得让它带上响应头。';
      }
    }

    var note = $('#s-transport-note');
    if (note) {
      if (!official) {
        note.innerHTML = '<b>中转 api：</b>打你自己填的中转地址，用那个中转给你的令牌。<br>'
          + '这条路不需要官方开放跨域，你的中转自己开了就行。';
      } else if (af) {
        note.innerHTML = '<b>官网 api：</b>地址是官方端点，Key 用你自己的官方 API Key。<br>'
          + '请求现在经<b>「作者的中转服务器」</b>发出 —— 官方不给跨域头，浏览器直打会被拦。';
      } else {
        note.innerHTML = '<b>官网 api：</b>地址是官方端点，Key 用你自己的官方 API Key。<br>'
          + '官方不给跨域头，所以浏览器直打会被拦 —— 要真正跑通，把下面的走法切到'
          + '<b>「作者的中转服务器」</b>。';
      }
    }

    var ab = $('#s-tts-authstyle');
    if (ab) ab.textContent = AUTH_LABEL[S.ttsAuth] || 'Bearer';

    var h = $('#vs-ping-hint');
    if (h) {
      var base;
      if (af) {
        base = '<b>检查通道</b>只打一次 <code>/tts/health</code>（不带 Key、不带文本），'
          + '它只答"中转在不在线"，<b>答不了"能不能出声"</b>。';
      } else if (official) {
        base = '<b style="color:var(--amber)">令牌会随聊天变量存进这个聊天文件</b>，也会明文出现在页面上。'
          + '另外官方端点一定被浏览器跨域拦下 —— 切到「作者的中转服务器」就能跑通。';
      } else {
        base = '<b style="color:var(--amber)">令牌会随聊天变量存进这个聊天文件</b>，也会明文出现在页面上。'
          + '连通不通取决于<b>你的中转有没有开跨域</b>（被拦时错误里写 Failed to fetch）。';
      }
      h.innerHTML = base
        + '<br>要确认账号额度、模型、音色都可用，点上面的「<b>能不能真的出声</b>」—— '
        + '它会真合成一条极短音频（按官方计费，通常不到一分钱）；这一颗检查不产生合成费用。';
    }
  }

  function bindVoice() {
    var v = $('#s-voice'); if (v) v.textContent = VOICE_LABEL[S.voice] || '关';
    fillModelOptions();   // 先把候选与说明铺好，再写值，免得输入框的值被后设置的列表带偏
    var m = $('#s-tts-model'); if (m) m.value = S.ttsModel || '';
    fillVoiceSelect(1);
    fillVoiceSelect(2);
    var vt2 = $('#s-voice-two');
    var two = !!S.ttsVoiceTease || !!S.voiceTwo;   // 开了开关还没填 ID 的也算开
    if (vt2) vt2.classList.toggle('on', two);
    var v2b = $('#s-voice-2-box');
    if (v2b) v2b.style.display = two ? 'block' : 'none';
    var tg = $('#s-tts-target'); if (tg) tg.value = S.ttsTarget || '';
    var ky = $('#s-tts-key'); if (ky) ky.value = S.ttsKey || '';
    var mh = $('#s-tts-modelhdr'); if (mh) mh.value = S.ttsModelHdr || 'model';
    var rf = $('#s-tts-reffield'); if (rf) rf.value = S.ttsRefField || 'reference_id';
    var ex = $('#s-tts-extra'); if (ex) ex.value = S.ttsExtraHdrs || '';
    var la = $('#s-tts-latency'); if (la) la.textContent = S.ttsLatency || 'low';
    var nm = $('#s-tts-nomodel'); if (nm) nm.classList.toggle('on', !!S.ttsNoModelHdr);
    var fm = $('#s-tts-format'); if (fm) fm.textContent = S.ttsFormat;
    var vol = $('#s-voicevol'); if (vol) vol.value = S.voiceVol;
    var spd = $('#s-tts-speed'); if (spd) spd.value = S.ttsSpeed;
    var ai = $('#s-voiceai'); if (ai) ai.textContent = S.voiceAI ? 'AI 生成' : '台词库';
    var swa = $('#s-voiceauto'); if (swa) swa.classList.toggle('on', S.voiceAuto);
    var sww = $('#s-voicewarm'); if (sww) sww.classList.toggle('on', S.voiceWarm);
    paintAutoWarn();
    paintTransport();
    paintPlatform();
    paintVoice();
    paintBook();      // 音色簿：有存过的才显示，记得跟着读档一起刷
  }

  /* 自动播放的警示：三处一起亮 —— 两个开关的脉冲、语音页的警示条、设置页入口的红字。
     它是唯一会"在没人点的情况下出声"的开关，所以开着就得看得见。 */
  function paintAutoWarn() {
    var on = !!S.voiceAuto;
    var w1 = $('#vs-auto-warn');
    if (w1) w1.hidden = !on;
    var w2 = $('#c-voice-auto-warn');
    if (w2) {
      w2.hidden = !on;
      if (on) {
        w2.innerHTML = '<b>自动播放开着</b> —— 新反应会直接出声。'
          + '在外面先关掉它（语音设置页 →「自动播放」）。';
      }
    }
    var sws = ROOT.querySelectorAll('#s-voiceauto');
    for (var i = 0; i < sws.length; i++) {
      sws[i].classList.toggle('danger', on);
      sws[i].classList.toggle('on', on);
    }
    // 设置页的快捷开关：文字与脉冲都跟着状态走，一眼看出现在是不是"会自己出声"
    var qb = $('#c-voiceauto-quick');
    if (qb) {
      qb.textContent = on ? '自动播放 · 开' : '自动播放 · 关';
      qb.classList.toggle('danger-chip', on);
    }
  }

  /* 设置页那个快捷开关：不必进语音页就能关掉它 —— 社死只需一秒的反应时间 */
  onEl('#c-voiceauto-quick', 'click', function () {
    S.voiceAuto = !S.voiceAuto;
    persist();
    paintAutoWarn();
    toast(S.voiceAuto
      ? '自动播放已开：新反应会直接出声，注意场合'
      : '自动播放已关：只有你点「语音播放」才会出声', 3000);
  });

  function onEl(sel, evt, fn) {
    var e = $(sel);
    if (e) e.addEventListener(evt, fn);
  }

  function warmVoice() {
    if (!VOC.voiceOn()) { toast('先打开 TTS 语音'); return; }
    var kind = voiceKind();
    var list = [];
    for (var s = 1; s <= 5; s++) list.push(fillName(libPick(kind, s)));
    var h = $('#vs-try-hint');
    if (h) h.textContent = '正在预热 ' + list.length + ' 条…';
    VOC.warm(list).then(function (n) {
      if (h) h.textContent = '预热完成：' + n + ' 条已缓存，之后播这些不再联网。';
      toast('音集预热完成：' + n + ' 条');
    });
  }

  // 语音开关：四档循环（关 → TTS 语音 → 两个都要 → 振动音，见 VOICE_IDS）
  onEl('#s-voice', 'click', function () {
    var i = VOICE_IDS.indexOf(S.voice);
    S.voice = VOICE_IDS[(i + 1) % VOICE_IDS.length];
    bindVoice();
    persist();
    if (S.voice === 'off') { VOC.stopAll(); toast('语音已关闭'); return; }
    VOC.resume();
    if (VOC.buzzMode() && S.on) VOC.tick(S.env);
    if (S.voice === 'buzz') {
      toast('振动音是未测试项：只在装置运行时出声，慎用', 3000);
    } else {
      toast('语音：' + VOICE_LABEL[S.voice]);
      if (!S.ttsTarget) toast('还要填「合成地址」才能真正念出来', 3000);
      else if (S.voiceWarm) warmVoice();
    }
  });

  onEl('#c-voice-warm', 'click', warmVoice);

  /* =========================================================
   * 试听选择器：从台词库里挑一句来试音色
   *
   * 三级联动：分类 → 档位 → 句子。改音色或语速之后用它对比最省事，
   * 不必等装置跑起来。里面显示的文本就是真正会送去合成的那一串（含情绪标记）。
   * ======================================================= */
  function libSelGet() {
    var k = $('#s-voice-kind');
    var s = $('#s-voice-stage');
    var l = $('#s-voice-line');
    return {
      kind: (k && k.value) || 'moan',
      stage: parseInt((s && s.value) || '3', 10) || 3,
      idx: parseInt((l && l.value) || '0', 10) || 0
    };
  }

  function paintLibStage() {
    var sel = $('#s-voice-stage');
    if (!sel) return;
    var cur = libSelGet();
    var kind = cur.kind;
    sel.innerHTML = '';
    if (kind === 'beg') {
      var o = document.createElement('option');
      o.value = '1';
      o.textContent = '不分档（求停时的一句话）';
      sel.appendChild(o);
      sel.disabled = true;
    } else {
      sel.disabled = false;
      for (var s = 1; s <= 5; s++) {
        var op = document.createElement('option');
        op.value = String(s);
        op.textContent = '第 ' + s + ' 档 · ' + STAGES[s - 1].name;
        sel.appendChild(op);
      }
      sel.value = String(clamp(cur.stage, 1, 5));
    }
    var note = $('#s-voice-stage-note');
    if (note) {
      note.textContent = (kind === 'beg')
        ? '这一支是玩家请求停下时 TA 的应答，与强度档位无关。'
        : '档位决定用哪一组句子（越往后越失控）。';
    }
  }

  function paintLibLines() {
    var sel = $('#s-voice-line');
    if (!sel) return;
    var cur = libSelGet();
    var n = (cur.kind === 'beg') ? VOICE_LIB.beg.length : libStagePool(cur.kind, cur.stage).length;
    if (!n) n = 1;
    sel.innerHTML = '';
    for (var i = 0; i < n; i++) {
      var o = document.createElement('option');
      o.value = String(i);
      o.textContent = libLineAt(cur.kind, cur.stage, i);
      sel.appendChild(o);
    }
    sel.value = String(clamp(cur.idx, 0, n - 1));
    paintLibNote();
  }

  var VoiceKindCount = '';
  function paintLibNote() {
    var cur = libSelGet();
    var line = libLineAt(cur.kind, cur.stage, cur.idx);
    var tag = $('#vs-text-tag');
    if (tag) tag.textContent = VoiceKindCount;
    var note = $('#vs-preview-note');
    if (note) {
      note.innerHTML = '这一句：<b style="color:var(--cyan)">' + esc4(line) + '</b>'
        + '<br>台词库共 ' + VoiceKindCount + '（呻吟 17 · 调教 14 · 自己玩 10 · 求停 4）。'
        + '情绪标记是每条随机取的，换一句可能配到别的标记。';
    }
  }

  (function initLibPicker() {
    var k = $('#s-voice-kind');
    if (!k) return;
    var total = 0;
    ['moan', 'tease', 'self'].forEach(function (kk) {
      for (var s = 1; s <= 5; s++) total += libStagePool(kk, s).length;
    });
    total += VOICE_LIB.beg.length;
    VoiceKindCount = total + ' 句';
    k.innerHTML = '';
    var order = ['moan', 'tease', 'self', 'beg'];
    order.forEach(function (kk) {
      var o = document.createElement('option');
      o.value = kk;
      var cnt = (kk === 'beg') ? VOICE_LIB.beg.length
        : (function () { var n = 0; for (var s = 1; s <= 5; s++) n += libStagePool(kk, s).length; return n; })();
      o.textContent = (VOICE_KIND_LABEL[kk] || kk) + ' · ' + cnt + ' 句';
      k.appendChild(o);
    });
    k.value = voiceKind();          // 默认跟着当前档位走，跳过去就能试当下这一档
    if (libSelGet().kind !== k.value) k.value = 'moan';
    paintLibStage();
    paintLibLines();
  })();

  onEl('#s-voice-kind', 'change', function () { paintLibStage(); paintLibLines(); });
  onEl('#s-voice-stage', 'change', function () { paintLibLines(); });
  onEl('#s-voice-line', 'change', function () { paintLibNote(); });

  function previewLibLine(advance) {
    var cur = libSelGet();
    if (advance) {
      var n = (cur.kind === 'beg') ? VOICE_LIB.beg.length : libStagePool(cur.kind, cur.stage).length;
      cur.idx = (cur.idx + 1) % Math.max(1, n);
      var sel = $('#s-voice-line');
      if (sel) sel.value = String(cur.idx);
      paintLibNote();
    }
    var line = libLineAt(cur.kind, cur.stage, cur.idx);
    VOC.resume();
    if (VOC.buzzMode() && S.on) VOC.tick(S.env);
    if (VOC.voiceOn()) {
      if (!S.ttsTarget) { toast('先填「合成地址」'); return; }
      if (S.ttsTransport === 'direct' && S.ttsAuth !== 'none' && !S.ttsKey) { toast('直连模式还要填令牌'); return; }
      var v = (cur.kind === 'tease' && S.ttsVoiceTease) ? S.ttsVoiceTease : S.ttsVoice;
      VOC.say(line, { vol: S.voiceVol / 100, voice: v });
      toast('试听：' + line.slice(0, 24));
    } else {
      toast('语音开关还没开（要在 TTS 语音或两个都要）');
    }
  }
  onEl('#c-preview-line', 'click', function () { previewLibLine(false); });
  onEl('#c-preview-next', 'click', function () { previewLibLine(true); });

  /* 连通性检查：空文本探一次。它不产生合成计费，却能把四种情况分开 ——
     跨域被拦 / 鉴权失败 / 路由不存在 / 只是参数不合法（那说明前两关都过了）。
     两种传输方式都走这一条，只是打出去的地址不同。 */
  function voicePing() {
    var h = $('#vs-ping-hint');
    function say(msg, cls) {
      if (h) h.textContent = msg;
      VOC.addLog('[检查] ' + msg, cls || (/连不上|拦下|失败|不对|404|401|403|超时|没填/.test(msg) ? 'err'
        : (/过了|通了|可以试听/.test(msg) ? 'ok' : 'hi')));
    }
    /* 经作者中转时，检查走的是一个专门的健康接口：GET /tts/health，
       不带 Key、不带文本、不碰上游 —— 服务器不为它垫付任何合成费用。
       它只说明中转活着，不能当成"你的 Key 与音色可用"。 */
    var direct = !forwarding();
    var af = usingAF() ? afURL(S.ttsTarget) : '';
    var chan = af ? '经作者中转' : '直连';
    VOC.addLog('=== 连通性检查开始（' + chan + '）===', 'hi');
    if (!S.ttsTarget) { say('还没填「合成地址」。'); toast('先填合成地址'); return Promise.resolve(false); }
    if (!direct && isOfficial() && !afReady()) {
      say('这个官方地址本脚本中转不认 —— 它只转 Fish 官方与 MiniMax 国际站两个端点。'
        + '请把地址改回官方端点，或切到「中转 api」填你自己的中转地址。');
      toast('作者中转不支持这个地址');
      return Promise.resolve(false);
    }

    var url = af ? afHealth() : S.ttsTarget;
    if (S.ttsAuth !== 'none' && !S.ttsKey) {
      say(af ? '经作者中转要用你自己的官方 API Key，先填「官方 API Key」。'
        : '要填令牌（或把鉴权改成「不带」）。');
      toast('缺令牌');
      return Promise.resolve(false);
    }

    say('正在检查（' + chan + '）…', 'hi');
    VOC.addLog(af ? ('打 ' + url + '（健康接口，不带 Key、不带文本）')
      : ('打 ' + url + '（空文本，不产生合成计费）'), 'hi');
    var ctl = (typeof AbortController !== 'undefined') ? new AbortController() : null;
    var timer = ctl ? setTimeout(function () { ctl.abort(); }, 12000) : null;
    var t0 = Date.now();
    var headers = { 'Content-Type': 'application/json' };
    // 跟真正合成时（cfgNow）同一条规则：OpenAI / MiniMax 一律不带模型头。头不一样，跨域预检的结果就对不上，检查会报反
    var noMH = (S.ttsPlatform === 'openai' || S.ttsPlatform === 'minimax') ? true : !!S.ttsNoModelHdr;
    if (!af) {
      if (S.ttsAuth === 'x-api-key' && S.ttsKey) headers['x-api-key'] = S.ttsKey;
      else if (S.ttsAuth === 'raw' && S.ttsKey) headers['Authorization'] = S.ttsKey;
      else if (S.ttsAuth !== 'none' && S.ttsKey) headers['Authorization'] = 'Bearer ' + S.ttsKey;
      if (S.ttsModel && !noMH) headers[S.ttsModelHdr || 'model'] = S.ttsModel;
      var exRaw = String(S.ttsExtraHdrs || '').trim();
      if (exRaw) { try { var ex = JSON.parse(exRaw) || {}; Object.keys(ex).forEach(function (k) { headers[k] = String(ex[k]); }); } catch (e) { /* 忽略 */ } }
    }

    var req = af
      ? fetch(url, { method: 'GET', credentials: 'omit', referrerPolicy: 'no-referrer', signal: ctl ? ctl.signal : undefined })
      : fetch(url, {
        method: 'POST', headers: headers,
        body: JSON.stringify({ text: '', format: S.ttsFormat }),
        signal: ctl ? ctl.signal : undefined,
        credentials: 'omit', referrerPolicy: 'no-referrer'
      });
    return req.then(function (r) {
      if (timer) clearTimeout(timer);
      var ms = Date.now() - t0;
      var ct = r.headers.get('content-type') || '';
      if (af) {
        // 只有 GET 200 且 ok:true 才算中转活着
        return r.text().then(function (tx) {
          var j = null; try { j = JSON.parse(tx); } catch (e) { /* 非 JSON 就走下面的分支 */ }
          if (r.ok && j && j.ok) {
            say('本脚本中转在线（' + r.status + ' · ' + ms + 'ms · 当前处理中 ' + (j.active | 0) + '）—— '
              + '这只能说明中转活着，能不能出声还得点「试听一句」用真实 Key 验一次。', 'ok');
            return true;
          }
          if (r.status === 429) {
            say('中转正忙（429）—— 同时合成的路数满了，等几秒再试，别连着重发。', 'err');
          } else {
            say('本脚本中转回了 ' + r.status + (tx ? '：' + String(tx).slice(0, 120) : ''), 'err');
          }
          return false;
        }, function () { return false; });
      }
      if (r.ok && ct.indexOf('json') < 0) {
        say('通到上游了（' + r.status + ' · ' + ms + 'ms）—— 可以直接试听。', 'ok');
        return true;
      } else if (r.status === 400 || r.status === 422) {
        // 参数不合法 = 通道与密钥都过了，只是空文本被拒。这正是我们要看到的。
        say('通道与鉴权都过了（上游回 ' + r.status + '，因为空文本被拒）—— 可以试听。', 'ok');
        return true;
      } else if (r.status === 401 || r.status === 403) {
        say(direct
          ? '鉴权失败（' + r.status + '）：检查令牌与「鉴权方式」是不是和中转文档一致。'
          : '路由通了，但令牌不对（' + r.status + '）。检查「官方 API Key」（它要用你自己的官方 Key）。', 'err');
      } else if (r.status === 404) {
        say('404：合成地址的路径不对。检查中转文档给的确是 /v1/tts 还是别的路径。', 'err');
      } else {
        say('上游回 ' + r.status + '：看运行日志里那条 REST 的响应内容', 'err');
      }
      return r.text().then(function (tx) {
        if (tx && tx.length && /error|message|ok|detail/i.test(tx)) {
          VOC.addLog('响应体：' + String(tx).slice(0, 220), 'err');
        }
        return false;
      }, function () { return false; });
    }).catch(function (e) {
      if (timer) clearTimeout(timer);
      var msg = (e && e.name === 'AbortError') ? '超时（12 秒）' : ((e && e.message) || String(e));
      if (/Failed to fetch|NetworkError|Load failed/i.test(msg)) {
        say(af ? '连不上作者中转 —— 检查一下网络，或换成「浏览器直打」再试。'
          : (direct && isOfficial()
            ? '直连被拦下了（官方端点不给跨域头）—— 把走法切到「作者的中转服务器」就能跑通。'
            : '连不上这个地址：要么地址写错了，要么对方没开跨域（CORS）。'), 'err');
      } else {
        say('检查失败：' + msg, 'err');
      }
      return false;
    });
  }
  onEl('#c-voice-ping', 'click', voicePing);

  /* 「对比检查通道」「能不能真的出声」两颗按钮已按要求移除；通道检查只留上面那一颗。 */
  onEl('#c-voice-test', 'click', function () {
    if (S.voice === 'off') { toast('先把语音开关打开（至少要 TTS 语音）'); return; }
    VOC.resume();
    if (VOC.buzzMode() && S.on) VOC.tick(S.env);
    if (VOC.voiceOn()) {
      if (!S.ttsTarget) { toast('先填「合成地址」'); return; }
      var pick = voiceFor('', S.stage);
      var h = $('#vs-try-hint');
      if (h) {
        h.textContent = '测试台词：' + pick.text + '（'
          + (pick.kind === 'tease' ? '调教对白' : (pick.kind === 'self' ? '自己玩 · 气音' : '呻吟')) + '）';
      }
      VOC.say(pick.text, { vol: S.voiceVol / 100, voice: pick.voice });
    } else {
      toast('振动音已开：启动装置就能听到');
    }
  });

  onEl('#c-voice-clear', 'click', function () {
    VOC.clearCache().then(function () { toast('语音缓存已清空'); });
  });

  // 设置页那条只是入口，真正调参数在语音页
  onEl('#c-goto-voice', 'click', function () { go('voice'); });

  /* ---- 运行日志：复制 / 清空 ---- */
  onEl('#c-log-clear', 'click', function () {
    VOC.clearLog();
    toast('日志已清空');
  });
  onEl('#c-log-copy', 'click', function () {
    var t = VOC.logText();
    if (!t) { toast('日志是空的'); return; }
    copyToClipboard(t, '日志已复制（' + VOC.logCount() + ' 条）');
  });

  /* =========================================================
   * 合成记录：分页浏览 + 单条下载 + 打包下载 + 清空
   *
   * 数据源就是音频缓存本身，所以"清空记录"和「清空语音缓存」是同一件事 ——
   * 界面上两处按钮文案写清这一点，免得以为是两份数据。
   * ======================================================= */
  var AUD_PAGE = 0, AUD_PER = 6;

  function fmtClock(ms) {
    var d = new Date(ms || 0);
    return pad2(d.getMonth() + 1) + '-' + pad2(d.getDate()) + ' ' + pad2(d.getHours()) + ':' + pad2(d.getMinutes());
  }
  function fmtBytes(n) {
    n = n || 0;
    if (n < 1024) return n + ' B';
    if (n < 1024 * 1024) return (n / 1024).toFixed(1) + ' KB';
    return (n / 1048576).toFixed(2) + ' MB';
  }
  /* 用的就是合成时那份 meta —— 显示的和实际发出去的一致，不另存一份 */
  function recLine(rec) {
    return String((rec.meta && rec.meta.text) || '（无文本）').replace(/\s+/g, ' ').trim();
  }
  function recVoice(rec) {
    var v = (rec.meta && rec.meta.voice) || '';
    return v ? ('音色 ' + v.slice(0, 12)) : '默认音色';
  }

  function paintAudioList() {
    if (!$('#vs-list')) return;
    VOC.listAll().then(function (all) {
      var total = all.length;
      var pages = Math.max(1, Math.ceil(total / AUD_PER));
      if (AUD_PAGE > pages - 1) AUD_PAGE = pages - 1;
      if (AUD_PAGE < 0) AUD_PAGE = 0;

      var cnt = $('#vs-list-count');
      if (cnt) cnt.textContent = total ? (total + ' 条') : '';
      var info = $('#vs-page-info');
      if (info) info.textContent = total ? ('共 ' + total + ' 条 · 第 ' + (AUD_PAGE + 1) + ' / ' + pages + ' 页') : '共 0 条';
      var prev = $('#c-page-prev'), next = $('#c-page-next');
      // 空列表时两个都禁掉：页数按 max(1,...) 算出来是 1，光比下标会误判成可翻
      if (prev) prev.disabled = (total === 0 || AUD_PAGE <= 0);
      if (next) next.disabled = (total === 0 || AUD_PAGE >= pages - 1);

      var box = $('#vs-list');
      if (!box) return;
      if (!total) {
        box.innerHTML = '<div class="lgdim" style="padding:10px 0">（还没有合成记录）</div>';
        return;
      }
      box.innerHTML = '';
      all.slice(AUD_PAGE * AUD_PER, AUD_PAGE * AUD_PER + AUD_PER).forEach(function (rec) {
        var row = document.createElement('div');
        row.className = 'recl';
        var m = document.createElement('div');
        m.className = 'm';
        var t = document.createElement('div');
        t.className = 't';
        t.textContent = recLine(rec);
        var s = document.createElement('div');
        s.className = 's';
        s.textContent = fmtClock(rec.at) + ' · ' + recVoice(rec) + ' · '
          + fmtBytes(rec.blob ? rec.blob.size : 0);
        m.appendChild(t); m.appendChild(s);

        var pb = document.createElement('button');
        pb.type = 'button';
        pb.className = 'b';
        pb.textContent = '播';
        pb.addEventListener('click', function () {
          if (!rec.blob) { toast('这条音频已不在本地'); return; }
          VOC.resume();
          VOC.play(rec.blob, { vol: S.voiceVol / 100, voice: (rec.meta && rec.meta.voice) || S.ttsVoice });
          VOC.addLog('回放记录：' + recLine(rec).slice(0, 30), 'hi');
        });

        var db = document.createElement('button');
        db.type = 'button';
        db.className = 'b';
        db.textContent = '存';
        db.addEventListener('click', function () {
          saveOne(rec);
        });

        row.appendChild(m); row.appendChild(pb); row.appendChild(db);
        box.appendChild(row);
      });
    });
  }

  /* 单条落盘 */
  function saveOne(rec) {
    if (!rec.blob) { toast('这条音频已不在本地'); return; }
    try {
      var url = URL.createObjectURL(rec.blob);
      var a = document.createElement('a');
      a.href = url;
      a.download = 'toylink-' + safeName(recLine(rec).slice(0, 20)) + '-'
        + (rec.id || 'x') + '.' + ((rec.meta && rec.meta.format) || S.ttsFormat || 'mp3');
      document.body.appendChild(a);
      a.click();
      a.remove();
      setTimeout(function () { URL.revokeObjectURL(url); }, 8000);
      toast('已保存：' + a.download);
    } catch (e) {
      toast('保存失败：' + ((e && e.message) || e));
    }
  }

  /* 全部落盘：在浏览器里自己打一个 zip（stored，不压缩） */
  function packAll() {
    VOC.listAll().then(function (all) {
      if (!all.length) { toast('还没有可打包的音频'); return; }
      VOC.addLog('开始打包 ' + all.length + ' 条音频…', 'hi');
      var items = [];
      var chain = Promise.resolve();
      all.forEach(function (rec) {
        chain = chain.then(function () {
          return rec.blob.arrayBuffer().then(function (buf) {
            items.push({ name: safeName(recLine(rec).slice(0, 20)) + '-' + rec.id + '.' + ((rec.meta && rec.meta.format) || 'mp3'), data: new Uint8Array(buf) });
          }, function () { /* 单条读失败就跳过 */ });
        });
      });
      return chain.then(function () {
        if (!items.length) { toast('打包失败：没有可读的音频'); return; }
        var bytes = zipBuild(items);
        var blob = new Blob([bytes], { type: 'application/zip' });
        var url = URL.createObjectURL(blob);
        var a = document.createElement('a');
        a.href = url;
        a.download = 'toylink-voice-' + all.length + '.zip';
        document.body.appendChild(a);
        a.click();
        a.remove();
        setTimeout(function () { URL.revokeObjectURL(url); }, 12000);
        VOC.addLog('打包完成：' + items.length + ' 个文件，' + fmtBytes(bytes.length), 'ok');
        toast('已打包 ' + items.length + ' 条（' + fmtBytes(bytes.length) + '）', 3200);
      });
    });
  }

