  // 输入框：边打边存，切走再确认一次，避免手机上输入法不触发 change
  function bindText(sel, key, isNum) {
    var el = $(sel);
    if (!el) return;
    var apply = function (ev) {
      if (isNum) {
        var n = parseFloat(el.value);
        S[key] = isFinite(n) ? clamp(n, key === 'ttsSpeed' ? 0.5 : 0, key === 'ttsSpeed' ? 1.5 : 100) : S[key];
        // 打字途中不回写：敲「0」会被立刻夹成 0.5，「0.8」就永远敲不进去。离开输入框时再规整显示
        if (!ev || ev.type !== 'input') el.value = S[key];
      } else {
        S[key] = String(el.value || '').trim();
      }
      persistSoon(ev);
      paintVoice();
    };
    el.addEventListener('input', apply);
    el.addEventListener('change', apply);
    el.addEventListener('blur', apply);
  }
