  /* =========================================================
   * 10. 设置持久化 —— 分两处存，因为这两类东西的生命周期根本不同
   *
   *  A. 语音接口配置（平台 / 地址 / 令牌 / 音色 / 模型…）
   *     这是"我这台机器怎么连中转"，与玩哪个聊天无关。
   *     存全局变量 + 本机 localStorage —— 新建对话、换角色卡、换聊天都还在。
   *
   *  B. 剧情会话状态（作用对象、装置形态、模式、频率、强度…）
   *     这些和"这一局怎么玩"绑定，应当随聊天各自独立。
   *     仍存聊天变量，新建对话回到默认值是正确的。
   *
   * 早先全塞进聊天变量里，结果是每开一个新对话都要重填地址与令牌 —— 那是错的。
   * ======================================================= */
  var LS_KEY = 'toylink_cfg_v1';
  var CHAT_TO_GLOBAL = {
    toy_cfg_voice: 'toy_out_voice',
    toy_cfg_voicevol: 'toy_out_vol',
    toy_cfg_voiceauto: 'toy_out_auto',
    toy_cfg_voiceai: 'toy_out_ai',
    toy_cfg_voicewarm: 'toy_out_warm',
    toy_cfg_warmset: 'toy_out_warmset',
    toy_cfg_haptap: 'toy_out_haptap',
    toy_cfg_hapfol: 'toy_out_hapfol',
    toy_cfg_audio: 'toy_out_audio',
    toy_cfg_proxy: 'toy_tts_proxy',
    toy_cfg_transport: 'toy_tts_transport',
    toy_cfg_ttskey: 'toy_tts_key',
    toy_cfg_modelhdr: 'toy_tts_modelhdr',
    toy_cfg_reffield: 'toy_tts_reffield',
    toy_cfg_nomodel: 'toy_tts_nomodel',
    toy_cfg_extra: 'toy_tts_extra',
    toy_cfg_latency: 'toy_tts_latency',
    toy_cfg_platform: 'toy_tts_platform',
    toy_cfg_langboost: 'toy_tts_langboost',
    toy_cfg_target_url: 'toy_tts_target',
    toy_cfg_ttsvoice: 'toy_tts_voice',
    toy_cfg_ttsvoicet: 'toy_tts_voicet',
    toy_cfg_ttsmodel: 'toy_tts_model',
    toy_cfg_ttsformat: 'toy_tts_format',
    toy_cfg_ttsspeed: 'toy_tts_speed',
    toy_cfg_ttsauth: 'toy_tts_auth'
  };
  var GLOBAL_SEEN = {};   // restoreGlobal 读到了哪些全局键（有全局值的，聊天里的旧值就不再采用）

  function lsSave(obj) {
    try { localStorage.setItem(LS_KEY, JSON.stringify(obj)); } catch (e) { /* 无痕模式等情形忽略 */ }
  }
  function lsLoad() {
    try { return JSON.parse(localStorage.getItem(LS_KEY) || 'null') || {}; } catch (e) { return {}; }
  }

  /* 只写"是否亲手碰过预热开关"这一个标记，两种存储都写一份 */
  function persistSettingsFlags() {
    var ls = lsLoad();
    ls.toy_out_warmset = !!S.warmTouched;
    lsSave(ls);
    BRIDGE.setVars({ toy_out_warmset: !!S.warmTouched }, 'global');
  }

  /* A 类：与聊天无关的接口配置 */
  function persistGlobal() {
    var g = {
      toy_tts_platform: S.ttsPlatform,
      toy_tts_target: S.ttsTarget,
      // 切到「官网直连」时把原中转地址记下来，切回「中转」要还给用户
      toy_tts_relay_target: S.relaySavedTarget,
      toy_tts_key: S.ttsKey,
      toy_tts_transport: S.ttsTransport,
      toy_tts_auth: S.ttsAuth,
      toy_tts_voice: S.ttsVoice,
      toy_tts_voicet: S.ttsVoiceTease,
      // 音色簿里当前选中哪一条（名字）。音色值本身会有"改了没存"的中间态，
      // 这两个选择跟踪的是"上次套用的是哪条"，所以单独存。
      toy_voicesel1: S.voiceSel1,
      toy_voicesel2: S.voiceSel2,
      toy_voice_two: !!S.voiceTwo,
      toy_tts_model: S.ttsModel,
      toy_tts_format: S.ttsFormat,
      toy_tts_speed: S.ttsSpeed,
      toy_tts_modelhdr: S.ttsModelHdr,
      toy_tts_reffield: S.ttsRefField,
      toy_tts_nomodel: S.ttsNoModelHdr,
      toy_tts_extra: S.ttsExtraHdrs,
      toy_tts_latency: S.ttsLatency,
      toy_tts_langboost: S.ttsLangBoost,
      // 音色簿跟全局走（它不含令牌，且"我存过哪几个音色"是跨对话的偏好）
      toy_voicebook: S.voiceBook,
      // 输出开关也算偏好：换聊天时不该被重置
      toy_out_vol: S.voiceVol,
      toy_out_auto: S.voiceAuto,
      toy_out_warm: S.voiceWarm,
      toy_out_warmset: !!S.warmTouched,   // 一起写进来：lsSave 是整份覆盖，漏了它会把预热标记冲掉
      toy_out_ai: S.voiceAI,
      toy_out_haptap: S.hapticTap,
      toy_out_hapfol: S.hapticFollow,
      toy_out_audio: S.audio,
      toy_out_voice: S.voice
    };
    lsSave(g);                       // 本机兜底：酒馆没就绪、或全局变量不可用时也记得住
    BRIDGE.setVars(g, 'global');     // 全局变量：跟着用户存档走
  }

  /* B 类 + 兼容：聊天级状态照旧写聊天变量 */
  function persist() {
    persistGlobal();
    if (!BRIDGE.ready) return;
    var blob = {
      toy_cfg_drive: S.drive,
      toy_cfg_inject: S.inject,
      toy_cfg_cd: S.cd,
      toy_cfg_gain: S.gain,
      toy_cfg_reset: S.resetOnPeak,
      toy_cfg_hold: S.hold,
      toy_cfg_dashrate: S.dashRate,
      toy_cfg_recfreq: S.recFreq,
      toy_cfg_freeze: S.freezeOnGen,
      toy_cfg_managewb: S.manageWb,
      toy_cfg_sendmode: S.sendMode,
      toy_cfg_target: S.target,
      toy_cfg_holder: S.holder,
      toy_cfg_dev: S.dev,
      toy_cfg_body: S.body,
      toy_cfg_explicit: S.explicit,
      toy_cfg_begdocile: S.begDocile,
      toy_cfg_auto: S.auto,
      // 首次运行补写"用户开始自己管这个开关"的版本号；一旦写下就不再改，
      // 否则老用户下次打开又会被判成"没碰过"
      toy_cfg_autoset: (AUTO_SET_STAMP || S.autoTouched) ? (AUTO_SET_STAMP || VERSION) : '',
      toy_cfg_mode: S.mode,
      toy_cfg_freq: S.freq,
      toy_cfg_pow: S.pow
    };
    /* 接口配置和输出偏好已经搬到全局（persistGlobal）。聊天里不再存它们，
       并且把旧版写进来的值清成 null：令牌不该跟着每个聊天文件走（导出/分享聊天会一起带出去），
       旧聊天里的旧值也不该在切回来时盖掉全局里的新值。 */
    Object.keys(CHAT_TO_GLOBAL).forEach(function (k) { blob[k] = null; });
    BRIDGE.setVars(blob, 'chat');
  }

  /* 恢复顺序很关键：全局配置 → 聊天状态 →（聊天里若也存过接口配置，说明是旧存档，用它兜一次）
     这样"新对话里接口配置还在"，而"旧存档里的配置也不会丢"。 */
  function restoreGlobal() {
    var fromLs = lsLoad();
    var fromGlobal = BRIDGE.ready ? (BRIDGE.getVars('global') || {}) : {};
    // 全局变量优先（它跟着用户存档走），localStorage 兜底
    var g = {};
    Object.keys(fromLs).forEach(function (k) { g[k] = fromLs[k]; });
    Object.keys(fromGlobal).forEach(function (k) { if (fromGlobal[k] != null) g[k] = fromGlobal[k]; });
    GLOBAL_SEEN = {};
    Object.keys(g).forEach(function (k) { if (g[k] != null) GLOBAL_SEEN[k] = 1; });

    if (typeof g.toy_tts_platform === 'string' && PLATFORMS[g.toy_tts_platform]) S.ttsPlatform = g.toy_tts_platform;
    if (typeof g.toy_tts_target === 'string') S.ttsTarget = g.toy_tts_target;
    if (typeof g.toy_tts_relay_target === 'string') S.relaySavedTarget = g.toy_tts_relay_target;
    /* 老存档里没有 relaySavedTarget：如果当前地址不是官网，就把它当作中转地址记下来 ——
       否则用户第一次点「官网 api」会把自己填的中转地址弄丢。 */
    if (!S.relaySavedTarget && S.ttsTarget && !isOfficial()) S.relaySavedTarget = S.ttsTarget;
    /* 从没填过地址的（新装用户）补上官方的默认端点。
       配合下面通道的默认值 af，新装用户打开语音设置看到的就是一套能直接填 Key 用起来的配置：
       平台 Fish、地址官方端点、走作者的中转服务器。不补的话默认通道虽在 af，
       地址却是空的，afReady() 为假 —— 界面会显示"这个地址作者中转不认"，等于默认状态是坏的。 */
    if (!String(S.ttsTarget || '').trim() && OFFICIAL_URL[S.ttsPlatform]) {
      S.ttsTarget = OFFICIAL_URL[S.ttsPlatform];
    }
    if (typeof g.toy_tts_key === 'string') S.ttsKey = g.toy_tts_key;
    if (typeof g.toy_tts_proxy === 'string') S.ttsProxy = g.toy_tts_proxy;   // 已废弃键：读进来只为兼容老存档，不再使用
    /* 通道：只有显式存过才覆盖默认值（默认是 af＝作者的中转服务器）。
       老存档里的：
         'relay' —— 当年的"经本机转发"，那条路已经拆掉，折算成 'direct'：
                    宁可让用户重新点一次开关，也不能把他的 Key 与台词悄悄送到别人的服务器上；
         'direct' —— 保持直连，那是他自己选的。
       反过来说，键根本不存在的（从没配过 TTS 的人）才留在默认的 af 上。 */
    if (g.toy_tts_transport === 'af') S.ttsTransport = 'af';
    else if (g.toy_tts_transport === 'direct' || g.toy_tts_transport === 'relay') S.ttsTransport = 'direct';
    if (typeof g.toy_tts_auth === 'string') S.ttsAuth = g.toy_tts_auth;
    if (typeof g.toy_tts_voice === 'string') S.ttsVoice = g.toy_tts_voice;
    if (typeof g.toy_tts_voicet === 'string') S.ttsVoiceTease = g.toy_tts_voicet;
    if (typeof g.toy_voicesel1 === 'string') S.voiceSel1 = g.toy_voicesel1;
    if (typeof g.toy_voicesel2 === 'string') S.voiceSel2 = g.toy_voicesel2;
    if (typeof g.toy_voice_two === 'boolean') S.voiceTwo = g.toy_voice_two;
    if (typeof g.toy_tts_model === 'string') S.ttsModel = g.toy_tts_model;
    if (typeof g.toy_tts_format === 'string') S.ttsFormat = g.toy_tts_format;
    if (typeof g.toy_tts_speed === 'number') S.ttsSpeed = clamp(g.toy_tts_speed, 0.5, 1.5);
    if (typeof g.toy_tts_modelhdr === 'string' && g.toy_tts_modelhdr) S.ttsModelHdr = g.toy_tts_modelhdr;
    if (typeof g.toy_tts_reffield === 'string' && g.toy_tts_reffield) S.ttsRefField = g.toy_tts_reffield;
    if (typeof g.toy_tts_nomodel === 'boolean') S.ttsNoModelHdr = g.toy_tts_nomodel;
    if (typeof g.toy_tts_extra === 'string') S.ttsExtraHdrs = g.toy_tts_extra;
    if (['low', 'balanced', 'normal'].indexOf(g.toy_tts_latency) >= 0) S.ttsLatency = g.toy_tts_latency;
    if (typeof g.toy_tts_langboost === 'boolean') S.ttsLangBoost = g.toy_tts_langboost;
    /* 音色簿：只收形状对的条目，别让一段坏数据把整个下拉框搞崩。
       name 必填，id 允许为空（存过但还没填 ID 的情况）。 */
    if (Object.prototype.toString.call(g.toy_voicebook) === '[object Array]') {
      var bk = [];
      for (var bi = 0; bi < g.toy_voicebook.length && bk.length < 60; bi++) {
        var be = g.toy_voicebook[bi];
        if (!be || typeof be !== 'object') continue;
        var bn = String(be.name == null ? '' : be.name).trim().slice(0, 16);
        if (!bn) continue;
        bk.push({
          name: bn,
          id: String(be.id == null ? '' : be.id).trim(),
          model: String(be.model == null ? '' : be.model).trim(),
          format: String(be.format == null ? 'mp3' : be.format).trim() || 'mp3',
          speed: (typeof be.speed === 'number' ? clamp(be.speed, 0.5, 1.5) : 1)
        });
      }
      S.voiceBook = bk;
    }
    if (typeof g.toy_out_vol === 'number') S.voiceVol = clamp(g.toy_out_vol, 0, 100);
    if (typeof g.toy_out_auto === 'boolean') S.voiceAuto = g.toy_out_auto;
    /* 预热：只有用户亲手改过（toy_out_warmset）才沿用存档值。
       老存档里存的是旧默认 true，直接用会替用户继续花额度，所以那种情况落回新默认 false。 */
    if (g.toy_out_warmset === true) { S.warmTouched = true; if (typeof g.toy_out_warm === 'boolean') S.voiceWarm = g.toy_out_warm; }
    if (typeof g.toy_out_ai === 'boolean') S.voiceAI = g.toy_out_ai;
    if (typeof g.toy_out_haptap === 'boolean') S.hapticTap = g.toy_out_haptap;
    if (typeof g.toy_out_hapfol === 'boolean') S.hapticFollow = g.toy_out_hapfol;
    if (typeof g.toy_out_audio === 'boolean') S.audio = g.toy_out_audio;
    if (VOICE_IDS.indexOf(g.toy_out_voice) >= 0) S.voice = g.toy_out_voice;
  }

  function restore() {
    /* 先恢复与聊天无关的接口配置 —— 它在酒馆未就绪时也要能读到（localStorage 兜底），
       所以这一步放在 BRIDGE.ready 判断之前。 */
    restoreGlobal();
    if (!BRIDGE.ready) return;
    var v0 = BRIDGE.getVars('chat') || {}, v = {};
    Object.keys(v0).forEach(function (k) {
      if (CHAT_TO_GLOBAL[k] && GLOBAL_SEEN[CHAT_TO_GLOBAL[k]]) return;   // 全局已有新值，旧聊天里的不算
      v[k] = v0[k];
    });
    if (typeof v.toy_cfg_drive === 'string') S.drive = v.toy_cfg_drive;
    if (typeof v.toy_cfg_inject === 'boolean') S.inject = v.toy_cfg_inject;
    if (typeof v.toy_cfg_cd === 'number') S.cd = v.toy_cfg_cd;
    if (typeof v.toy_cfg_gain === 'number') S.gain = v.toy_cfg_gain;
    if (typeof v.toy_cfg_reset === 'boolean') S.resetOnPeak = v.toy_cfg_reset;
    if (typeof v.toy_cfg_hold === 'boolean') S.hold = v.toy_cfg_hold;
    if (typeof v.toy_cfg_dashrate === 'number') S.dashRate = clamp(v.toy_cfg_dashrate, 0.1, 1);
    if (typeof v.toy_cfg_recfreq === 'boolean') S.recFreq = v.toy_cfg_recfreq;
    if (typeof v.toy_cfg_freeze === 'boolean') S.freezeOnGen = v.toy_cfg_freeze;
    if (typeof v.toy_cfg_managewb === 'boolean') S.manageWb = v.toy_cfg_managewb;
    if (v.toy_cfg_sendmode === 'slash' || v.toy_cfg_sendmode === 'generate') S.sendMode = v.toy_cfg_sendmode;
    if (v.toy_cfg_target === 'user' || v.toy_cfg_target === 'char' || v.toy_cfg_target === 'self') S.target = v.toy_cfg_target;
    if (typeof v.toy_cfg_holder === 'string') S.holder = v.toy_cfg_holder.trim().slice(0, 24);
    if (hasDev(v.toy_cfg_dev)) S.dev = v.toy_cfg_dev;
    if (v.toy_cfg_body === 'male' || v.toy_cfg_body === 'female') S.body = v.toy_cfg_body;
    // 老聊天里没有这个键，缺失时保持默认（直写），不改变已有存档的行为
    if (typeof v.toy_cfg_explicit === 'boolean') S.explicit = v.toy_cfg_explicit;
    if (typeof v.toy_cfg_begdocile === 'boolean') S.begDocile = v.toy_cfg_begdocile;
    /* 自动反应改成默认关闭。这里的迁移有点绕，值得说明：
       老存档里 auto 是 true，而它多半不是用户选的 —— 是旧默认值被顺手写进了存档。
       所以不能一律沿用，否则"改成默认关"对老用户等于没生效，而他们才是最该被省额度的。
       办法是记住"这个开关是从哪个版本开始由用户自己管的"（toy_cfg_autoset 存版本号）：
         · 标记缺失或早于 AUTO_DEFAULT_FROM → 存档里的值只是旧默认，丢掉，走新默认（关）；
         · 标记不早于它 → 用户在新规则下亲手设过，沿用。
       标记在首次运行时补写成本版号，之后不再变。 */
    var autoSetFrom = (typeof v.toy_cfg_autoset === 'string') ? v.toy_cfg_autoset : '';
    if (autoSetFrom && !newerThan(autoSetFrom, AUTO_DEFAULT_FROM)) {   // 按数字比：字符串比较到 1.13.100 会错
      S.autoTouched = true;
      if (typeof v.toy_cfg_auto === 'boolean') S.auto = v.toy_cfg_auto;
    } else {
      S.auto = false;         // 旧默认留下的值：不是用户选的，不认
      S.autoTouched = false;
      AUTO_SET_STAMP = VERSION;
    }
    // 三个输出开关原先没有持久化，每次重载都会弹回默认值，一并补上
    if (typeof v.toy_cfg_haptap === 'boolean') S.hapticTap = v.toy_cfg_haptap;
    if (typeof v.toy_cfg_hapfol === 'boolean') S.hapticFollow = v.toy_cfg_hapfol;
    if (typeof v.toy_cfg_audio === 'boolean') S.audio = v.toy_cfg_audio;
    if (typeof v.toy_cfg_mode === 'string' && modeExists(v.toy_cfg_mode)) S.mode = v.toy_cfg_mode;
    if (typeof v.toy_cfg_freq === 'number') S.freq = clamp(v.toy_cfg_freq, 1, 100);
    if (typeof v.toy_cfg_pow === 'number') S.pow = clamp(v.toy_cfg_pow, 1, 100);

    // 语音（VOC）。这些也是新键，老聊天里没有 —— 缺失一律保持默认（关），
    // 不动已有存档的行为；要开语音得自己到设置页开一次。
    if (VOICE_IDS.indexOf(v.toy_cfg_voice) >= 0) S.voice = v.toy_cfg_voice;
    if (typeof v.toy_cfg_voicevol === 'number') S.voiceVol = clamp(v.toy_cfg_voicevol, 0, 100);
    if (typeof v.toy_cfg_voiceauto === 'boolean') S.voiceAuto = v.toy_cfg_voiceauto;
    if (typeof v.toy_cfg_voiceai === 'boolean') S.voiceAI = v.toy_cfg_voiceai;
    if (typeof v.toy_cfg_warmset === 'boolean') S.warmTouched = v.toy_cfg_warmset;
    if (S.warmTouched && typeof v.toy_cfg_voicewarm === 'boolean') S.voiceWarm = v.toy_cfg_voicewarm;
    if (typeof v.toy_cfg_proxy === 'string') S.ttsProxy = v.toy_cfg_proxy;   // 已废弃键，同上
    // 传输方式与令牌。老聊天里的 'relay' 折算成 'direct'：那一档（本机转发）已经拆掉，
    // 折算成直连最安全 —— 用户想走作者中转，点一次开关就行。
    if (v.toy_cfg_transport === 'af') S.ttsTransport = 'af';
    else if (v.toy_cfg_transport === 'direct' || v.toy_cfg_transport === 'relay') S.ttsTransport = 'direct';
    if (typeof v.toy_cfg_ttskey === 'string') S.ttsKey = v.toy_cfg_ttskey;
    // 高级项：老聊天里没有，缺省保持标准 Fish 协议的行为
    if (typeof v.toy_cfg_modelhdr === 'string' && v.toy_cfg_modelhdr) S.ttsModelHdr = v.toy_cfg_modelhdr;
    if (typeof v.toy_cfg_reffield === 'string' && v.toy_cfg_reffield) S.ttsRefField = v.toy_cfg_reffield;
    if (typeof v.toy_cfg_nomodel === 'boolean') S.ttsNoModelHdr = v.toy_cfg_nomodel;
    if (typeof v.toy_cfg_extra === 'string') S.ttsExtraHdrs = v.toy_cfg_extra;
    if (['low', 'balanced', 'normal'].indexOf(v.toy_cfg_latency) >= 0) S.ttsLatency = v.toy_cfg_latency;
    /* 平台白名单以前写死成 ['fish','openai','custom']，漏了 minimax ——
       结果：选过 MiniMax 的人一换聊天，平台就被悄悄退回 Fish，音色与请求体全错。
       现在从 PLATFORMS 自己取键，加平台不用再记得改这里。 */
    if (Object.prototype.hasOwnProperty.call(PLATFORMS, v.toy_cfg_platform)) S.ttsPlatform = v.toy_cfg_platform;
    if (typeof v.toy_cfg_langboost === 'boolean') S.ttsLangBoost = v.toy_cfg_langboost;
    if (typeof v.toy_cfg_target_url === 'string') S.ttsTarget = v.toy_cfg_target_url;
    if (typeof v.toy_cfg_ttsvoice === 'string') S.ttsVoice = v.toy_cfg_ttsvoice;    // 旧存档里的 toy_cfg_ttsvoicet（调教音色）已废弃：音色合并成一套，读到了也不采用
    if (typeof v.toy_cfg_ttsmodel === 'string') S.ttsModel = v.toy_cfg_ttsmodel;
    if (typeof v.toy_cfg_ttsformat === 'string') S.ttsFormat = v.toy_cfg_ttsformat;
    if (typeof v.toy_cfg_ttsspeed === 'number') S.ttsSpeed = clamp(v.toy_cfg_ttsspeed, 0.5, 1.5);
    if (typeof v.toy_cfg_ttsauth === 'string') S.ttsAuth = v.toy_cfg_ttsauth;
  }

  /* =========================================================
   * 11. 酒馆事件监听
   * ======================================================= */
  function bindTavernEvents() {
    if (!BRIDGE.ready) return;
    // 新楼层到达 = 这一轮生成结束了，先把冻结解掉。
    // 注意这里不再把正文搬进面板：面板现在只显示心声，而心声是随正文一起
    // 生成、随即被剥掉的（正文落库时已经不含 <TOY>），从楼层里捞不到。
    // 正文本身就在聊天记录里躺着，不需要面板再复述一遍。
    BRIDGE.on(EVT.MSG_RECEIVED, function () {
      markIdle();
    });
    // 生成状态：AI 在回复中时不要调用 /trigger，酒馆会直接拦掉
    BRIDGE.on(EVT.GEN_STARTED, markBusy);
    BRIDGE.on(EVT.GEN_ENDED, markIdle);
    BRIDGE.on(EVT.GEN_STOPPED, markIdle);      // 被停止按钮打断
    BRIDGE.on(EVT.JS_GEN_STARTED, markBusy);   // 面板内 generate()
    BRIDGE.on(EVT.JS_GEN_ENDED, markIdle);
    BRIDGE.on(EVT.CHAT_CHANGED, function () { location.reload(); });
  }

  /* =========================================================
   * 12. 启动
   * ======================================================= */
  function boot() {
    BRIDGE.probe();
    restore();
    buildModes();
    bindSettings();
    bindVoice();      // restore 之后再刷一次：读档的值要反映到语音设置界面上
    paintHold();      // 两个闸门的初始外观也要跟着读档的值走
    paintModeLocks();
    markDurChip();
    ['#freq', '#pow', '#dur'].forEach(function (s) {
      var el = $(s);
      el.value = s === '#freq' ? S.freq : (s === '#pow' ? S.pow : S.limit);
      paintSlider(el);
    });
    $('#modes').querySelectorAll('.mode').forEach(function (n) {
      n.classList.toggle('on', n.dataset.id === S.mode);
    });
    fitCanvas();
    ONWIN('resize', fitCanvas);
    ONWIN('orientationchange', function () { setTimeout(fitCanvas, 120); });

    // 全屏 / 窗口切换：窄屏本来是全屏，宽屏默认窗口，可手动切
    var shellEl = $('#shell'), sizeBtn = $('#btn-size'), fitSw = $('#s-fit'), FIT_KEY = 'toylink_fit_mode';
    function applyFit(on) {
      shellEl.classList.toggle('fit', on);
      if (sizeBtn) sizeBtn.textContent = on ? '⤡' : '⤢';
      if (fitSw) fitSw.classList.toggle('on', on);
      setTimeout(fitCanvas, 60);
    }
    // 首开规则要和脚本版 layout() 的一致：没存过偏好时，窄屏（<860）默认全屏。
    // 以前这里默认 false，会把脚本版刚加上的 fit 摘掉——面板是满屏的、状态却是「窗口」，⤢ 要点两次才缩小。
    var fitOn = false;
    try {
      var fitSaved = localStorage.getItem(FIT_KEY);
      fitOn = fitSaved === null ? (viewport().w < 860) : fitSaved === '1';   // 构建版把这里换成酒馆页面的宽度
    } catch (e) { /* noop */ }
    applyFit(fitOn);
    // 顶栏 ⤢ 和设置页的「全屏」开关是同一个动作。手机上顶栏可能被系统状态栏盖住（2026-10-12 玩家反馈：
    // 满屏、退不出来），所以设置页里也放一个，底栏「设置」永远点得到。
    function toggleFit() {
      fitOn = !shellEl.classList.contains('fit');
      applyFit(fitOn);
      try { localStorage.setItem(FIT_KEY, fitOn ? '1' : '0'); } catch (e) { /* noop */ }
      toast(fitOn ? '全屏模式' : '窗口模式');
    }
    if (sizeBtn) sizeBtn.addEventListener('click', toggleFit);
    if (fitSw) fitSw.addEventListener('click', toggleFit);

    var dot = $('#dot'), txt = $('#conn-txt');
    if (BRIDGE.ready) {
      dot.classList.add('live');
      txt.textContent = '已连接酒馆';
      bindTavernEvents();
      syncVars(true);
      syncWorldbook(true);   // 通用设定：写进世界书并挂到当前角色卡
      $('#env-hint').textContent = '运行环境：酒馆助手 iframe，接口就绪。装置状态写进聊天变量，并作为系统提示注入给角色；回复走' +
        (S.drive === 'inner' ? '面板内生成' : '酒馆聊天') + '。';
    } else {
      dot.classList.add('demo');
      txt.textContent = '演示模式';
      $('#env-hint').textContent = '未检测到酒馆助手接口，当前为演示模式：界面、波形、触觉可用，角色回复由本地模板模拟。' +
        '把本文件作为前端界面载入酒馆助手后即可接入真实角色。';
      toast('演示模式：未检测到酒馆助手', 2600);
    }

    // 首次交互解锁音频
    var unlock = function () {
      if (S.audio) AUD.start();
      OFFWIN('touchstart', unlock);
      OFFWIN('click', unlock);
    };
    ONWIN('touchstart', unlock, { passive: true });
    ONWIN('click', unlock);

    // 页面隐藏时停输出，避免后台白震
    ONDOC('visibilitychange', function () {
      if (document.hidden) {
        HAP.kill();
        AUD.update(0, hz());
      }
    });
    ONWIN('pagehide', function () {
      HAP.kill();
      // 切聊天会重载脚本 iframe；两个 AudioContext 建在酒馆页面上，不关就一直挂在那里
      try { if (AUD.ctx) { AUD.ctx.close(); AUD.ctx = null; } } catch (e) { /* noop */ }
      try { VOC.close(); } catch (e) { /* noop */ }
    });

    render();
    wakeLoop();
    setInterval(heartbeat, 50);   // rAF 被挂起时的兜底心跳；装置关着时自动降到 ~4Hz

    // 后台问一次有没有新版，不阻塞启动、失败也不影响使用
    /* 自更新：构建版由外层在启动最前跑过一次，这里不再重复 */

    var verEl = $('#ver-hint');
    if (verEl) verEl.textContent = 'TOY·LINK v' + VERSION + '（' + BUILD_DATE + '）';
    var brandVer = $('#brand-ver');
    if (brandVer) brandVer.textContent = 'v' + VERSION;

    // 兜底：某些环境里 iframe 晚于脚本就绪
    if (!BRIDGE.ready) {
      setTimeout(function () {
        if (BRIDGE.probe()) {
          $('#dot').classList.remove('demo');
          $('#dot').classList.add('live');
          $('#conn-txt').textContent = '已连接酒馆';
          restore(); bindSettings(); bindTavernEvents(); syncVars(true); syncWorldbook(true);
          $('#env-hint').textContent = '运行环境：酒馆助手 iframe，接口就绪。';
        }
      }, 1200);
    }
  }

  /* =========================================================
   * 自更新
   *
   * 脚本库里存的本来就是「本体自己」。启动时问一次版本指针，发现比手上这个
   * 新，就把新本体写回脚本库 —— 下次启动直接跑新版，不再需要网络。
   *
   * 为什么是这个方案，而不是一行 `import '网址'`：
   *   · jsDelivr 给固定网址的响应头是 max-age=604800，浏览器缓存 7 天，
   *     purge 只清 CDN 那一层，够不着浏览器 → 热更新失效。
   *   · GitHub raw 缓存只有 5 分钟，但给的是 text/plain 加 nosniff，
   *     而 import 按规范要求 JavaScript 的 MIME，浏览器直接拒绝执行。
   * 两头都堵，所以只能自己拿 fetch 拉（fetch 不看 MIME），再写回脚本库。
   * 好处是更新过的本体落在本地，之后断网也照常跑。
   *
   * 只在酒馆助手脚本环境里生效；当前端卡加载时这些接口不存在，直接跳过。
   * ======================================================= */
  /* 指针也要多源：jsDelivr 会长时间缓存 version.txt 本身，只问它一家会把
     "缓存没翻页"误判成"没有新版"。顺序按"翻页最快"排，raw 放最后（可能被墙）。 */
  var UPD_POINTERS = [
    'https://fastly.jsdelivr.net/gh/fJForever/toy-link@main/version.txt',
    'https://cdn.jsdelivr.net/gh/fJForever/toy-link@main/version.txt',
    'https://raw.githubusercontent.com/fJForever/toy-link/main/version.txt'
  ];
  var UPD_BASES = [
    'https://cdn.jsdelivr.net/gh/fJForever/toy-link@main/dist/',
    'https://fastly.jsdelivr.net/gh/fJForever/toy-link@main/dist/',
    'https://raw.githubusercontent.com/fJForever/toy-link/main/dist/'
  ];

  // 脚本里这些是全局函数；导出到 TavernHelper 的也试一下，两边都探
  function thai(name) {
    try { if (typeof window[name] === 'function') return window[name]; } catch (e) { /* noop */ }
    try {
      if (typeof TavernHelper !== 'undefined' && TavernHelper && typeof TavernHelper[name] === 'function') {
        return TavernHelper[name].bind(TavernHelper);
      }
    } catch (e) { /* noop */ }
    return null;
  }

  function newerThan(mine, theirs) {
    var a = String(mine).split('.').map(Number);
    var b = String(theirs).split('.').map(Number);
    for (var i = 0; i < 3; i++) {
      var x = a[i] || 0, y = b[i] || 0;
      if (y > x) return true;
      if (y < x) return false;
    }
    return false;
  }

  function fetchText(url, ms) {
    var ctl = (typeof AbortController !== 'undefined') ? new AbortController() : null;
    var timer = ctl ? setTimeout(function () { ctl.abort(); }, ms) : null;
    return fetch(url, { cache: 'no-store', signal: ctl ? ctl.signal : undefined }).then(function (r) {
      if (timer) clearTimeout(timer);
      if (!r.ok) throw new Error('HTTP ' + r.status);
      return r.text();
    }, function (e) {
      if (timer) clearTimeout(timer);
      throw e;
    });
  }

  /* 认出"脚本库里哪一条是自己"。
     ① getScriptId() —— 接口是真的，但它只在脚本内可用，**不在脚本里调用会抛错**，
        所以必须包 try，不能拿"函数存不存在"当判断依据。
     ② 退一步用 getScriptName() 拿自己的名字去脚本树里对。名字可能被用户改过，
        所以再加一道"内容是本体那种长度"的确认；脚本库里本体只有一条，够用。 */
  function myHandles() {
    var ids = {}, names = {};
    var idFn = thai('getScriptId');
    if (idFn) { try { var s = idFn(); if (s) ids[s] = 1; } catch (e) { /* 不在脚本内，正常 */ } }
    var nmFn = thai('getScriptName');
    if (nmFn) { try { var n = nmFn(); if (n) names[n] = 1; } catch (e) { /* noop */ } }
    return { ids: ids, names: names, ok: Object.keys(ids).length > 0 || Object.keys(names).length > 0 };
  }

  function isMe(it, h) {
    if (!it) return false;
    if (h.ids[it.id]) return true;
    return !!(h.names[it.name] && String(it.content || '').length > 5000);
  }

  /* 把自己这个脚本的 content 换成新版本。
     逐个 scope 试，只在真的找到自己那条时才改，其余原样返回。 */
  function writeBackSelf(code, done) {
    var upd = thai('updateScriptTreesWith');
    var trees = thai('getScriptTrees');
    if (!upd || !trees) { done(false, '这个环境没有脚本管理接口'); return; }
    var h = myHandles();
    if (!h.ok) { done(false, '拿不到自己的脚本 id / 名称'); return; }

    /* 走一遍所有作用域，逐个问"我这条在不在里面"。
       用 getScriptTrees 判断、再整树写回，避免改到别的脚本。 */
    var scopes = ['global', 'preset', 'character'];
    var i = 0;
    (function nextScope() {
      if (i >= scopes.length) { done(false, '三个作用域里都没找到自己'); return; }
      var scope = scopes[i++];
      var hit = false;
      try {
        var list = trees({ type: scope }) || [];
        (function walk(a) {
          for (var k = 0; k < a.length; k++) {
            var it = a[k];
            if (!it) continue;
            if (it.type === 'folder' && it.scripts) walk(it.scripts);
            else if (isMe(it, h)) hit = true;
          }
        })(list);
      } catch (e) { /* 这个作用域不存在或没权限，换下一个 */ }
      if (!hit) { nextScope(); return; }

      try {
        upd(function (script_trees) {
          (function walk(a) {
            if (!a || !a.length) return;
            for (var k = 0; k < a.length; k++) {
              var it = a[k];
              if (!it) continue;
              if (it.type === 'folder' && it.scripts) walk(it.scripts);
              else if (isMe(it, h)) it.content = code;
            }
          })(script_trees);
          return script_trees;
        }, { type: scope });
        done(true, scope);
      } catch (e) { done(false, '写回 ' + scope + ' 失败'); }
    })();
  }

  function selfUpdate() {
    // 每次启动都自报一次版本，方便确认"我到底在跑哪一版"
    console.log('[TOY·LINK] v' + VERSION + ' 启动，检查更新…');
    // 不在脚本里（前端卡 / 演示模式）就没必要跑
    if (!thai('updateScriptTreesWith') || !thai('getScriptTrees')) {
      console.log('[TOY·LINK] 这个环境没有脚本库接口，跳过自更新（前端卡属正常）');
      return;
    }

    /* 指针文件也要逐个源试。
       踩过的坑：jsDelivr 对 version.txt 的响应头 max-age=604800，改完之后
       它还照旧发上一个版本号长达十几分钟。早先只在第一个源上取一次指针，
       于是"指针没翻页"被当成"没有新版"，后面两个已经翻页的源根本没机会问。
       现在谁先给出更新的版本号就用谁。 */
    var best = '';
    var pi = 0;
    (function nextPointer() {
      if (pi >= UPD_POINTERS.length) { afterPointer(); return; }
      var u = UPD_POINTERS[pi++];
      fetchText(u, 6000).then(function (txt) {
        var v = String(txt || '').trim();
        if (/^[0-9]+\.[0-9]+\.[0-9]+$/.test(v) && newerThan(best || '0.0.0', v)) best = v;
        // 已经拿到比手头这个新的了，不用再问别的源
        if (best && newerThan(VERSION, best)) { afterPointer(); return; }
        nextPointer();
      }, function (e) {
        console.log('[TOY·LINK] 指针源失败 ' + u + '：' + ((e && e.message) || e));
        nextPointer();
      });
    })();

    function afterPointer() {
      var remote = best;
      if (!remote) { console.log('[TOY·LINK] 拿不到版本指针，保持当前版本'); return; }
      if (!newerThan(VERSION, remote)) { console.log('[TOY·LINK] 已是最新（线上 ' + remote + '）'); return; }

      console.log('[TOY·LINK] 发现新版 ' + remote + '（当前 ' + VERSION + '），准备更新');
      var file = 'TOY-LINK-' + remote + '.js';
      var j = 0;
      (function tryNext() {
        if (j >= UPD_BASES.length) { console.log('[TOY·LINK] 所有源都不通，保持当前版本'); return; }
        var url = UPD_BASES[j++] + file;
        fetchText(url, 15000).then(function (code) {
          // 宁可停在当前版本，也不把半截内容写进用户的脚本库
          if (!code || code.length < 50000) throw new Error('内容异常 ' + (code ? code.length : 0) + ' 字符');
          /* 只看长度不够：运营商劫持页、门户登录页也能有 50KB，写进去脚本就永久变砖（连自更新都跑不了）。
             必须认得出是本体、版本号对得上，并且能编译。 */
          if (code.indexOf('function TOYLINK_BOOT') === -1 || code.indexOf("var VERSION = '" + remote + "'") === -1) {
            throw new Error('取到的不是 v' + remote + ' 本体');
          }
          try { new Function(code); } catch (e) {
            // 酒馆开了禁止 eval 的 CSP 时 new Function 本身就会被拦（EvalError），那不代表代码坏了：跳过这一步，靠上面两道认人
            var csp = (typeof EvalError !== 'undefined' && e instanceof EvalError) || /Content Security Policy|unsafe-eval/i.test(String((e && e.message) || e));
            if (!csp) throw new Error('v' + remote + ' 编译不过：' + ((e && e.message) || e));
          }
          writeBackSelf(code, function (ok, where) {
            if (ok) {
              console.log('[TOY·LINK] 已写入脚本库（' + where + '），刷新页面生效');
              try { toastr.info('TOY·LINK 已更新到 v' + remote + '，刷新页面生效', 'TOY·LINK'); } catch (e) { /* noop */ }
            } else {
              console.log('[TOY·LINK] 写回失败：' + where);
            }
          });
        }).catch(function (e) {   // 用 catch 而不是 then 的第二个参数：上面成功回调里抛的错也要接住、换下一个源
          console.log('[TOY·LINK] 源失败 ' + url + '：' + ((e && e.message) || e));
          tryNext();
        });
      })();
    }
  }

  if (document.readyState === 'loading') {
    ONDOC('DOMContentLoaded', boot);
  } else {
    boot();
  }
})();
  /* ==================== 同源逻辑结束 ==================== */

  /* ---------- 定位：悬浮窗 / 全屏 ----------
   * 全部用内联样式算，不走 CSS 媒体查询。
   * 默认悬浮窗：固定在视口一角、可拖动，酒馆其他地方照常点击与输入。
   */
  var sizeBtn = ROOT.querySelector("#btn-size");
  var FIT_KEY = "toylink_fit_mode", POS_KEY = "toylink_win_pos";

  /* 视口尺寸。这里必须层层兜底 —— 脚本跑在酒馆助手的 iframe 里，
     而 iframe 有可能是隐藏的（resolvePage 回落到 self 时）。隐藏 iframe 的
     innerWidth/clientWidth 都是 0，拿 0 去算布局会把面板定成 left=0;width=0：
     贴在左上角、内容一个点不到。宁可回落到一个保守的默认值，也不要 0。 */
  function viewport() {
    function pick() {
      for (var i = 0; i < arguments.length; i++) {
        var v = arguments[i];
        if (typeof v === "number" && isFinite(v) && v > 0) return v;
      }
      return 0;
    }
    var w = pick(WIN.innerWidth, DOC.documentElement && DOC.documentElement.clientWidth,
      (typeof window !== "undefined" ? window.innerWidth : 0),
      (typeof window !== "undefined" && window.document.documentElement)
        ? window.document.documentElement.clientWidth : 0)
      || 360;
    var h = pick(WIN.innerHeight, DOC.documentElement && DOC.documentElement.clientHeight,
      (typeof window !== "undefined" ? window.innerHeight : 0),
      (typeof window !== "undefined" && window.document.documentElement)
        ? window.document.documentElement.clientHeight : 0)
      || 640;
    return { w: w, h: h };
  }
  function lsGet(k) { try { return localStorage.getItem(k); } catch (e) { return null; } }
  function lsSet(k, v) { try { localStorage.setItem(k, v); } catch (e) { /* noop */ } }

  var savedPos = (function () {
    var s = lsGet(POS_KEY);
    if (!s) return null;
    var a = s.split(",");
    if (a.length !== 2) return null;
    var x = parseFloat(a[0]), y = parseFloat(a[1]);
    if (!isFinite(x) || !isFinite(y)) return null;
    /* 明显不可用的旧记录直接丢掉：面板宽 280-368，x 落在 0-10 之间一定是当年
       用一个错的视口宽度算出来的（比如隐藏 iframe 的 0），留着就会永远贴左边。 */
    if (x < 12 && y < 12) return null;
    return { left: x, top: y };
  })();

  var layingOut = false;   // layout 末尾会广播 resize，而 layout 自己也挂在 resize 上：不设闸就无限递归（控制台成串的 Maximum call stack）
  function layout() {
    if (!shellEl || layingOut) return;
    layingOut = true;
    try { layoutInner(); } finally { layingOut = false; }
  }
  function layoutInner() {
    var vp = viewport();
    // 窄屏第一次打开默认全屏，之后听用户的
    if (lsGet(FIT_KEY) === null && vp.w < 860) shellEl.classList.add("fit");
    /* 视口小到放不下一个窗口时，宁可全屏也不摆一个宽度接近 0 的窗口 ——
       那样面板会贴在左边、里面的按钮全点不到，等于把整个界面废掉。
       只是这一次按全屏摆，不写进 FIT_KEY、也不改 fit 类：手机横屏一下高度不到 320，
       以前会把用户自己选的「窗口」永久改成全屏，而设置页的开关和 ⤢ 图标都不知道。 */
    var tooSmall = (vp.w < 300 || vp.h < 320);
    var full = shellEl.classList.contains("fit") || tooSmall;
    shellEl.style.position = "fixed";
    shellEl.style.pointerEvents = "auto";
    if (full) {
      shellEl.style.left = "0px"; shellEl.style.top = "0px";
      shellEl.style.right = "auto"; shellEl.style.bottom = "auto";
      shellEl.style.width = vp.w + "px";
      shellEl.style.height = vp.h + "px";
      shellEl.style.maxHeight = "none";
      shellEl.style.minHeight = "0px";
      shellEl.style.borderRadius = "0px";
      shellEl.style.border = "0";
      shellEl.style.boxShadow = "none";
    } else {
      var w = Math.max(280, Math.min(368, vp.w - 20));
      var h = Math.max(300, Math.min(Math.round(vp.h * 0.78), vp.h - 120, 640));
      shellEl.style.width = w + "px";
      shellEl.style.height = h + "px";
      shellEl.style.maxHeight = h + "px";
      shellEl.style.minHeight = "0px";   // 样式表里 #shell{min-height:100vh} 会压过上面的高度：手机上窗口模式底栏整排跑出屏幕
      shellEl.style.borderRadius = "20px";
      shellEl.style.border = "1px solid rgba(232,214,236,.10)";
      shellEl.style.boxShadow = "0 24px 70px rgba(0,0,0,.72)";
      /* 上一次拖到的位置只有在"当前视口下真的放得下"时才认。
         以前是一票否决：savedPos 存在就永远用它，于是窗口变宽之后
         面板还钉在当年那个左边的坐标上，看起来就是"贴在左边"。 */
      var maxL = vp.w - w - 4, maxT = vp.h - h - 4;
      var useSaved = !!savedPos && maxL >= 0 && maxT >= 0;
      var L, T;
      if (useSaved) {
        L = Math.min(Math.max(4, savedPos.left), maxL);
        T = Math.min(Math.max(4, savedPos.top), maxT);
        // 纠偏后的位置与记录差得多，说明那条记录已经过期，就地修掉
        if (Math.abs(L - savedPos.left) > 24 || Math.abs(T - savedPos.top) > 24) {
          savedPos = { left: L, top: T };
          lsSet(POS_KEY, L + "," + T);
        }
      } else {
        L = Math.max(8, vp.w - w - 18);
        T = Math.max(8, vp.h - h - 88);
      }
      shellEl.style.left = L + "px";
      shellEl.style.top = T + "px";
      shellEl.style.right = "auto";
      shellEl.style.bottom = "auto";
    }
    try { WIN.dispatchEvent(new Event("resize")); } catch (e) { /* noop */ }
  }

  /* ---------- 拖动窗身 ---------- */
  var bar = ROOT.querySelector(".bar");
  if (bar) {
    bar.style.cursor = "grab";
    bar.style.touchAction = "none";
    var dg = { on: false, ox: 0, oy: 0 };
    bar.addEventListener("pointerdown", function (e) {
      if (!shellEl || shellEl.classList.contains("fit")) return;
      if (e.target && e.target.closest && e.target.closest("button")) return;
      var r = shellEl.getBoundingClientRect();
      dg.on = true; dg.ox = e.clientX - r.left; dg.oy = e.clientY - r.top;
      bar.style.cursor = "grabbing";
      try { bar.setPointerCapture(e.pointerId); } catch (err) { /* noop */ }
    });
    bar.addEventListener("pointermove", function (e) {
      if (!dg.on) return;
      var vp = viewport();
      var w = shellEl.offsetWidth, h = shellEl.offsetHeight;
      var L = Math.min(Math.max(4, e.clientX - dg.ox), Math.max(4, vp.w - w - 4));
      var T = Math.min(Math.max(4, e.clientY - dg.oy), Math.max(4, vp.h - h - 4));
      shellEl.style.left = L + "px";
      shellEl.style.top = T + "px";
      savedPos = { left: L, top: T };
      lsSet(POS_KEY, Math.round(L) + "," + Math.round(T));
    });
    var dgEnd = function () {
      if (!dg.on) return;
      dg.on = false;
      bar.style.cursor = "grab";
    };
    bar.addEventListener("pointerup", dgEnd);
    bar.addEventListener("pointercancel", dgEnd);
  }

  layout();
  ONWIN("resize", layout);
  ONWIN("orientationchange", function () { setTimeout(layout, 120); });
  if (sizeBtn) sizeBtn.addEventListener("click", function () { setTimeout(layout, 0); });
  var fitSw = ROOT.querySelector("#s-fit");   // 设置页的「全屏」开关和 ⤢ 是同一个动作，尺寸同样要重算
  if (fitSw) fitSw.addEventListener("click", function () { setTimeout(layout, 0); });

  /* ---------- 自助复位 ----------
   * 面板贴在角落、或者位置怎么都不对时，在浏览器控制台敲这一行即可：
   *     __TOYLINK__.resetLayout()
   * 它会清掉记下来的窗口位置和全屏偏好，然后按当前视口重算一次。
   * 之所以要留这个口子：位置是存在 localStorage 里的，一旦存进一个坏值，
   * 光刷新页面是出不来的 —— 用户会被锁在一个自己修不好的状态里。 */
  TK_API.resetLayout = function () {
    try { localStorage.removeItem(POS_KEY); } catch (e) { /* noop */ }
    try { localStorage.removeItem(FIT_KEY); } catch (e) { /* noop */ }
    savedPos = null;
    var vp = viewport();
    if (vp.w < 300 || vp.h < 320) shellEl.classList.add("fit");
    else shellEl.classList.remove("fit");
    layout();
    console.log("[TOY·LINK] 已复位布局：view " + vp.w + "x" + vp.h
      + " | fit=" + shellEl.classList.contains("fit")
      + " | left=" + (shellEl.style.left || "auto"));
    return "已复位";
  };

  /* ---------- 开合 ---------- */
  // 同一次会话里记住上次的收起状态，避免切聊天就又弹一脸
  /* 这几样（opened / apply / open / collapse / toggle / 收起按钮）已经在函数开头
     定义并绑定过了 —— 那里是"必须最先跑通"的一段，别在这里重复定义：
     重复声明会让后面这份覆盖前面那份，等于把最早的保险拆掉。 */
  tkBind(toggle);   // 点按开合，拖动吸边

  // 装置运行时的动态由悬浮球自己的循环直接读 S（见 TOY_BALL_RUNTIME），这里不用再轮询面板

  window.__TOYLINK__ = {
    version: "1.13.46",
    host: host, root: root, ball: ball, page: PAGE,
    resetLayout: TK_API.resetLayout,   // 面板位置不对劲时，控制台敲 __TOYLINK__.resetLayout()
    open: open, collapse: collapse, toggle: toggle,
    /* 面板里的运行日志。手机上没有控制台，语音出问题时这份日志就是唯一的现场。
       走一层 window 而不是直接引用闭包里的 VOC —— 闭包引用在宿主里未必解析得到。 */
    logText: function () { try { return WIN.__toylink_log.logText(); } catch (e) { return "(日志取不到: " + e.message + ")"; } },
    logCount: function () { try { return WIN.__toylink_log.logCount(); } catch (e) { return 0; } },
    stop: function () {
      try { if (NAV.vibrate) NAV.vibrate(0); } catch (e) { /* noop */ }
      try { tkDispose(); } catch (e) { /* noop */ }
      try { OFFALL(); } catch (e) { /* noop */ }
      var h = BYID("__toylink_host__"); if (h) h.remove();
      var b = BYID("__toylink_ball__"); if (b) b.remove();
      window.__TOYLINK__ = null;
    }
  };

  /* ---------- 脚本按钮 ----------
   * 点击事件的通道是 getButtonEvent(name) 返回的事件类型，
   * 不能用 eventOnButton（那是脚本设置里的按键绑定）。
   */
  function pickApi(name) {
    try { if (typeof window[name] === "function") return window[name]; } catch (e) { /* noop */ }
    try {
      if (typeof TavernHelper !== "undefined" && TavernHelper && typeof TavernHelper[name] === "function") {
        return TavernHelper[name].bind(TavernHelper);
      }
    } catch (e) { /* noop */ }
    try {
      var p = window.parent;
      if (p && p !== window && p.TavernHelper && typeof p.TavernHelper[name] === "function") {
        return p.TavernHelper[name].bind(p.TavernHelper);
      }
    } catch (e) { /* noop */ }
    return null;
  }

  try {
    var rsb = pickApi("replaceScriptButtons");
    if (rsb) { rsb([{ name: "TOY·LINK 控制器", visible: true }]); TK_API.btnOk = true; }

    var eon = pickApi("eventOn");
    var gbe = pickApi("getButtonEvent");
    if (eon && gbe) {
      eon(gbe("TOY·LINK 控制器"), function () { open(); });
    } else {
      // 极老版本没有 getButtonEvent 时留个念想
      var eob = pickApi("eventOnButton");
      if (eob) eob("TOY·LINK 控制器", function () { open(); });
    }
  } catch (e) {
    console.log("[TOY·LINK] 脚本按钮注册失败：", e);
  }
  if (!TK_API.btnOk) tkPref.hidden = false;   // 没按钮的环境里，球是唯一的门，不许藏

  /* ---------- 卸载清理 ---------- */
  var bye = function () {
    try { if (NAV.vibrate) NAV.vibrate(0); } catch (e) { /* noop */ }
    if (window.__TOYLINK__ && window.__TOYLINK__.stop) window.__TOYLINK__.stop();
  };
  ONWIN("pagehide", bye);

  apply();
  try { WIN.__toylink_ready = true; } catch (e) { /* noop */ }   // 走到这里才算启动完成

  console.log("[TOY·LINK] 已挂载到 " + (PAGE.via === "self" ? "脚本自身 iframe（未找到酒馆页面，界面可能不可见）" : "酒馆页面 via " + PAGE.via));
  setTimeout(function () {
    try {
      var hb = host.getBoundingClientRect();
      var sb = ROOT.querySelector("#shell").getBoundingClientRect();
      var dr = ROOT.querySelector("#v-device").getBoundingClientRect();
      var rg = ROOT.querySelector(".ring").getBoundingClientRect();
      console.log("[TOY·LINK] 尺寸 host " + Math.round(hb.width) + "x" + Math.round(hb.height)
        + " | shell " + Math.round(sb.width) + "x" + Math.round(sb.height)
        + " | stage " + Math.round(dr.width) + "x" + Math.round(dr.height)
        + " | ring " + Math.round(rg.width) + "x" + Math.round(rg.height)
        + " | dpr " + (WIN.devicePixelRatio || 1));
      /* 这一行是给"面板贴在左边 / 点不到"这类问题准备的：
         view 用的是算出来那个视口，shell 是最终落到页面上的大小。
         两个数对不上、或者 shell 宽度接近 0，看这行就知道卡在哪一步。 */
      var vpv = viewport();
      console.log("[TOY·LINK] 布局 view " + vpv.w + "x" + vpv.h
        + " | fit=" + shellEl.classList.contains("fit")
        + " | left=" + (shellEl.style.left || "auto")
        + " | 定位来源=" + (shellEl.style.left ? "内联（layout 算出来的）" : "CSS")
        + " | via=" + PAGE.via);
    } catch (e) { /* noop */ }
  }, 400);
}

// 酒馆页面可能尚未就绪
try {
  if (typeof $ === "function") { $(function () { TOYLINK_BOOT(); }); } else { TOYLINK_BOOT(); }
} catch (e) {
  console.error("[TOY·LINK] 启动失败，面板不会工作：", e);
}
/* 兜底自检：boot 若是半途抛错，面板会"看得见、全点不动"，
   而控制台里往往只有一行容易漏掉的红字。这里明确报出来。
   （外层 try/catch 抓不到 $(fn) 里的错误 —— jQuery 是异步调用的。） */
setTimeout(function () {
  if (!window.__TOYLINK__) {
    console.error("[TOY·LINK] 启动流程没有完成：window.__TOYLINK__ 不存在 —— "
      + "面板虽然可能已经画出来，但按钮全是死的。请把控制台里 TOY·LINK 相关的报错发出来。");
  }
}, 3000);
